INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合格", "is_correct": true, "explanation": "“合格”表示符合标准，与“都是合格产品”相符。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：有毒的产品不能算合格，与“都是合格产品”矛盾。"}, {"text": "假冒", "is_correct": false, "explanation": "语义：假冒产品不符合规定，与“都是合格产品”矛盾。"}, {"text": "残次", "is_correct": false, "explanation": "语义：残次品达不到标准，与“都是合格产品”矛盾。"}], "explanations": {"合格": "“合格”表示符合标准，与“都是合格产品”相符。", "有毒": "语义：有毒的产品不能算合格，与“都是合格产品”矛盾。", "假冒": "语义：假冒产品不符合规定，与“都是合格产品”矛盾。", "残次": "语义：残次品达不到标准，与“都是合格产品”矛盾。"}, "sentence_index": 6, "correct_answer": "合格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个答案很合格，老师给了满分。", "explanation": "这里应该用〈正确〉。“合格”指符合规定的标准，答案的对错应说“正确”。"}, {"text": "这次活动的时间很合格，正好是周末。", "explanation": "这里应该用〈恰当〉。“合格”指符合规定的标准，说时间选得好坏应用“恰当”，不说“合格”。"}, {"text": "这次假期很合格，我玩得很愉快。", "explanation": "这里应该用〈愉快〉。“合格”不用于形容假期或心情，应说“很愉快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批零件验收不合格，可以用了。", "corrected_sentence": "这批零件验收合格，可以用了。", "error_description": "错误在多了“不”。“不合格”与“可以用了”矛盾，应去掉“不”，说“验收合格，可以用了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批手机零件检测合格着，可以装机了。", "corrected_sentence": "这批手机零件检测合格，可以装机了。", "error_description": "错误在“合格”后加了“着”。表示结果已经完成应用“了”，不能用“着”，应说“检测合格，可以装机了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
