INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94605, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同在是在同一个地方，或在一起。", "primary_collocate": null, "pronunciation": "tóng zài", "ipa": "tʰʊŋ˧˥ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们两个人同在一个班学习。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我同在北京工作。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐和我同在一家公司上班。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们同在一个城市，常常见面。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子同在一间房子里玩。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和小王同在一栋楼里住。", "target_word": "同在", "complexity_tier": "T3", "furigana": "wǒ hé Xiǎo Wáng tóng zài yí dòng lóu lǐ zhù", "sentence_source": "generated"}, {"text": "同学们同在教室里准备考试。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈同在医院工作。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩同在一所学校读书。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家同在一个屋子里，不会冷。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人在同一个地方、同一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同在", "is_correct": true, "explanation": "同在：两人处在同一个班里，表示在同一处。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”的宾语应是住所，不能说“住一个班”。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指人之间建立婚姻关系，与“一个班学习”不能相容。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是在水中活动，与在班里学习不能相容。"}], "explanations": {"同在": "同在：两人处在同一个班里，表示在同一处。", "住": "搭配：“住”的宾语应是住所，不能说“住一个班”。", "结婚": "语义：“结婚”指人之间建立婚姻关系，与“一个班学习”不能相容。", "游泳": "语义：“游泳”是在水中活动，与在班里学习不能相容。"}, "sentence_index": 0, "correct_answer": "同在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们俩同在两所学校读书。", "explanation": "这里应该用〈分别〉。同在表示处在同一地方，与“分别在两处”相反；两人各在不同的学校，要说“分别”。"}, {"text": "我一个人同在图书馆里复习。", "explanation": "这里应该用〈在〉。同在要求两个或以上的人或物处在同一处，只有一个人时用“在”。"}, {"text": "他把两个孩子同在了一间房里。", "explanation": "这里应该用〈关〉。同在只说明已经处在同一处，不能表示有人把人或物安置到某处，这里要说“把两个孩子关在一间房里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同在", "is_correct": true, "explanation": "同在：同学们处在同一个教室里，表示共同所在。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人或动物从母体降生，不能用于同学们在教室里准备考试。"}, {"text": "种", "is_correct": false, "explanation": "搭配：“种”的宾语应是植物，不能说“同学们种教室里”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”描写身体状态，与“准备考试”不相容。"}], "explanations": {"同在": "同在：同学们处在同一个教室里，表示共同所在。", "出生": "语义：“出生”指人或动物从母体降生，不能用于同学们在教室里准备考试。", "种": "搭配：“种”的宾语应是植物，不能说“同学们种教室里”。", "生病": "语义：“生病”描写身体状态，与“准备考试”不相容。"}, "sentence_index": 6, "correct_answer": "同在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被同在了会场。", "explanation": "这里应该用〈派〉。同在不能用于被动式，表示被安排到某处要说“被派到会场”。"}, {"text": "他们把行李同在了房间里。", "explanation": "这里应该用〈放〉。同在只描述已经处在一起的状态，不能表示人把东西搬到某处。"}, {"text": "夫妻俩长期同在两地生活。", "explanation": "这里应该用〈分居〉。同在表示处在同一地方或在一起，与“夫妻分居两地”相反；两人长期分开生活要说“分居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩很同在一座山村里长大。", "corrected_sentence": "我们俩同在一座山村里长大。", "error_description": "副词错误：“同在”是动词，前面不能加程度副词“很”，应说“我们俩同在一座山村里长大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们几个人在同在一间屋子里取暖。", "corrected_sentence": "我们几个人同在一间屋子里取暖。", "error_description": "重复错误：“同在”本身已含“在”的意思，前面再加“在”是重复，应说“同在一间屋子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
