INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共同存在；在一起。", "primary_collocate": null, "pronunciation": "tóng zài", "ipa": "tʰʊŋ˧˥ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "快乐和难过常常同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "希望与困难同在，我们不要怕。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市里，新和旧同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱与恨有时会在一个人身上同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论你在哪里，我的心都与你同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危险和机会同在，你要想清楚。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小村子里，快乐与辛苦同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，成功与失败同在，别太难过。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的雪和春天的花同在一张画里。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们，好运与你们同在。", "target_word": "同在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两种事物或人共同存在、在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2667f8-e9d0-427d-8665-36e8f6ad299f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同在", "is_correct": true, "explanation": "同在：共同存在，与“快乐和难过”搭配，表示两者一起存在。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”只能用于有生命的人或动物，“快乐和难过”不能睡觉。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“工作”的主语要是能做事的人，抽象的情绪不能工作。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，专指尊贵的人来到，不用于描写情绪共存的一般语境。"}], "explanations": {"同在": "同在：共同存在，与“快乐和难过”搭配，表示两者一起存在。", "睡觉": "语义：“睡觉”只能用于有生命的人或动物，“快乐和难过”不能睡觉。", "工作": "语义：“工作”的主语要是能做事的人，抽象的情绪不能工作。", "驾临": "语域：“驾临”是敬辞，专指尊贵的人来到，不用于描写情绪共存的一般语境。"}, "sentence_index": 0, "correct_answer": "同在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两台机器的运行可以同在进行。", "explanation": "这里应该用〈同步〉。同在表示共同存在，不表示动作在同一时间进行；两个过程一起进行、节奏一致要用“同步”。"}, {"text": "这一刻，我的心里同在着一份喜悦。", "explanation": "这里应该用〈存在〉。同在要求两种或以上事物共同存在，只有一份喜悦时用“存在”或“有”。"}, {"text": "这两件事同在发生了。", "explanation": "这里应该用〈同时〉。同在表示共同存在，不表示“在同一时间”；说两件事在同一时间发生，要用“同时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同在", "is_correct": true, "explanation": "同在：共同存在，与“快乐与辛苦”搭配，说明两者在村子里并存。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要有生命的主体在水中活动，“快乐与辛苦”不能游泳。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指人因公到外地去，抽象的情绪不能出差。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”的主语应是商品或房产，不能说“快乐与辛苦出售”。"}], "explanations": {"同在": "同在：共同存在，与“快乐与辛苦”搭配，说明两者在村子里并存。", "游泳": "语义：“游泳”需要有生命的主体在水中活动，“快乐与辛苦”不能游泳。", "出差": "语义：“出差”指人因公到外地去，抽象的情绪不能出差。", "出售": "搭配：“出售”的主语应是商品或房产，不能说“快乐与辛苦出售”。"}, "sentence_index": 6, "correct_answer": "同在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两支队伍把人马同在了一处。", "explanation": "这里应该用〈集结〉。同在只说明事物已经处在一起，不表示有人主动把人或物聚到一处，这里要说“把人马集结在一处”。"}, {"text": "他心里同在一个不愿说出口的秘密。", "explanation": "这里应该用〈有〉。同在要求两种或以上事物共存；心里只有一个秘密时用“有”。"}, {"text": "我的老家同在一个安静的小镇上。", "explanation": "这里应该用〈在〉。同在强调与别的事物共存；只说一个主语所处的位置时用“在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "勇气与恐惧很同在，她还是走了出去。", "corrected_sentence": "勇气与恐惧同在，她还是走了出去。", "error_description": "副词错误：“同在”是动词，前面不能加程度副词“很”，应说“勇气与恐惧同在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "欢笑与泪水在同在，这就是生活。", "corrected_sentence": "欢笑与泪水同在，这就是生活。", "error_description": "错误的形式是“在同在”，正确的形式是“同在”。“同在”本身已含“在”的意思，前面再加“在”是重复，应直接说“同在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b42dbd5-06a6-458e-9feb-55fb79c19ffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶", "is_correct": true, "explanation": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。"}, {"text": "远", "is_correct": false, "explanation": "远与善没有反义关系，远指距离大，与心地好的义项无关。"}, {"text": "慢", "is_correct": false, "explanation": "慢与善没有反义关系，慢指速度低，与心地好的义项无关。"}, {"text": "硬", "is_correct": false, "explanation": "硬与善没有反义关系，硬指质地坚实，与心地好的义项无关。"}], "correct_answer": "恶", "explanations": {"恶": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。", "远": "远与善没有反义关系，远指距离大，与心地好的义项无关。", "慢": "慢与善没有反义关系，慢指速度低，与心地好的义项无关。", "硬": "硬与善没有反义关系，硬指质地坚实，与心地好的义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶", "is_correct": true, "explanation": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。"}, {"text": "快", "is_correct": false, "explanation": "快与善没有反义关系，快指速度高，与心地好的义项无关。"}, {"text": "重", "is_correct": false, "explanation": "重与善没有反义关系，重指分量大，与心地好的义项无关。"}, {"text": "高", "is_correct": false, "explanation": "高与善没有反义关系，高指距离上方远，与心地好的义项无关。"}], "correct_answer": "恶", "explanations": {"恶": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。", "快": "快与善没有反义关系，快指速度高，与心地好的义项无关。", "重": "重与善没有反义关系，重指分量大，与心地好的义项无关。", "高": "高与善没有反义关系，高指距离上方远，与心地好的义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "善是心地好，愿意帮助别人。", "primary_collocate": null, "pronunciation": "shàn", "ipa": "ʂan˥˩", "syllable_count": 1, "sentences": [{"text": "王阿姨心善，邻居有事她都帮忙。", "target_word": "善", "complexity_tier": "T3", "furigana": "wáng ā yí xīn shàn, lín jū yǒu shì tā dōu bāng máng.", "sentence_source": "generated"}, {"text": "那位大姐心善，看见有人摔倒马上跑过去。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李心善，同学没带钱，他就请客。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个又善又热心的人。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我，做人要心善，要多帮别人。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板娘心善，总给我们多加菜。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心善，遇到老人过马路，一定去扶。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心善，谁找他帮忙他都不拒绝。", "target_word": "善", "complexity_tier": "T3", "furigana": "tā xīn shàn, shéi zhǎo tā bāng máng tā dōu bù jù jué.", "sentence_source": "generated"}, {"text": "班里的小明心善，常常帮同学拿东西。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居心善，下雨时会借伞给路人。", "target_word": "善", "complexity_tier": "T3", "furigana": "wǒ de lín jū xīn shàn, xià yǔ shí huì jiè sǎn gěi lù rén.", "sentence_source": "generated"}], "morphological_forms": [{"form": "善良", "label": "复合"}, {"form": "善意", "label": "复合"}, {"form": "善心", "label": "复合"}], "register": "中性", "sense_fingerprint": "心地好，愿意帮助别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "善", "is_correct": true, "explanation": "善（shàn）：心地好、愿意帮助别人，是正确答案。"}, {"text": "闪", "is_correct": false, "explanation": "闪（shǎn）与善（shàn）声调不同，闪是第三声，意思是闪亮、躲避。"}, {"text": "散", "is_correct": false, "explanation": "散（sàn）与善（shàn）声母不同，s 与 sh 相混，声调相同，意思是分散。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng）与善（shàn）韵母不同，an 与 ang 相混，声调相同，意思是上面。"}, {"text": "赞", "is_correct": false, "explanation": "赞（zàn）与善（shàn）声母不同（z 与 sh），声调和韵母相同，意思是赞扬。"}], "explanations": {"善": "善（shàn）：心地好、愿意帮助别人，是正确答案。", "闪": "闪（shǎn）与善（shàn）声调不同，闪是第三声，意思是闪亮、躲避。", "散": "散（sàn）与善（shàn）声母不同，s 与 sh 相混，声调相同，意思是分散。", "上": "上（shàng）与善（shàn）韵母不同，an 与 ang 相混，声调相同，意思是上面。", "赞": "赞（zàn）与善（shàn）声母不同（z 与 sh），声调和韵母相同，意思是赞扬。"}, "sentence_index": null, "correct_answer": "善"}, "level_3": {"options": [{"text": "善", "is_correct": true, "explanation": "善：心地好、愿意帮助别人，与“邻居有事她都帮忙”相符，是正确答案。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“心冷”指冷漠无情，与“邻居有事她都帮忙”矛盾。"}, {"text": "凶", "is_correct": false, "explanation": "语义：“心凶”指凶狠，与主动帮忙的语境相反。"}, {"text": "慌", "is_correct": false, "explanation": "搭配：“心慌”形容内心慌乱，说的是心神状态，不能用来评价一个人的品性。"}], "explanations": {"善": "善：心地好、愿意帮助别人，与“邻居有事她都帮忙”相符，是正确答案。", "冷": "语义：“心冷”指冷漠无情，与“邻居有事她都帮忙”矛盾。", "凶": "语义：“心凶”指凶狠，与主动帮忙的语境相反。", "慌": "搭配：“心慌”形容内心慌乱，说的是心神状态，不能用来评价一个人的品性。"}, "sentence_index": 0, "correct_answer": "善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很善，坐起来很舒服。", "explanation": "这里应该用〈好〉。善指人心地好、愿意帮助别人，形容物品的好坏要用好。"}, {"text": "天气很善，一会儿晴一会儿雨。", "explanation": "这里应该用〈多变〉。善形容人的心地好，不用来形容天气。"}, {"text": "这台电脑很善，运行得很快。", "explanation": "这里应该用〈好〉。善指心地好、愿意帮助别人，形容电脑性能要用好，不能说“善”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "善", "is_correct": true, "explanation": "善（shàn）：心地好、愿意帮助别人，是正确答案。"}, {"text": "山", "is_correct": false, "explanation": "山（shān）与善（shàn）声调不同，山是第一声，意思是山。"}, {"text": "尚", "is_correct": false, "explanation": "尚（shàng）与善（shàn）韵尾不同（n 与 ng），声调相同，意思是还、尚且。"}, {"text": "赞", "is_correct": false, "explanation": "赞（zàn）与善（shàn）声母不同（z 与 sh），声调和韵母相同，意思是赞扬。"}], "explanations": {"善": "善（shàn）：心地好、愿意帮助别人，是正确答案。", "山": "山（shān）与善（shàn）声调不同，山是第一声，意思是山。", "尚": "尚（shàng）与善（shàn）韵尾不同（n 与 ng），声调相同，意思是还、尚且。", "赞": "赞（zàn）与善（shàn）声母不同（z 与 sh），声调和韵母相同，意思是赞扬。"}, "sentence_index": null, "correct_answer": "善"}, "level_3": {"options": [{"text": "善", "is_correct": true, "explanation": "善：心地好、愿意帮助别人，与“一定去扶”相符，是正确答案。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“心硬”指铁石心肠，与“遇到老人过马路，一定去扶”矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“心懒”指懒惰，与主动扶老人的语境相悖。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“心冷”指冷漠无情，与“遇到老人过马路，一定去扶”矛盾。"}], "explanations": {"善": "善：心地好、愿意帮助别人，与“一定去扶”相符，是正确答案。", "硬": "语义：“心硬”指铁石心肠，与“遇到老人过马路，一定去扶”矛盾。", "懒": "语义：“心懒”指懒惰，与主动扶老人的语境相悖。", "冷": "语义：“心冷”指冷漠无情，与“遇到老人过马路，一定去扶”矛盾。"}, "sentence_index": 6, "correct_answer": "善"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料很善，摸起来很软。", "explanation": "这里应该用〈软〉。善形容人的心地好，不用来形容布料的质地。"}, {"text": "这场雨很善，下了三天都不停。", "explanation": "这里应该用〈连绵〉。善形容人的心地好，不用来形容雨。"}, {"text": "这支笔很善，写起字来很流畅。", "explanation": "这里应该用〈好用〉。善形容人的心地好，不用来形容书写工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们楼下的阿姨善心，见到乞丐就给点吃的。", "corrected_sentence": "我们楼下的阿姨心善，见到乞丐就给点吃的。", "error_description": "语序错误：表示品性时，形容词“善”要与“心”组成“心善”作谓语，“善心”是名词，不能直接作谓语。应说“阿姨心善”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个小伙子不心善，看到我搬家就来帮忙。", "corrected_sentence": "那个小伙子心善，看到我搬家就来帮忙。", "error_description": "否定位置错误：否定词“不”应放在“善”前构成“心不善”，“不心善”是错误语序。本句是肯定句，应去掉“不”，说“心善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶", "is_correct": true, "explanation": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。"}, {"text": "远", "is_correct": false, "explanation": "远与善没有反义关系，远指距离大，与心地仁慈的义项无关。"}, {"text": "慢", "is_correct": false, "explanation": "慢与善没有反义关系，慢指速度低，与心地仁慈的义项无关。"}, {"text": "硬", "is_correct": false, "explanation": "硬与善没有反义关系，硬指质地坚实，与心地仁慈的义项无关。"}], "correct_answer": "恶", "explanations": {"恶": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。", "远": "远与善没有反义关系，远指距离大，与心地仁慈的义项无关。", "慢": "慢与善没有反义关系，慢指速度低，与心地仁慈的义项无关。", "硬": "硬与善没有反义关系，硬指质地坚实，与心地仁慈的义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶", "is_correct": true, "explanation": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。"}, {"text": "快", "is_correct": false, "explanation": "快与善没有反义关系，快指速度高，与心地仁慈的义项无关。"}, {"text": "重", "is_correct": false, "explanation": "重与善没有反义关系，重指分量大，与心地仁慈的义项无关。"}, {"text": "高", "is_correct": false, "explanation": "高与善没有反义关系，高指距离上方远，与心地仁慈的义项无关。"}], "correct_answer": "恶", "explanations": {"恶": "恶：与“善”构成反义关系，是《现代汉语词典》所列的反义词。", "快": "快与善没有反义关系，快指速度高，与心地仁慈的义项无关。", "重": "重与善没有反义关系，重指分量大，与心地仁慈的义项无关。", "高": "高与善没有反义关系，高指距离上方远，与心地仁慈的义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "良好，心地仁慈。", "primary_collocate": null, "pronunciation": "shàn", "ipa": "ʂan˥˩", "syllable_count": 1, "sentences": [{"text": "她这个人心善，常常帮助邻居。", "target_word": "善", "complexity_tier": "T3", "furigana": "tā zhè ge rén xīn shàn, cháng cháng bāng zhù lín jū.", "sentence_source": "generated"}, {"text": "奶奶心善，从不跟别人吵架。", "target_word": "善", "complexity_tier": "T3", "furigana": "nǎi nai xīn shàn, cóng bù gēn bié rén chǎo jià.", "sentence_source": "generated"}, {"text": "他看起来很凶，其实心善。", "target_word": "善", "complexity_tier": "T3", "furigana": "tā kàn qǐ lái hěn xiōng, qí shí xīn shàn.", "sentence_source": "generated"}, {"text": "我们都说他是个心善的人。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板心善，常给山区的孩子送书。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这个人心善，别人一求他就答应。", "target_word": "善", "complexity_tier": "T3", "furigana": "tā zhè ge rén xīn shàn, bié rén yì qiú tā jiù dā ying.", "sentence_source": "generated"}, {"text": "这位大叔心善，看见小孩摔倒就把他扶起来。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人心善，每天都给流浪猫送吃的。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张医生心善，给穷人看病不收钱。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就心善，见到可怜的人就想帮忙。", "target_word": "善", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "善良", "label": "复合"}, {"form": "善意", "label": "复合"}, {"form": "善心", "label": "复合"}], "register": "中性", "sense_fingerprint": "心地仁慈，品性良好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "善", "is_correct": true, "explanation": "善（shàn）：心地仁慈、品性良好，是正确答案。"}, {"text": "山", "is_correct": false, "explanation": "山（shān）与善（shàn）声调不同，山是第一声，意思是山。"}, {"text": "闪", "is_correct": false, "explanation": "闪（shǎn）与善（shàn）声调不同，闪是第三声，意思是闪亮、躲避。"}, {"text": "散", "is_correct": false, "explanation": "散（sàn）与善（shàn）声母不同，s 与 sh 相混，声调相同，意思是分散。"}, {"text": "上", "is_correct": false, "explanation": "上（shàng）与善（shàn）韵母不同，an 与 ang 相混，声调相同，意思是上面。"}], "explanations": {"善": "善（shàn）：心地仁慈、品性良好，是正确答案。", "山": "山（shān）与善（shàn）声调不同，山是第一声，意思是山。", "闪": "闪（shǎn）与善（shàn）声调不同，闪是第三声，意思是闪亮、躲避。", "散": "散（sàn）与善（shàn）声母不同，s 与 sh 相混，声调相同，意思是分散。", "上": "上（shàng）与善（shàn）韵母不同，an 与 ang 相混，声调相同，意思是上面。"}, "sentence_index": null, "correct_answer": "善"}, "level_3": {"options": [{"text": "善", "is_correct": true, "explanation": "善：心地仁慈，与“常常帮助邻居”相符，是正确答案。"}, {"text": "狠", "is_correct": false, "explanation": "语义：“狠”指凶恶残忍，与“常常帮助邻居”矛盾，“心狠”不合句意。"}, {"text": "黑", "is_correct": false, "explanation": "语域：“心黑”是口语中的贬义说法，与书面叙述的助人语境不合，句意也相反。"}, {"text": "慌", "is_correct": false, "explanation": "搭配：“心慌”形容内心慌乱，说的是心神状态，不能用来评价一个人的品性。"}], "explanations": {"善": "善：心地仁慈，与“常常帮助邻居”相符，是正确答案。", "狠": "语义：“狠”指凶恶残忍，与“常常帮助邻居”矛盾，“心狠”不合句意。", "黑": "语域：“心黑”是口语中的贬义说法，与书面叙述的助人语境不合，句意也相反。", "慌": "搭配：“心慌”形容内心慌乱，说的是心神状态，不能用来评价一个人的品性。"}, "sentence_index": 0, "correct_answer": "善"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头很善，摸起来很粗糙。", "explanation": "这里应该用〈粗糙〉。善形容人的心地仁慈，不用来描述物体的质感。"}, {"text": "这个孩子的身高很善，已经比哥哥还高了。", "explanation": "这里应该用〈高〉。善形容人的心地仁慈，不用来形容身高。"}, {"text": "这家餐厅的门很善，推开就吱吱作响。", "explanation": "这里应该用〈旧〉。善形容人的心地仁慈，不用来形容门的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
