INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个人善心，见到流浪狗就带回家喂养。", "corrected_sentence": "他这个人心善，见到流浪狗就带回家喂养。", "error_description": "语序错误：表示品性时，形容词“善”要与“心”组成“心善”作谓语，“善心”是名词，不能直接作谓语。应说“他这个人心善”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位房东不心善，从不催房租。", "corrected_sentence": "那位房东心善，从不催房租。", "error_description": "否定位置错误：否定词“不”应放在“善”前构成“心不善”，“不心善”是错误语序。本句是肯定句，应去掉“不”，说“心善”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
