INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94613, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "子弹是枪里打出去的小小的、硬硬的东西。", "primary_collocate": null, "pronunciation": "zǐ dàn", "ipa": "tsɨ˨˩ tan˥˩", "syllable_count": 2, "sentences": [{"text": "警察的枪里只剩一颗子弹了。", "target_word": "子弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "子弹从枪里飞出去，速度很快。", "target_word": "子弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把子弹放进枪里。", "target_word": "子弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的人躲开了飞来的子弹。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些子弹硬硬的，不能乱玩。", "target_word": "子弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上有一个子弹留下的小洞。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵的口袋里装着几颗子弹。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "枪里没有子弹，就打不出去。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在博物馆里看到一颗旧子弹。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子弹打在石头上，发出很大的声音。", "target_word": "子弹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "发", "label": "量词"}, {"form": "子弹壳", "label": "复合"}], "register": "中性", "sense_fingerprint": "枪里打出去的小而硬的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹药", "is_correct": false, "explanation": "搭配：“弹药”是不可数的统称，不能说“一颗弹药”。"}, {"text": "子弹", "is_correct": true, "explanation": "“子弹”是枪里打出去的小弹丸，用“颗”计量，符合句中“枪里”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会装在枪里，“枪里只剩一颗石头”与常识不符。"}, {"text": "糖", "is_correct": false, "explanation": "语义：糖不是枪里的东西，与“警察的枪”这一语境冲突。"}], "explanations": {"弹药": "搭配：“弹药”是不可数的统称，不能说“一颗弹药”。", "子弹": "“子弹”是枪里打出去的小弹丸，用“颗”计量，符合句中“枪里”的语境。", "石头": "语义：石头不会装在枪里，“枪里只剩一颗石头”与常识不符。", "糖": "语义：糖不是枪里的东西，与“警察的枪”这一语境冲突。"}, "sentence_index": 0, "correct_answer": "子弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们点燃了一颗子弹。", "explanation": "这里应该用〈鞭炮〉。鞭炮可以点燃放响，子弹是枪械用的弹丸，不能点燃。"}, {"text": "坦克的主炮朝敌人打出了一发子弹。", "explanation": "这里应该用〈炮弹〉。主炮是大口径火炮，发射的是炮弹；“子弹”指枪械发射的小弹丸，不能由主炮打出。"}, {"text": "敌人的飞机朝我们扔了一颗子弹。", "explanation": "这里应该用〈炸弹〉。飞机投下的是炸弹，子弹要靠枪械射出，不能用“扔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "体貌：西瓜太大，装不进士兵的口袋。"}, {"text": "子弹", "is_correct": true, "explanation": "“子弹”是可以装进口袋的小弹丸，用“颗”计量，符合句意。"}, {"text": "云", "is_correct": false, "explanation": "体貌：云没有固定形状，也不能装进口袋。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，不会被装进士兵的口袋里。"}], "explanations": {"西瓜": "体貌：西瓜太大，装不进士兵的口袋。", "子弹": "“子弹”是可以装进口袋的小弹丸，用“颗”计量，符合句意。", "云": "体貌：云没有固定形状，也不能装进口袋。", "月亮": "语义：月亮在天上，不会被装进士兵的口袋里。"}, "sentence_index": 6, "correct_answer": "子弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拉开保险栓，把子弹扔向了敌人的阵地。", "explanation": "这里应该用〈手榴弹〉。扔出去的是手榴弹；“子弹”要靠枪械射出，不能用“扔”。"}, {"text": "子弹从发射架上升空，直奔目标。", "explanation": "这里应该用〈导弹〉。导弹才从发射架上升空；子弹由枪械射出，不用发射架发射。"}, {"text": "夜里，一颗子弹照亮了整个战场。", "explanation": "这里应该用〈照明弹〉。照明弹能发光照亮，子弹不能照明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的枪里还有几张子弹。", "corrected_sentence": "他的枪里还有几颗子弹。", "error_description": "量词错误：“子弹”应用量词“颗”（或“发”），不能用“张”（“张”用于平面的东西）。正确的说法是“几颗子弹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一颗子弹放进了口袋。", "corrected_sentence": "他把一颗子弹放进了口袋。", "error_description": "漏掉了“把”。“放进”要用把字句处置“子弹”，应说“他把一颗子弹放进了口袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
