INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指导学习、研究或工作的老师。", "primary_collocate": null, "pronunciation": "dǎo shī", "ipa": "taʊ̯˨˩˦ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他在大学读硕士，导师是一位有名的教授。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生要先选好导师，再开始做研究。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的导师很忙，一个月才有时间见我一次。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导师看了我的论文，提了几个意见。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每个新人安排了一位导师。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业的时候，我送了导师一本书。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟着导师做了三年研究。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导师对学生要求很严，大家都怕他。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位导师带过很多有名的学生。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生有问题，可以随时去办公室问导师。", "target_word": "导师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "導師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指导学习、研究或工作的老师", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5258b993-fe08-4e39-8f9e-8758c837d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师（dǎo shī）：指导学习、研究或工作的老师，是正确答案。"}, {"text": "倒是", "is_correct": false, "explanation": "倒是（dào shì）与导师（dǎo shī）第一个音节声调不同，第二个音节声调也不同，意思是“倒是”。"}, {"text": "到时", "is_correct": false, "explanation": "到时（dào shí）与导师（dǎo shī）两个音节的声调都不同，意思是到了那个时候。"}, {"text": "导视", "is_correct": false, "explanation": "导视（dǎo shì）与导师（dǎo shī）第二个音节声调不同，意思是导向标识。"}, {"text": "道士", "is_correct": false, "explanation": "道士（dào shi）与导师（dǎo shī）第一个音节声调不同，第二个音节读轻声，意思是道教的修行人。"}], "explanations": {"导师": "导师（dǎo shī）：指导学习、研究或工作的老师，是正确答案。", "倒是": "倒是（dào shì）与导师（dǎo shī）第一个音节声调不同，第二个音节声调也不同，意思是“倒是”。", "到时": "到时（dào shí）与导师（dǎo shī）两个音节的声调都不同，意思是到了那个时候。", "导视": "导视（dǎo shì）与导师（dǎo shī）第二个音节声调不同，意思是导向标识。", "道士": "道士（dào shi）与导师（dǎo shī）第一个音节声调不同，第二个音节读轻声，意思是道教的修行人。"}, "sentence_index": null, "correct_answer": "导师"}, "level_3": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师：指导学习和研究的教授，与“是一位有名的教授”相符，是正确答案。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是读书的人，不能是“有名的教授”，句意矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不能是一位教授，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“是一位……教授”要求人作主语，窗户无法充当。"}], "explanations": {"导师": "导师：指导学习和研究的教授，与“是一位有名的教授”相符，是正确答案。", "学生": "语义：学生是读书的人，不能是“有名的教授”，句意矛盾。", "花园": "语义：花园是地方，不能是一位教授，句意不通。", "窗户": "配价：“是一位……教授”要求人作主语，窗户无法充当。"}, "sentence_index": 0, "correct_answer": "导师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导师每天负责开车接送我们。", "explanation": "这里应该用〈司机〉。导师指指导学习、研究或工作的人，不指驾驶车辆的人。"}, {"text": "导师每天在工地上搬砖。", "explanation": "这里应该用〈工人〉。导师指指导学习、研究或工作的人，不指体力劳动者。"}, {"text": "我们公司请了一位导师，每周来修理电脑。", "explanation": "这里应该用〈技术员〉。导师指指导学习或工作的人，不指修理电脑的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导师", "is_correct": true, "explanation": "导师：指导学习和研究的人，与“跟着做了三年研究”相符，是正确答案。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能作为人跟着做研究的对象，句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐的场所，不能被“跟着”去做研究，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“跟着……做研究”要求人作对象，桌子无法充当。"}], "explanations": {"导师": "导师：指导学习和研究的人，与“跟着做了三年研究”相符，是正确答案。", "电脑": "语义：电脑是机器，不能作为人跟着做研究的对象，句意不通。", "食堂": "语义：食堂是用餐的场所，不能被“跟着”去做研究，句意不通。", "桌子": "配价：“跟着……做研究”要求人作对象，桌子无法充当。"}, "sentence_index": 6, "correct_answer": "导师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导师每天帮我做饭洗衣服。", "explanation": "这里应该用〈保姆〉。导师指指导学习或研究的人，不负责家务。"}, {"text": "导师每天打扫教室。", "explanation": "这里应该用〈清洁工〉。导师指指导学习或工作的人，不指打扫卫生的工人。"}, {"text": "导师每天开车送我上班。", "explanation": "这里应该用〈司机〉。导师指指导学习或工作的人，不指驾驶车辆的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
