INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们系的一位导师们很负责。", "corrected_sentence": "我们系的一位导师很负责。", "error_description": "后缀错误：数量短语“一位”已表示数量，“导师”之后不能再加复数后缀“们”。应说“一位导师”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8008efc7-4257-404c-9074-a08841ac8e8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
