INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "处境为难，神态不自然。", "primary_collocate": null, "pronunciation": "gān gà", "ipa": "kan˥ ka˥˩", "syllable_count": 2, "sentences": [{"text": "他的处境很尴尬，帮谁都不好。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在两个朋友中间，样子很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得很尴尬，不知道说什么好。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个尴尬的问题，大家都不想回答。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他丢了工作，又没有钱，处境十分尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人一见面，脸上的表情都有点尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里很安静，气氛变得尴尬起来。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是老师，也不是学生，身份有点尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听到这个问题，笑容看起来很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "furigana": "gān gà", "sentence_source": "generated"}, {"text": "吵架以后，他们在电梯里遇到，场面很尴尬。", "target_word": "尴尬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尴尬地", "label": "副词形式"}, {"form": "尷尬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处境进退两难，或表情神态不自然", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“处境尴尬”指进退两难，与“帮谁都不好”相符。"}, {"text": "顺利", "is_correct": false, "explanation": "语义：“顺利”表示没有阻碍，与“帮谁都不好”的两难处境矛盾。"}, {"text": "优越", "is_correct": false, "explanation": "语义：“优越”表示条件好，与两难的处境不符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“处境”一般说好、坏、困难，不说“处境热闹”。"}], "explanations": {"尴尬": "“处境尴尬”指进退两难，与“帮谁都不好”相符。", "顺利": "语义：“顺利”表示没有阻碍，与“帮谁都不好”的两难处境矛盾。", "优越": "语义：“优越”表示条件好，与两难的处境不符。", "热闹": "搭配：“处境”一般说好、坏、困难，不说“处境热闹”。"}, "sentence_index": 0, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次合作很尴尬，双方都很满意。", "explanation": "这里应该用〈顺利〉。尴尬表示处境为难或神态不自然，不能用来形容合作顺利、双方满意。"}, {"text": "父母看到孩子进步，感到很尴尬。", "explanation": "这里应该用〈欣慰〉。尴尬表示为难或不自然，不表示满意的心情。"}, {"text": "孩子考了满分，非常尴尬。", "explanation": "这里应该用〈自豪〉。尴尬表示处境为难或神态不自然，不表示骄傲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尴尬", "is_correct": true, "explanation": "“气氛尴尬”表示场面不自然，与“房间很安静”之后气氛的变化相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“气氛”不说“漂亮”，一般说热烈、融洽之类。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形或物体的大小，不能用来形容气氛。"}, {"text": "凶猛", "is_correct": false, "explanation": "语义：“凶猛”指猛烈或凶狠，与安静的房间不相符。"}], "explanations": {"尴尬": "“气氛尴尬”表示场面不自然，与“房间很安静”之后气氛的变化相符。", "漂亮": "搭配：“气氛”不说“漂亮”，一般说热烈、融洽之类。", "高大": "体貌：“高大”形容体形或物体的大小，不能用来形容气氛。", "凶猛": "语义：“凶猛”指猛烈或凶狠，与安静的房间不相符。"}, "sentence_index": 6, "correct_answer": "尴尬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赢了比赛，心里很尴尬。", "explanation": "这里应该用〈得意〉。尴尬指处境为难或神态不自然，不用来形容赢了比赛后的得意。"}, {"text": "球迷听到进球的消息，都很尴尬。", "explanation": "这里应该用〈兴奋〉。尴尬表示为难或神态不自然，不用来描述听到好消息时的激动。"}, {"text": "听到亲人去世的消息，他很尴尬。", "explanation": "这里应该用〈悲伤〉。尴尬不表示失去亲人的悲痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他夹在两家人中间，这种尴尬地处境让他很累。", "corrected_sentence": "他夹在两家人中间，这种尴尬的处境让他很累。", "error_description": "结构助词用错。错误形式是“尴尬地处境”，正确形式是“尴尬的处境”。“尴尬”修饰名词“处境”时要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人见面后，她尴尬了地转过了头。", "corrected_sentence": "两人见面后，她尴尬地转过了头。", "error_description": "错误形式：“尴尬了地转过了头”。正确形式：“尴尬地转过了头”。“了”表示完成，不能插在状语“尴尬”和结构助词“地”之间，这样组合不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
