INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "常务委员会的成员的简称，指在委员会中负责日常事务、经常履行职责的委员。", "primary_collocate": null, "pronunciation": "cháng wěi", "ipa": "tʂʰɑŋ˧˥ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是常委之一，负责日常工作。", "target_word": "常委", "complexity_tier": "T3", "furigana": "cháng wěi", "sentence_source": "generated"}, {"text": "这位常委每天都去办公室。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "常委要经常参加会议。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家选她当常委。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的常委已经上班了。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位常委刚从北京回来。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "常委们讨论了今年的预算。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年常委，很有经验。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里有十二位常委。", "target_word": "常委", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "常委负责审查每月的报告。", "target_word": "常委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "正式", "sense_fingerprint": "常务委员会中负责日常事务的委员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常委", "is_correct": true, "explanation": "常委是常务委员会中负责日常事务的委员，与“负责日常工作”相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不负责日常工作，与句意矛盾。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是来买东西的人，不负责日常工作。"}, {"text": "鲜花", "is_correct": false, "explanation": "搭配：“鲜花”不指人，不能用于“……之一，负责日常工作”。"}], "explanations": {"常委": "常委是常务委员会中负责日常事务的委员，与“负责日常工作”相符。", "游客": "语义：游客是来参观的人，不负责日常工作，与句意矛盾。", "顾客": "语义：顾客是来买东西的人，不负责日常工作。", "鲜花": "搭配：“鲜花”不指人，不能用于“……之一，负责日常工作”。"}, "sentence_index": 0, "correct_answer": "常委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家选她当一只常委。", "explanation": "这里应该用〈位〉。常委指人，量词要用〈位〉，〈只〉不用于人。"}, {"text": "这位常委在工地上搬砖，从不管日常事务。", "explanation": "这里应该用〈工人〉。常委负责日常事务、经常履行职责，在工地搬砖是工人的工作，不说〈常委〉。"}, {"text": "这位常委每天在农田里收割庄稼，从不参加会议。", "explanation": "这里应该用〈农民〉。常委常常要参加会议、履行职责，在农田里收割庄稼是农民的劳动，不说〈常委〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常委", "is_correct": true, "explanation": "常委是有决策权的成员，能够讨论预算，与句意相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能讨论预算，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不能讨论预算。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“讨论”的主语须是人或群体，“窗户”不能搭配。"}], "explanations": {"常委": "常委是有决策权的成员，能够讨论预算，与句意相符。", "小猫": "语义：小猫不能讨论预算，与句意矛盾。", "石头": "语义：石头是无生命的东西，不能讨论预算。", "窗户": "搭配：“讨论”的主语须是人或群体，“窗户”不能搭配。"}, "sentence_index": 6, "correct_answer": "常委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "常委每天在港口搬货，从不审查报告。", "explanation": "这里应该用〈装卸工〉。常委负责审查报告、履行职责，在港口搬货是装卸工的工作，不说〈常委〉。"}, {"text": "常委每天在街上修自行车。", "explanation": "这里应该用〈修车工〉。常委是负责日常事务的委员，在街上修自行车是修车工的工作，不说〈常委〉。"}, {"text": "常委每天在医院当护工，帮病人洗澡。", "explanation": "这里应该用〈护工〉。常委负责审查报告、决定事务，帮病人洗澡是护工的工作，不说〈常委〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只常委每周一都要主持例会。", "corrected_sentence": "这位常委每周一都要主持例会。", "error_description": "量词错误：“常委”指人，应用量词“位”，不能用“只”。正确说法是“这位常委”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "常委的们明天都会到齐。", "corrected_sentence": "常委们明天都会到齐。", "error_description": "词语错误：“常委们”是复数，“们”前面不能加“的”。正确说法是“常委们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
