INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94629, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从前是很久很久以前的时候。", "primary_collocate": null, "pronunciation": "cóng qián", "ipa": "tsʰʊŋ˧˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "从前，山里有一个小村子。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前有一只小狗，它很爱笑。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，从前这里没有路。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前，有个国王住在大房子里。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我讲了一个从前的故事。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前有位老人，他每天都去河边。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事是这样开始的：从前有三只小猪。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前，森林里住着一只大熊。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每晚讲故事：“从前，有个小女孩。”", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前有一个人，他特别喜欢画画。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從前", "label": "繁体"}], "register": "中性", "sense_fingerprint": "故事开头用语，指很久很久以前的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，村子不会在明天才出现，与故事的开头不符。"}, {"text": "从前", "is_correct": true, "explanation": "“从前”指很久很久以前，正适合故事的开头。"}, {"text": "星期六", "is_correct": false, "explanation": "语义：星期六是一个具体的日子，不能作为故事的开头时间。"}, {"text": "前期", "is_correct": false, "explanation": "语域：“前期”是书面或专业用语，不适合童话式的口语开头。"}], "explanations": {"明天": "语义：“明天”指将来，村子不会在明天才出现，与故事的开头不符。", "从前": "“从前”指很久很久以前，正适合故事的开头。", "星期六": "语义：星期六是一个具体的日子，不能作为故事的开头时间。", "前期": "语域：“前期”是书面或专业用语，不适合童话式的口语开头。"}, "sentence_index": 0, "correct_answer": "从前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从前我们再去看他吧。", "explanation": "这里应该用〈以后〉。“从前”指很久很久以前，不能用来提议将来再做的事。"}, {"text": "火车从前就要开了。", "explanation": "这里应该用〈马上〉。“从前”指很久以前，不能与“就要”搭配，表示眼前即将发生的事。"}, {"text": "我们从前下个月去郊游。", "explanation": "这里应该用〈将来〉。“从前”指很久以前，不能与“下个月”这样的近期将来时间并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下周", "is_correct": false, "explanation": "语义：“下周”指将来，不能用于讲述很久以前的故事。"}, {"text": "从前", "is_correct": true, "explanation": "“从前”是故事开头的常用语，指很久以前，符合句意。"}, {"text": "初期", "is_correct": false, "explanation": "语域：“初期”是书面用语，不用于童话开头。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学是学校，不能作为故事开头的时间。"}], "explanations": {"下周": "语义：“下周”指将来，不能用于讲述很久以前的故事。", "从前": "“从前”是故事开头的常用语，指很久以前，符合句意。", "初期": "语域：“初期”是书面用语，不用于童话开头。", "大学": "语义：大学是学校，不能作为故事开头的时间。"}, "sentence_index": 6, "correct_answer": "从前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们从前就要结婚了。", "explanation": "这里应该用〈下个月〉。“从前”指过去，不能和“就要”这样表示将来的词搭配。"}, {"text": "这家店从前就要开业了。", "explanation": "这里应该用〈下周〉。“从前”指很久以前，不能与“就要”搭配，表示近期将要发生的事。"}, {"text": "这一刻，我们从前正在散步。", "explanation": "这里应该用〈现在〉。“从前”指很久以前，不能和“这一刻”正在进行的动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从前的，有一个老人住在山下。", "corrected_sentence": "从前，有一个老人住在山下。", "error_description": "错误在“从前”后多加了“的”。“从前”作故事开头的时间词，后面要直接用逗号，应说“从前，有一个老人住在山下。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌是从前了流传下来的。", "corrected_sentence": "这首歌是从前流传下来的。", "error_description": "错误在“从前”后加了“了”。“从前”是时间词，不能带“了”，应说“这首歌是从前流传下来的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "桌子", "is_correct": false, "explanation": "与“从前”无反义关系，“桌子”不是时间词，不构成对立。"}, {"text": "现在", "is_correct": true, "explanation": "“现在”指说话的当下，与“从前”指过去构成时间上的反义。"}, {"text": "河流", "is_correct": false, "explanation": "与“从前”无反义关系，“河流”不是时间词，不构成对立。"}, {"text": "苹果", "is_correct": false, "explanation": "与“从前”无反义关系，“苹果”不是时间词，不构成对立。"}], "correct_answer": "现在", "explanations": {"桌子": "与“从前”无反义关系，“桌子”不是时间词，不构成对立。", "现在": "“现在”指说话的当下，与“从前”指过去构成时间上的反义。", "河流": "与“从前”无反义关系，“河流”不是时间词，不构成对立。", "苹果": "与“从前”无反义关系，“苹果”不是时间词，不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白云", "is_correct": false, "explanation": "与“从前”无反义关系，“白云”不是时间词，不构成对立。"}, {"text": "现在", "is_correct": true, "explanation": "“现在”指说话的当下，与“从前”指过去构成时间上的反义。"}, {"text": "窗户", "is_correct": false, "explanation": "与“从前”无反义关系，“窗户”不是时间词，不构成对立。"}, {"text": "书包", "is_correct": false, "explanation": "与“从前”无反义关系，“书包”不是时间词，不构成对立。"}], "correct_answer": "现在", "explanations": {"白云": "与“从前”无反义关系，“白云”不是时间词，不构成对立。", "现在": "“现在”指说话的当下，与“从前”指过去构成时间上的反义。", "窗户": "与“从前”无反义关系，“窗户”不是时间词，不构成对立。", "书包": "与“从前”无反义关系，“书包”不是时间词，不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去的时间，泛指很久以前或说话之前的某个时期。", "primary_collocate": null, "pronunciation": "cóng qián", "ipa": "tsʰʊŋ˧˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他现在比从前高多了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市和从前不一样了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是像从前一样爱笑。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前我不爱吃鱼，后来很爱吃。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家从前住在乡下。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友还是和从前一样。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前这里有一家小书店，现在关门了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从前学过画画，现在不画了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不像从前那样常见面了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河比从前干净多了。", "target_word": "从前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從前", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过去的某个时期，常与现在对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大象", "is_correct": false, "explanation": "语义：人不会比大象高，“他现在比大象高多了”与常识不符。"}, {"text": "从前", "is_correct": true, "explanation": "“从前”指过去的某个时期，与“现在”对比，用来比较现在的身高正合适。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：人不可能比大楼高，句子与常识不符。"}, {"text": "云", "is_correct": false, "explanation": "体貌：云没有固定的高度，无法用来比较身高。"}], "explanations": {"大象": "语义：人不会比大象高，“他现在比大象高多了”与常识不符。", "从前": "“从前”指过去的某个时期，与“现在”对比，用来比较现在的身高正合适。", "大楼": "语义：人不可能比大楼高，句子与常识不符。", "云": "体貌：云没有固定的高度，无法用来比较身高。"}, "sentence_index": 0, "correct_answer": "从前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从前我就要毕业了。", "explanation": "这里应该用〈明年〉。“从前”指过去，不能与“就要”搭配，表示即将发生的事。"}, {"text": "我们从前下周考试。", "explanation": "这里应该用〈将来〉。“从前”指过去，不能与“下周”这样的近期将来时间并用。"}, {"text": "今天下午我们从前开会了。", "explanation": "这里应该用〈刚才〉。“从前”指很久以前，不能和“今天下午”这样的近时间并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”是将来，与“现在关门了”的先后顺序相矛盾。"}, {"text": "从前", "is_correct": true, "explanation": "“从前”指过去，与“现在关门了”构成对比，符合句意。"}, {"text": "星期天", "is_correct": false, "explanation": "语义：星期天是某一天，不能作为书店存在的时期，与句意不符。"}, {"text": "大海", "is_correct": false, "explanation": "体貌：大海是广阔的水域，不可能在它的某处开一家小书店。"}], "explanations": {"明天": "语义：“明天”是将来，与“现在关门了”的先后顺序相矛盾。", "从前": "“从前”指过去，与“现在关门了”构成对比，符合句意。", "星期天": "语义：星期天是某一天，不能作为书店存在的时期，与句意不符。", "大海": "体貌：大海是广阔的水域，不可能在它的某处开一家小书店。"}, "sentence_index": 6, "correct_answer": "从前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们从前就要开始学汉语了。", "explanation": "这里应该用〈下个学期〉。“从前”指过去，不能与“就要”搭配，表示即将开始的事。"}, {"text": "从前就要下雨了，我们快回家吧。", "explanation": "这里应该用〈马上〉。“从前”指过去，不能和“就要”表示的即将发生的事搭配。"}, {"text": "此刻，他从前正在钓鱼。", "explanation": "这里应该用〈现在〉。“从前”指很久以前，不能和“此刻”正在进行的动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从前了住在城里，现在住在乡下。", "corrected_sentence": "他从前住在城里，现在住在乡下。", "error_description": "错误在“从前”后加了“了”。“从前”是时间词，不能带“了”，应说“他从前住在城里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街从前的很热闹。", "corrected_sentence": "这条街从前很热闹。", "error_description": "错误在“从前”后多加了“的”。“从前”是时间词，直接放在“很热闹”之前，不能带“的”，应说“这条街从前很热闹。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接", "is_correct": true, "explanation": "接：伸手承住飞来的东西，与“扔”（抛出去）是反义关系。"}, {"text": "踢", "is_correct": false, "explanation": "踢是用脚撞击，与“扔”没有反义关系。"}, {"text": "推", "is_correct": false, "explanation": "推是用力使物体移动，与“扔”没有反义关系。"}, {"text": "拍", "is_correct": false, "explanation": "拍是用手轻击，与“扔”没有反义关系。"}], "correct_answer": "接", "explanations": {"接": "接：伸手承住飞来的东西，与“扔”（抛出去）是反义关系。", "踢": "踢是用脚撞击，与“扔”没有反义关系。", "推": "推是用力使物体移动，与“扔”没有反义关系。", "拍": "拍是用手轻击，与“扔”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
