INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扔是用手把东西丢出去。", "primary_collocate": null, "pronunciation": "rēng", "ipa": "ɻɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他把球扔给了我。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩把石头扔进河里。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把球扔过来。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我扔了一个球给小狗。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把书包扔在沙发上。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别往窗外扔东西。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力扔出了那个球。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢扔飞盘玩。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在公园里扔着雪球。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候常在河边扔石头。", "target_word": "扔", "complexity_tier": "T3", "furigana": "rēng", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔了", "label": "体标"}, {"form": "扔过", "label": "体标"}, {"form": "扔着", "label": "体标"}, {"form": "扔一扔", "label": "重叠"}], "register": "口语", "sense_fingerprint": "用手把东西抛向别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔（rēng）：用手把东西丢出去。"}, {"text": "灯", "is_correct": false, "explanation": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。"}, {"text": "坑", "is_correct": false, "explanation": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。"}, {"text": "争", "is_correct": false, "explanation": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}], "explanations": {"扔": "扔（rēng）：用手把东西丢出去。", "灯": "扔 rēng 与 灯 dēng 声母不同（r / d），灯的意思是灯。", "坑": "扔 rēng 与 坑 kēng 声母不同（r / k），坑的意思是坑洞。", "争": "扔 rēng 与 争 zhēng 声母不同（r / zh），争的意思是争夺。"}, "sentence_index": null, "correct_answer": "扔"}, "level_3": {"options": [{"text": "扔", "is_correct": true, "explanation": "扔：把球抛给对方，符合“把球……给了我”的语境。"}, {"text": "举", "is_correct": false, "explanation": "搭配：“举”不能表示递送，“把球举给了我”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发出声音，不能用于递送球。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不是把球递给别人。"}], "explanations": {"扔": "扔：把球抛给对方，符合“把球……给了我”的语境。", "举": "搭配：“举”不能表示递送，“把球举给了我”不成立。", "唱": "语义：唱是发出声音，不能用于递送球。", "咬": "语义：咬是用牙齿夹住，不是把球递给别人。"}, "sentence_index": 0, "correct_answer": "扔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用脚把球扔进了球门。", "explanation": "这里应该用〈踢〉。扔是用手把东西丢出去，用脚把球送进球门要用〈踢〉，不说〈扔〉。"}, {"text": "他把一盆水扔进了河里。", "explanation": "这里应该用〈倒〉。扔是用手把东西丢出去，水是液体，不能用扔，要说〈倒〉。"}, {"text": "他轻轻地把杯子扔在桌上。", "explanation": "这里应该用〈放〉。扔带有用力抛出的动作，“轻轻”放置要用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
