INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扔是把不要的东西丢掉。", "primary_collocate": null, "pronunciation": "rēng", "ipa": "ɻɤŋ˥", "syllable_count": 1, "sentences": [{"text": "这件旧衣服我想扔了。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把垃圾扔在地上。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把坏了的手机扔了。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些东西还有用，别扔。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把没吃完的饭扔了。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把空瓶子扔进垃圾桶。", "target_word": "扔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧书扔了太可惜。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不扔旧东西。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么把我的画扔了？", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过期的牛奶要扔掉。", "target_word": "扔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "扔了", "label": "体标"}, {"form": "扔过", "label": "体标"}, {"form": "扔掉", "label": "复合"}], "register": "口语", "sense_fingerprint": "把不要的东西丢掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 