INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抱怨是心里不高兴，一直说别人不好。", "primary_collocate": null, "pronunciation": "bào yuàn", "ipa": "pɑʊ̯˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他总是抱怨同事不好好工作。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别老抱怨了，快点做吧。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈一直抱怨爸爸回家太晚。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友总抱怨老师给的作业太多。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他心里不高兴，一直抱怨弟弟。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么一直抱怨我？", "target_word": "抱怨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子抱怨妈妈不给他买玩具。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抱怨过丈夫很多次。", "target_word": "抱怨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边走一边抱怨朋友来晚了。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都不喜欢听他抱怨别人。", "target_word": "抱怨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抱怨了", "label": "体标"}, {"form": "抱怨着", "label": "体标"}, {"form": "抱怨过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：心里不高兴，一直说别人不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抱怨", "is_correct": true, "explanation": "“抱怨”表示心里不满、一直说别人不好，与“总是”和“不好好工作”的情况相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是肯定别人的好表现，不能用来形容不好好工作的人。"}, {"text": "称赞", "is_correct": false, "explanation": "语义：“称赞”针对好的表现，与“不好好工作”相矛盾。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，不能带“同事不好好工作”这样的小句作宾语。"}], "explanations": {"抱怨": "“抱怨”表示心里不满、一直说别人不好，与“总是”和“不好好工作”的情况相符。", "表扬": "语义：“表扬”是肯定别人的好表现，不能用来形容不好好工作的人。", "称赞": "语义：“称赞”针对好的表现，与“不好好工作”相矛盾。", "微笑": "配价：“微笑”是不及物动词，不能带“同事不好好工作”这样的小句作宾语。"}, "sentence_index": 0, "correct_answer": "抱怨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抱怨这次旅行的风景很美。", "explanation": "这里应该用〈称赞〉。抱怨表示心里不满、一直说别人不好，不能用来夸奖风景。"}, {"text": "我抱怨老师耐心地帮我改作业。", "explanation": "这里应该用〈感谢〉。抱怨表示不满，不能用来说别人的好意。"}, {"text": "他抱怨同学的作文写得很好。", "explanation": "这里应该用〈表扬〉。抱怨表示不满，不能用来夸同学写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抱怨", "is_correct": true, "explanation": "“抱怨”表示对别人的做法不满并说出来，与“不给他买玩具”的情况相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示夸奖，不能用来说“妈妈不给买玩具”这种让人不满的事。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”是因为得到好处而感谢，与“不给买玩具”相矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“妈妈不给他买玩具”作宾语。"}], "explanations": {"抱怨": "“抱怨”表示对别人的做法不满并说出来，与“不给他买玩具”的情况相符。", "赞美": "语义：“赞美”表示夸奖，不能用来说“妈妈不给买玩具”这种让人不满的事。", "感激": "语义：“感激”是因为得到好处而感谢，与“不给买玩具”相矛盾。", "哭": "配价：“哭”是不及物动词，不能带“妈妈不给他买玩具”作宾语。"}, "sentence_index": 6, "correct_answer": "抱怨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都抱怨这次演出精彩极了。", "explanation": "这里应该用〈赞赏〉。抱怨表示不满，不能用来称赞演出精彩。"}, {"text": "老师抱怨她的作品很有创意。", "explanation": "这里应该用〈赞叹〉。抱怨表示不满，不能用来赞叹作品有创意。"}, {"text": "老板抱怨他的报告写得很清楚。", "explanation": "这里应该用〈夸奖〉。抱怨表示不满，不能用来夸报告写得清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是跟同事抱怨得工作太累。", "corrected_sentence": "他总是跟同事抱怨工作太累。", "error_description": "错误形式：“抱怨得工作太累”。正确形式：“抱怨工作太累”。“得”用在动词后引出补语，“抱怨”后直接接宾语小句，不需要“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子明天会向妈妈抱怨了作业太多。", "corrected_sentence": "孩子明天会向妈妈抱怨作业太多。", "error_description": "错误形式：“抱怨了作业太多”。正确形式：“抱怨作业太多”。“明天会”表示将来，“了”表示动作已经完成，二者矛盾，“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
