INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "描写是用话把看到的样子写出来。", "primary_collocate": null, "pronunciation": "miáo xiě", "ipa": "miɑʊ˧˥ ɕiɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请你把看到的公园描写一下。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在日记里描写了今天的天气。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我描写一下新同学的样子。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇作文要描写自己最爱的动物。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他描写的那只小狗，又小又白。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看完图片，就用几句话描写它。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，描写人物要写清楚样子。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把海边的日落描写得很清楚。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在描写教室里的东西。", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能描写一下昨天看到的那个人吗？", "target_word": "描写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "描写了", "label": "体标（了）"}, {"form": "描写过", "label": "体标（过）"}, {"form": "描写着", "label": "体标（着）"}, {"form": "描寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把亲眼看到的人或东西的样子用话写下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3325f6b1-73dc-4a1c-9d96-b519a163574c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描写", "is_correct": true, "explanation": "“请你把看到的公园描写一下”指用话把看到的样子写出来，符合语境。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除或分解，请人把公园拆一下不合常理，句子无法成立。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”的对象是花果、叶子，不能用于公园。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指用力分开纸张等，用于公园不成立。"}], "explanations": {"描写": "“请你把看到的公园描写一下”指用话把看到的样子写出来，符合语境。", "拆": "语义：“拆”指拆除或分解，请人把公园拆一下不合常理，句子无法成立。", "摘": "搭配：“摘”的对象是花果、叶子，不能用于公园。", "撕": "语义：“撕”指用力分开纸张等，用于公园不成立。"}, "sentence_index": 0, "correct_answer": "描写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用算盘描写了账目。", "explanation": "这里应该用〈计算〉。算账要用计算，描写是用文字写出样子，与算盘无关。"}, {"text": "他用画笔描写了那只猫。", "explanation": "这里应该用〈绘制〉。用画笔把猫画出来是绘制，描写是用文字把看到的样子写出来，不用于作画。"}, {"text": "老师用故事描写了一个道理。", "explanation": "这里应该用〈讲〉。道理要讲解，描写的对象是人或景物的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描写", "is_correct": true, "explanation": "“老师说，描写人物要写清楚样子”指用文字写出人物的样子，符合语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，描写人物不能说煮人物。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是对物体的动作，与“写清楚样子”的要求不符。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于树木、草坪、头发，不能修剪人物。"}], "explanations": {"描写": "“老师说，描写人物要写清楚样子”指用文字写出人物的样子，符合语境。", "煮": "语义：“煮”的对象是食物，描写人物不能说煮人物。", "踢": "语义：“踢”是对物体的动作，与“写清楚样子”的要求不符。", "修剪": "搭配：“修剪”多用于树木、草坪、头发，不能修剪人物。"}, "sentence_index": 6, "correct_answer": "描写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师描写了这道题的答案。", "explanation": "这里应该用〈写出〉。答案是要写出来的结果，不是人或景物的样子，不能用“描写”。"}, {"text": "工人用机器描写了照片。", "explanation": "这里应该用〈打印〉。用机器输出照片要用打印，描写是用文字写出看到的样子。"}, {"text": "他描写了字典上的生词。", "explanation": "这里应该用〈查〉。在字典上找生词是查，描写是把看到的样子写成文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没描写了这种动物。", "corrected_sentence": "我从来没描写过这种动物。", "error_description": "“没”表示未曾经历时要用体标“过”，不能用“了”，应改为“没描写过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那个人的样子描写的很清楚。", "corrected_sentence": "他把那个人的样子描写得很清楚。", "error_description": "“描写得很清楚”中“得”引出程度补语，学习者常误用“的”，应改为“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15cbd8ad-718e-4fbc-8e03-b5bafdea70d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
