INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "擅长是对一件事做得特别好。", "primary_collocate": null, "pronunciation": "shàn cháng", "ipa": "ʂan˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他很擅长画画，所以常常拿奖。", "target_word": "擅长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐擅长做饭，家人都爱吃她做的菜。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李擅长游泳，每次比赛都拿第一。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不擅长数学，一看到题就头疼。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师擅长讲故事，孩子们都爱听。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你擅长什么运动？", "target_word": "擅长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我弟弟擅长踢足球，所以是队里的前锋。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他擅长用笑话让大家放松。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈最擅长做面条，我每周都要吃。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生擅长治小孩的病。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不擅长", "label": "否定"}], "register": "中性", "sense_fingerprint": "对某件事做得特别好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擅长", "is_correct": true, "explanation": "“擅长”表示画画本领高，所以常常拿奖，与句意相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌画画与“所以常常拿奖”的因果不通，句意矛盾。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：厌烦画画不会带来“常常拿奖”的结果，句意矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "搭配：“反对”多接意见、政策、做法，不说“反对画画”。"}], "explanations": {"擅长": "“擅长”表示画画本领高，所以常常拿奖，与句意相符。", "讨厌": "语义：讨厌画画与“所以常常拿奖”的因果不通，句意矛盾。", "厌烦": "语义：厌烦画画不会带来“常常拿奖”的结果，句意矛盾。", "反对": "搭配：“反对”多接意见、政策、做法，不说“反对画画”。"}, "sentence_index": 0, "correct_answer": "擅长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我擅长星期一，每周一都特别有精神。", "explanation": "这里应该用〈喜欢〉。“擅长”指在某方面有本领，星期一是时间，不能擅长；应说“我喜欢星期一”。"}, {"text": "我很擅长这条路，闭着眼也能走。", "explanation": "这里应该用〈熟悉〉。“擅长”后接做事或技能，不能接地点“这条路”；对路熟悉应说“熟悉”。"}, {"text": "他很擅长感冒，一换季就病了。", "explanation": "这里应该用〈容易〉。感冒是容易发生的事，不是本领，应说“很容易感冒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擅长", "is_correct": true, "explanation": "“擅长”表示踢球踢得好，与“是队里的前锋”相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃踢球就当不了队里的前锋，与句子后半部分矛盾。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：害怕踢球与“是队里的前锋”的身份矛盾。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：“嫌弃”多接人或物，不说“嫌弃踢足球”。"}], "explanations": {"擅长": "“擅长”表示踢球踢得好，与“是队里的前锋”相符。", "放弃": "语义：放弃踢球就当不了队里的前锋，与句子后半部分矛盾。", "害怕": "语义：害怕踢球与“是队里的前锋”的身份矛盾。", "嫌弃": "搭配：“嫌弃”多接人或物，不说“嫌弃踢足球”。"}, "sentence_index": 6, "correct_answer": "擅长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很擅长怕打针，每次都哭。", "explanation": "这里应该用〈害怕〉。“擅长”指做事本领，怕打针是心理感受，应说“很害怕打针”。"}, {"text": "这间教室很擅长讲课，学生们都很喜欢。", "explanation": "这里应该用〈适合〉。“擅长”的主语应是人或团体，教室不能擅长做事，应说“很适合讲课”。"}, {"text": "他擅长拿走了我的书，也没有告诉我。", "explanation": "这里应该用〈擅自〉。“擅自”指未经允许就做事，不是本领，应说“擅自拿走了我的书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他擅长了修自行车，邻居都请他帮忙。", "corrected_sentence": "他擅长修自行车，邻居都请他帮忙。", "error_description": "错误在“擅长”后面加了“了”。“擅长”表示一种长期的能力，不表示完成，应说“他擅长修自行车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐没擅长唱歌，每次聚会都唱。", "corrected_sentence": "我姐姐擅长唱歌，每次聚会都唱。", "error_description": "错误在“擅长”前面多了“没”。“擅长”表示一种本领，不能用“没”否定，否定应说“不擅长”；句中应说“我姐姐擅长唱歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
