INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在某方面具有特别的技能或本领，做得比一般人好。", "primary_collocate": null, "pronunciation": "shàn cháng", "ipa": "ʂan˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他擅长修电脑，所以朋友的电脑坏了都找他。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她擅长英语，工作时常帮同事翻译。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张擅长书法，写的字很多人喜欢。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司擅长做手机软件。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同桌擅长唱歌，声音比一般人好听。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他擅长跟陌生人聊天，很快就能交朋友。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥擅长下棋，所以同学都下不过他。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她擅长画漫画，还参加过比赛。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王擅长摄影，拍的照片像画一样。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师擅长教外国人汉语，学生们都进步很快。", "target_word": "擅长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不擅长", "label": "否定"}], "register": "中性", "sense_fingerprint": "某方面有特别的技能，比一般人强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擅长", "is_correct": true, "explanation": "“擅长”表示有修电脑的本领，与“朋友都找他”相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌修电脑与“所以朋友的电脑坏了都找他”的因果不通，句意矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃修电脑，朋友就不会都来找他，与句意矛盾。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：“嫌弃”多接人或物，不说“嫌弃修电脑”。"}], "explanations": {"擅长": "“擅长”表示有修电脑的本领，与“朋友都找他”相符。", "讨厌": "语义：讨厌修电脑与“所以朋友的电脑坏了都找他”的因果不通，句意矛盾。", "放弃": "语义：放弃修电脑，朋友就不会都来找他，与句意矛盾。", "嫌弃": "搭配：“嫌弃”多接人或物，不说“嫌弃修电脑”。"}, "sentence_index": 0, "correct_answer": "擅长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司擅长去年，去年就特别忙。", "explanation": "这里应该去掉“擅长”，说“这家公司去年就特别忙”。“擅长”指做事有本领，时间不能被擅长。"}, {"text": "这家公司擅长下雨，每到雨季生意就特别好。", "explanation": "这里应该用〈赶上〉。“擅长”指做事有本领，下雨是天气，不能擅长；应说“赶上雨季，生意就特别好”。"}, {"text": "这家公司擅长冬天，每到冬天就特别忙。", "explanation": "这里应该用〈在〉。“擅长”指做事有本领，冬天是时间，不能擅长；应说“在冬天就特别忙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擅长", "is_correct": true, "explanation": "“擅长”表示下棋水平高，与“同学都下不过他”相符。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：厌烦下棋的人不会下得很好，与“同学都下不过他”的技艺矛盾。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：害怕下棋与“同学都下不过他”的技艺描写矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "搭配：“反对”多接意见、政策、做法，不说“反对下棋”。"}], "explanations": {"擅长": "“擅长”表示下棋水平高，与“同学都下不过他”相符。", "厌烦": "语义：厌烦下棋的人不会下得很好，与“同学都下不过他”的技艺矛盾。", "害怕": "语义：害怕下棋与“同学都下不过他”的技艺描写矛盾。", "反对": "搭配：“反对”多接意见、政策、做法，不说“反对下棋”。"}, "sentence_index": 6, "correct_answer": "擅长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我朋友擅长生日，每年都记得我的生日。", "explanation": "这里应该用〈记住〉。“擅长”指做事有本领，记生日不是本领，应说“记住我的生日”。"}, {"text": "我擅长这位老师，前天刚见过他。", "explanation": "这里应该用〈认识〉。“擅长”后接做事或技能，不能接人，认识某人应说“认识这位老师”。"}, {"text": "他擅长星期三，每周三都很开心。", "explanation": "这里应该用〈喜欢〉。“擅长”指做事有本领，星期三是时间，不能擅长；应说“喜欢星期三”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她擅长了英语翻译，经常帮我看文件。", "corrected_sentence": "她擅长英语翻译，经常帮我看文件。", "error_description": "错误在“擅长”后面加了“了”。“擅长”表示一种能力，不表示完成，应说“她擅长英语翻译”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹没擅长跳舞，比赛常拿奖。", "corrected_sentence": "我妹妹擅长跳舞，比赛常拿奖。", "error_description": "错误在“擅长”前面多了“没”。“擅长”表示一种本领，不能用“没”否定，否定应说“不擅长”；句中应说“我妹妹擅长跳舞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
