INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94649, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有意是心里想好了才去做。", "primary_collocate": null, "pronunciation": "yǒu yì", "ipa": "joʊ˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "他有意把门关上了。", "target_word": "有意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我是有意告诉你的。", "target_word": "有意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有意走得很慢。", "target_word": "有意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有意留下一张纸条。", "target_word": "有意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师有意问了他一个问题。", "target_word": "有意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有意把电话放在桌上。", "target_word": "有意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做是有意的。", "target_word": "有意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有意没说出真话。", "target_word": "有意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有意把椅子搬到门口。", "target_word": "有意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈有意给你留了一碗你爱喝的汤。", "target_word": "有意", "complexity_tier": "T3", "furigana": "māma yǒu yì gěi nǐ liú le yì wǎn nǐ ài hē de tāng", "sentence_source": "generated"}], "morphological_forms": [{"form": "有意无意", "label": "复合"}], "register": "中性", "sense_fingerprint": "想好了才去做，不是偶然", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有意", "is_correct": true, "explanation": "正确答案：有意 yǒu yì，副词，表示想好了才去做。"}, {"text": "有利", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是有好处。"}, {"text": "右翼", "is_correct": false, "explanation": "yòu 与 yǒu 声调不同，意思是右边或右翼。"}, {"text": "游医", "is_correct": false, "explanation": "yóu 与 yǒu 声调不同，yī 与 yì 声调也不同，意思是流动行医的医生。"}, {"text": "有戏", "is_correct": false, "explanation": "xì 与 yì 声母不同，意思是有希望。"}], "explanations": {"有意": "正确答案：有意 yǒu yì，副词，表示想好了才去做。", "有利": "lì 与 yì 声母不同，意思是有好处。", "右翼": "yòu 与 yǒu 声调不同，意思是右边或右翼。", "游医": "yóu 与 yǒu 声调不同，yī 与 yì 声调也不同，意思是流动行医的医生。", "有戏": "xì 与 yì 声母不同，意思是有希望。"}, "sentence_index": null, "correct_answer": "有意"}, "level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "有意：故意地，表示这是事先想好才做的。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“关上了”的完成状态不符。"}, {"text": "不停", "is_correct": false, "explanation": "体貌：“不停”表示持续不断，与“关上了”这样一次完成的动作不符。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱，不能与已完成的“关上了”搭配。"}], "explanations": {"有意": "有意：故意地，表示这是事先想好才做的。", "正在": "体貌：“正在”表示动作进行中，与“关上了”的完成状态不符。", "不停": "体貌：“不停”表示持续不断，与“关上了”这样一次完成的动作不符。", "千万": "语义：“千万”多用于叮嘱，不能与已完成的“关上了”搭配。"}, "sentence_index": 0, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有意不小心把纸条掉在地上了。", "explanation": "这里误把〈有意〉（故意）用在〈不小心〉的行为上，应改用〈无意〉。"}, {"text": "我有意脸红了，连耳朵都红了。", "explanation": "这里误把〈有意〉（故意）用于不由自主的脸红，应改用〈不由自主〉。"}, {"text": "她有意偶然遇见了老同学。", "explanation": "这里误把〈有意〉（故意）用于偶然的相遇，应改用〈碰巧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94649, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有意", "is_correct": true, "explanation": "正确答案：有意 yǒu yì，副词，表示想好了才去做。"}, {"text": "有事", "is_correct": false, "explanation": "shì 与 yì 声母不同，意思是有事情要办。"}, {"text": "有力", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是有力量。"}, {"text": "犹疑", "is_correct": false, "explanation": "yóu 与 yǒu 声调不同，yí 与 yì 声调也不同，意思是犹豫不定。"}, {"text": "油衣", "is_correct": false, "explanation": "yóu 与 yǒu 声调不同，yī 与 yì 声调也不同，意思是防雨的油布衣。"}], "explanations": {"有意": "正确答案：有意 yǒu yì，副词，表示想好了才去做。", "有事": "shì 与 yì 声母不同，意思是有事情要办。", "有力": "lì 与 yì 声母不同，意思是有力量。", "犹疑": "yóu 与 yǒu 声调不同，yí 与 yì 声调也不同，意思是犹豫不定。", "油衣": "yóu 与 yǒu 声调不同，yī 与 yì 声调也不同，意思是防雨的油布衣。"}, "sentence_index": null, "correct_answer": "有意"}, "level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "有意：故意的，表示这样做是出于主动的打算。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，不能用来形容做法的性质。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”是温度，不能用来评价做法。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”指高度，不能用来说一种做法是高的。"}], "explanations": {"有意": "有意：故意的，表示这样做是出于主动的打算。", "红": "语义：“红”是颜色，不能用来形容做法的性质。", "冷": "语义：“冷”是温度，不能用来评价做法。", "高": "语义：“高”指高度，不能用来说一种做法是高的。"}, "sentence_index": 6, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈被迫有意给你留了一碗汤。", "explanation": "这里误把〈有意〉（出于自己的打算）用于被迫的事，应改用〈只好〉。"}, {"text": "这碗汤很有意，你快喝吧。", "explanation": "这里“有意”不表示“有趣”，应说“有意思”；这是把词义用错了。"}, {"text": "妈妈有意不得不给你留了一碗汤。", "explanation": "这里误把〈有意〉（主动去做）与〈不得不〉（被迫）放在一起，应改用〈只能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
