INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "次于是比另一个差一点，排在后面。", "primary_collocate": null, "pronunciation": "cì yú", "ipa": "tsʰɨ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "我的成绩次于小王，排第二。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的速度次于那个。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画次于哥哥的，但也不错。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，我队的分数次于对方。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的质量只次于那件。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑得很快，只次于同学小李。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容次于第一本，但也很好看。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的收成次于去年。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的汉语水平次于老师，比同学们都好。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们班，小明的个子次于小高，排第二。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "水平、成绩等比另一个稍差，排在其后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94653, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次于", "is_correct": true, "explanation": "次于（cì yú）：比另一个稍差，排在其后。"}, {"text": "词语", "is_correct": false, "explanation": "cí yǔ（第二、第三声）与 cì yú（第四、第二声）声调不同，意思是词语。"}, {"text": "似于", "is_correct": false, "explanation": "sì yú 与 cì yú 声母不同（s/c），意思是相似于。"}, {"text": "至于", "is_correct": false, "explanation": "zhì yú 与 cì yú 声母不同（zh/c），意思是至于、关于。"}], "explanations": {"次于": "次于（cì yú）：比另一个稍差，排在其后。", "词语": "cí yǔ（第二、第三声）与 cì yú（第四、第二声）声调不同，意思是词语。", "似于": "sì yú 与 cì yú 声母不同（s/c），意思是相似于。", "至于": "zhì yú 与 cì yú 声母不同（zh/c），意思是至于、关于。"}, "sentence_index": null, "correct_answer": "次于"}, "level_3": {"options": [{"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归入某类或归某人所有，句中要求的是与小王的排名比较，“属于”不符，句子不通。"}, {"text": "次于", "is_correct": true, "explanation": "“次于”表示比对方稍差、排在其后，与“排第二”相符。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”的主体须是人或团体，不能说“成绩配合小王”。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”要求人作主语，宾语是意见或请求，“成绩同意小王”不通。"}], "explanations": {"属于": "语义：“属于”表示归入某类或归某人所有，句中要求的是与小王的排名比较，“属于”不符，句子不通。", "次于": "“次于”表示比对方稍差、排在其后，与“排第二”相符。", "配合": "搭配：“配合”的主体须是人或团体，不能说“成绩配合小王”。", "同意": "配价：“同意”要求人作主语，宾语是意见或请求，“成绩同意小王”不通。"}, "sentence_index": 0, "correct_answer": "次于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市次于火车站的东边。", "explanation": "这里应该用〈位于〉。“位于”说明处于某个位置，“次于”只用于地位、水平等高低比较，不能说明场所。"}, {"text": "这个问题次于数学范围。", "explanation": "这里应该用〈属于〉。“属于”表示归入某一类别，“次于”不能表示归属关系。"}, {"text": "今天的气温次于零度。", "explanation": "这里应该用〈低于〉。“低于”用于数值或温度的界线，“次于”用于排名、水平的比较，不能用于温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胜过", "is_correct": false, "explanation": "语义：“胜过”表示更好，与后半句“但也很好看”的转折不符。"}, {"text": "次于", "is_correct": true, "explanation": "“次于”表示比第一本稍差，与“但也很好看”的转折相符。"}, {"text": "居于", "is_correct": false, "explanation": "语义：“居于”指处于某个位置，句中要的是“比第一本稍差”的比较，“居于”不表达这一关系。"}, {"text": "敬佩", "is_correct": false, "explanation": "搭配：“敬佩”的主体须是人，“内容”不能敬佩他人。"}], "explanations": {"胜过": "语义：“胜过”表示更好，与后半句“但也很好看”的转折不符。", "次于": "“次于”表示比第一本稍差，与“但也很好看”的转折相符。", "居于": "语义：“居于”指处于某个位置，句中要的是“比第一本稍差”的比较，“居于”不表达这一关系。", "敬佩": "搭配：“敬佩”的主体须是人，“内容”不能敬佩他人。"}, "sentence_index": 6, "correct_answer": "次于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家次于他的决定。", "explanation": "这里应该用〈支持〉。“支持”表示赞成或帮助，“次于”只用于比较高低、排序，不能表示支持。"}, {"text": "这台机器次于很大的声音。", "explanation": "这里应该用〈发出〉。“发出”表示产生声音，“次于”不能表示发出声响。"}, {"text": "这件事次于大家的注意。", "explanation": "这里应该用〈引起〉。“引起”表示使某种关注产生，“次于”不能表示引发关注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的汉语水平次于了我，但差距很小。", "corrected_sentence": "他的汉语水平次于我，但差距很小。", "error_description": "错误在“次于”后面多了“了”。“次于”表示比较关系，一般不带“了”，应改为“次于我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的规模很次于大公司，但发展很快。", "corrected_sentence": "这家公司的规模次于大公司，但发展很快。", "error_description": "错误在“次于”前面多了“很”。“次于”表示比较关系，不能被程度副词“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优于", "is_correct": true, "explanation": "反义：“优于”表示质量、水平比对方高，与“次于”相对。"}, {"text": "逃避", "is_correct": false, "explanation": "无关：“逃避”表示躲开责任或困难，与质量高低无关。"}, {"text": "模仿", "is_correct": false, "explanation": "无关：“模仿”表示照着别人的样子做，与质量比较无关。"}, {"text": "忍耐", "is_correct": false, "explanation": "无关：“忍耐”表示克制、承受，与质量比较无关。"}], "correct_answer": "优于", "explanations": {"优于": "反义：“优于”表示质量、水平比对方高，与“次于”相对。", "逃避": "无关：“逃避”表示躲开责任或困难，与质量高低无关。", "模仿": "无关：“模仿”表示照着别人的样子做，与质量比较无关。", "忍耐": "无关：“忍耐”表示克制、承受，与质量比较无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
