INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "在地位、质量或顺序上排在某人或某事物之后。", "primary_collocate": null, "pronunciation": "cì yú", "ipa": "tsʰɨ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "在公司里，经理的地位次于老板。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河的长度次于长江。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这次比赛里，我的排名次于王老师。", "target_word": "次于", "complexity_tier": "T3", "furigana": "zài zhè cì bǐsài lǐ, wǒ de páimíng cì yú Wáng lǎoshī.", "sentence_source": "generated"}, {"text": "这种茶的质量次于那种，价格也低。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在排名中，我们学校次于北京大学。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职位次于校长，是副校长。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队的实力次于冠军队。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在出场的顺序上，我次于小王。", "target_word": "次于", "complexity_tier": "T3", "furigana": "zài chūchǎng de shùnxù shàng, wǒ cì yú Xiǎo Wáng.", "sentence_source": "generated"}, {"text": "这次考试，他的成绩次于第一名。", "target_word": "次于", "complexity_tier": "T3", "furigana": "zhè cì kǎoshì, tā de chéngjì cì yú dì yī míng.", "sentence_source": "generated"}, {"text": "这台电脑的性能次于最新的那台。", "target_word": "次于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "地位、质量或顺序上排在某人或某物之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次于", "is_correct": true, "explanation": "次于（cì yú）：在地位、质量或顺序上排在某人或某事物之后。"}, {"text": "词语", "is_correct": false, "explanation": "cí yǔ（第二、第三声）与 cì yú（第四、第二声）声调不同，意思是词语。"}, {"text": "似于", "is_correct": false, "explanation": "sì yú 与 cì yú 声母不同（s/c），意思是相似于。"}, {"text": "至于", "is_correct": false, "explanation": "zhì yú 与 cì yú 声母不同（zh/c），意思是至于、关于。"}], "explanations": {"次于": "次于（cì yú）：在地位、质量或顺序上排在某人或某事物之后。", "词语": "cí yǔ（第二、第三声）与 cì yú（第四、第二声）声调不同，意思是词语。", "似于": "sì yú 与 cì yú 声母不同（s/c），意思是相似于。", "至于": "zhì yú 与 cì yú 声母不同（zh/c），意思是至于、关于。"}, "sentence_index": null, "correct_answer": "次于"}, "level_3": {"options": [{"text": "领导", "is_correct": false, "explanation": "语义：“领导”是上级带领下级，“老板”是经理的上级，经理不能领导老板。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”的主语须是人，“地位”不能认识老板。"}, {"text": "次于", "is_correct": true, "explanation": "“次于”表示地位排在老板之后，与“经理”的职位关系相符。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”的主体须是人或团体，不能说“地位配合老板”。"}], "explanations": {"领导": "语义：“领导”是上级带领下级，“老板”是经理的上级，经理不能领导老板。", "认识": "语义：“认识”的主语须是人，“地位”不能认识老板。", "次于": "“次于”表示地位排在老板之后，与“经理”的职位关系相符。", "配合": "搭配：“配合”的主体须是人或团体，不能说“地位配合老板”。"}, "sentence_index": 0, "correct_answer": "次于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份礼物次于朋友。", "explanation": "这里应该用〈来自〉。“来自”表示来源，“次于”只用于地位、质量或顺序的比较，不能表示来源。"}, {"text": "这首歌次于春天。", "explanation": "这里应该用〈像〉。“像”表示相似，“次于”只表示排序上的高低，不能用于比喻。"}, {"text": "这本书次于图书馆。", "explanation": "这里应该用〈属于〉。“属于”表示归属关系，“次于”不能表示归属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追随", "is_correct": false, "explanation": "语义：“追随”的主体是人或团体，“实力”不能追随他人。"}, {"text": "模仿", "is_correct": false, "explanation": "搭配：“模仿”的主体是人或团体，“实力”不能模仿冠军队。"}, {"text": "次于", "is_correct": true, "explanation": "“次于”表示实力比冠军队稍差，与句意相符。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”的主体须是人，宾语是责任或困难，不能说“实力逃避冠军队”。"}], "explanations": {"追随": "语义：“追随”的主体是人或团体，“实力”不能追随他人。", "模仿": "搭配：“模仿”的主体是人或团体，“实力”不能模仿冠军队。", "次于": "“次于”表示实力比冠军队稍差，与句意相符。", "逃避": "搭配：“逃避”的主体须是人，宾语是责任或困难，不能说“实力逃避冠军队”。"}, "sentence_index": 6, "correct_answer": "次于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师次于这本书。", "explanation": "这里应该用〈推荐〉。“推荐”表示向别人介绍好的事物，“次于”不能表示推荐。"}, {"text": "这台机器次于很大的声音。", "explanation": "这里应该用〈发出〉。“发出”表示产生声音，“次于”不能表示发出声响。"}, {"text": "我们次于教室。", "explanation": "这里应该用〈打扫〉。“打扫”表示清理房间的动作，“次于”不能表示清洁行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店的服务很次于那家，但价格便宜。", "corrected_sentence": "这家饭店的服务次于那家，但价格便宜。", "error_description": "错误在“次于”前面多了“很”。“次于”表示比较关系，不能被“很”修饰，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的排名次于了那所，但设施很好。", "corrected_sentence": "这所学校的排名次于那所，但设施很好。", "error_description": "错误在“次于”后面多了“了”。“次于”表示比较关系，一般不带“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感情，与“次等”没有反义关系。"}, {"text": "上等", "is_correct": true, "explanation": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“次等”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容清楚分明，与“次等”没有反义关系。"}], "correct_answer": "上等", "explanations": {"温暖": "“温暖”形容温度或感情，与“次等”没有反义关系。", "上等": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。", "迅速": "“迅速”形容速度快，与“次等”没有反义关系。", "清晰": "“清晰”形容清楚分明，与“次等”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容面积广大，与“次等”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”形容山势或坡度很陡，与“次等”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度庄重或不随便，与“次等”没有反义关系。"}, {"text": "上等", "is_correct": true, "explanation": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。"}], "correct_answer": "上等", "explanations": {"辽阔": "“辽阔”形容面积广大，与“次等”没有反义关系。", "陡峭": "“陡峭”形容山势或坡度很陡，与“次等”没有反义关系。", "严肃": "“严肃”形容态度庄重或不随便，与“次等”没有反义关系。", "上等": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级或质量不是最好的，比最好的差一点。", "primary_collocate": null, "pronunciation": "cì děng", "ipa": "tsʰɨ˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这块肉是次等的，不是最好的。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了次等的鱼，因为它比较便宜。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最好的票卖完了，只有次等的座位。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子有小问题，是次等的。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一等的梨已经卖完，只剩次等的。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店的鸡蛋是次等的，不太新鲜。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好茶太贵，我只能喝次等的。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的布是次等的，没有那件好。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了次等的房间，因为最好的太贵。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的米是次等的，比不上店里的好米。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次等品", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不是最好的，比最好的差一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头等", "is_correct": false, "explanation": "语义：“头等”指第一等、最好的，与后半句“不是最好的”矛盾。"}, {"text": "次等", "is_correct": true, "explanation": "“次等”指等级较低，与后半句“不是最好的”相符，是正确答案。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，肉一般不用“甜”来说等级，此处搭配不当。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体态，不用来形容肉的等级。"}], "explanations": {"头等": "语义：“头等”指第一等、最好的，与后半句“不是最好的”矛盾。", "次等": "“次等”指等级较低，与后半句“不是最好的”相符，是正确答案。", "甜": "搭配：“甜”形容味道，肉一般不用“甜”来说等级，此处搭配不当。", "胖": "体貌：“胖”形容人或动物的体态，不用来形容肉的等级。"}, "sentence_index": 0, "correct_answer": "次等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事是次等的，先别管它。", "explanation": "这里应该用〈次要〉。次等指质量或等级较差，不用来说事情的主次。"}, {"text": "他次等地完成了任务。", "explanation": "这里应该用〈草率〉。“次等”只说质量或等级低，不用来描述做事的方式；说做事马虎要用〈草率〉。"}, {"text": "他在比赛里拿了次等，离冠军只差一步。", "explanation": "这里应该用〈亚军〉。“次等”指“不是最好的”，不用来表示比赛名次，第二名要说“亚军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名贵", "is_correct": false, "explanation": "语义：“名贵”指珍贵、价格高，与“太贵”重复，且与“只能喝”的无奈语气矛盾。"}, {"text": "次等", "is_correct": true, "explanation": "“次等”指等级较低，与“太贵”形成对应，表示只能选择较差的茶，是正确答案。"}, {"text": "满", "is_correct": false, "explanation": "搭配：“满”形容容器装得多，不说茶是满的，此处搭配不当。"}, {"text": "壮", "is_correct": false, "explanation": "体貌：“壮”形容人的体格，不用来形容茶。"}], "explanations": {"名贵": "语义：“名贵”指珍贵、价格高，与“太贵”重复，且与“只能喝”的无奈语气矛盾。", "次等": "“次等”指等级较低，与“太贵”形成对应，表示只能选择较差的茶，是正确答案。", "满": "搭配：“满”形容容器装得多，不说茶是满的，此处搭配不当。", "壮": "体貌：“壮”形容人的体格，不用来形容茶。"}, "sentence_index": 6, "correct_answer": "次等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从这里到学校的距离是次等的，走路要半小时。", "explanation": "“次等”指等级、质量，不能用来说距离；说距离远要用〈远〉。"}, {"text": "他的体重是次等的，比我胖一点。", "explanation": "这里应该用〈重〉。“次等”指等级、质量，不能用来说体重；“比我胖一点”应说“比我重”。"}, {"text": "我们会议的时间是次等的，有两个小时。", "explanation": "“次等”指等级、质量，不能用来说时长；说时间长要用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条鱼是次等地，价格便宜多了。", "corrected_sentence": "这条鱼是次等的，价格便宜多了。", "error_description": "结构助词用错。错误形式是“是次等地”，正确形式是“是次等的”。“次等”是形容词，作谓语时用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张次等地桌子，还能用。", "corrected_sentence": "这张次等的桌子，还能用。", "error_description": "结构助词用错。错误形式是“次等地桌子”，正确形式是“次等的桌子”。“次等”修饰名词“桌子”时要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锋利", "is_correct": false, "explanation": "“锋利”形容刀刃等尖快，与“次等”没有反义关系。"}, {"text": "上等", "is_correct": true, "explanation": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地松软或软和，与“次等”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序、不乱，与“次等”没有反义关系。"}], "correct_answer": "上等", "explanations": {"锋利": "“锋利”形容刀刃等尖快，与“次等”没有反义关系。", "上等": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。", "柔软": "“柔软”形容质地松软或软和，与“次等”没有反义关系。", "整齐": "“整齐”指排列有序、不乱，与“次等”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“次等”没有反义关系。"}, {"text": "深刻", "is_correct": false, "explanation": "“深刻”形容印象或认识透彻，与“次等”没有反义关系。"}, {"text": "上等", "is_correct": true, "explanation": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。"}, {"text": "活泼", "is_correct": false, "explanation": "“活泼”形容性格或气氛生动，与“次等”没有反义关系。"}], "correct_answer": "上等", "explanations": {"明亮": "“明亮”形容光线充足或颜色鲜亮，与“次等”没有反义关系。", "深刻": "“深刻”形容印象或认识透彻，与“次等”没有反义关系。", "上等": "“上等”指等级最高、质量最好，与“次等”意义相反，词典中构成反义关系。", "活泼": "“活泼”形容性格或气氛生动，与“次等”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级较低，质量或地位比较差的。", "primary_collocate": null, "pronunciation": "cì děng", "ipa": "tsʰɨ˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是次等水果，所以价格便宜。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想一辈子做次等公民。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的次等茶叶，味道不太好。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得自己是次等的，什么都不如别人。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只卖次等货，我不买。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次等布做的衣服，穿几次就坏了。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的米卖得快，次等米卖得慢。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对女儿和儿子一样好，没有把谁当次等人。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果是次等的，我们打折卖。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把次等的东西放在后面，好的放在前面。", "target_word": "次等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次等品", "label": "复合词"}], "register": "中性", "sense_fingerprint": "等级低，质量或地位比较差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9080b40-a81e-4230-8f7c-f24180c45908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名贵", "is_correct": false, "explanation": "语义：“名贵”指珍贵、价格高，与后半句“价格便宜”矛盾。"}, {"text": "次等", "is_correct": true, "explanation": "“次等”指等级较低，与后半句“价格便宜”相符，是正确答案。"}, {"text": "高级", "is_correct": false, "explanation": "语义：“高级”指等级高、质量好，与后半句“价格便宜”不相符。"}, {"text": "精品", "is_correct": false, "explanation": "语义：“精品”指精选的优质品，与后半句“价格便宜”不相符。"}], "explanations": {"名贵": "语义：“名贵”指珍贵、价格高，与后半句“价格便宜”矛盾。", "次等": "“次等”指等级较低，与后半句“价格便宜”相符，是正确答案。", "高级": "语义：“高级”指等级高、质量好，与后半句“价格便宜”不相符。", "精品": "语义：“精品”指精选的优质品，与后半句“价格便宜”不相符。"}, "sentence_index": 0, "correct_answer": "次等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很次等，我们先讨论别的。", "explanation": "这里应该用〈次要〉。次等指质量或等级较差，不用来说问题的主次。"}, {"text": "他的力气比我次等，我得多帮他搬东西。", "explanation": "这里应该用〈弱〉。“次等”指等级、质量，不用来比较力气；说力气小要用〈弱〉。"}, {"text": "他在比赛中得了次等，只差一点就是冠军。", "explanation": "这里应该用〈亚军〉。“次等”只用于质量、等级，不用来表示比赛名次，第二名要说“亚军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好", "is_correct": false, "explanation": "语义：“好米”与前句“好的米”重复，且与后半句“卖得慢”的对比不成立。"}, {"text": "次要", "is_correct": false, "explanation": "语义：“次要”说的是主次，不指米的质量等级，与前后对比不符。"}, {"text": "次等", "is_correct": true, "explanation": "“次等”指等级较低，与前句“好的米卖得快”形成对比，是正确答案。"}, {"text": "熟", "is_correct": false, "explanation": "搭配：“熟”形容煮熟或成熟，不用来说米的等级，“熟米”不能与对比结构搭配。"}], "explanations": {"好": "语义：“好米”与前句“好的米”重复，且与后半句“卖得慢”的对比不成立。", "次要": "语义：“次要”说的是主次，不指米的质量等级，与前后对比不符。", "次等": "“次等”指等级较低，与前句“好的米卖得快”形成对比，是正确答案。", "熟": "搭配：“熟”形容煮熟或成熟，不用来说米的等级，“熟米”不能与对比结构搭配。"}, "sentence_index": 6, "correct_answer": "次等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高是次等的，比同学都低。", "explanation": "“次等”指等级或质量，不能用来描述身高；说身高不高要用〈矮〉。"}, {"text": "她的年龄是次等的，比我小两岁。", "explanation": "“次等”指等级、质量，不能用来说年龄；说年龄小要用〈年轻〉。"}, {"text": "今天的温度是次等的，有三十度。", "explanation": "“次等”指等级、质量，不能用来说温度；说温度高要用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批布是次等地，价格比较低。", "corrected_sentence": "这批布是次等的，价格比较低。", "error_description": "结构助词用错。错误形式是“是次等地”，正确形式是“是次等的”。“次等”是形容词，作谓语时用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件次等地衣服，穿几次就坏了。", "corrected_sentence": "这件次等的衣服，穿几次就坏了。", "error_description": "结构助词用错。错误形式是“次等地衣服”，正确形式是“次等的衣服”。“次等”修饰名词“衣服”时要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670af652-8fde-4e32-b310-1906273bf65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
