INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雌性的，能生育后代的；多用于动物，与“公”相对。", "primary_collocate": null, "pronunciation": "mǔ", "ipa": "mu˨˩˦", "syllable_count": 1, "sentences": [{"text": "这只猫是母的，不是公的。", "target_word": "母", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你家的狗是公的还是母的？", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母的会生小猫，公的不会。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那匹马是母的，刚生了一匹小马。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些鸡里，只有母的才会下蛋。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想养一只母的小狗。", "target_word": "母", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他问老板这条鱼是公的还是母的。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头牛是母的，所以能产奶。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两只鸟，一只是公的，一只是母的。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只猫是母的，比公的安静。", "target_word": "母", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "母亲", "label": "复合"}, {"form": "母鸡", "label": "复合"}], "register": "口语", "sense_fingerprint": "母：（动物）雌性的，与公相对，常说“母的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94658, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "母", "is_correct": true, "explanation": "母（mǔ，第三声）：雌性的，与“公”相对。"}, {"text": "木", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是树木。"}, {"text": "目", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是眼睛。"}, {"text": "墓", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。"}, {"text": "努", "is_correct": false, "explanation": "nǔ 与 mǔ 声母不同（n／m），意思是努力。"}], "explanations": {"母": "母（mǔ，第三声）：雌性的，与“公”相对。", "木": "mù（第四声）与 mǔ（第三声）声调不同，意思是树木。", "目": "mù（第四声）与 mǔ（第三声）声调不同，意思是眼睛。", "墓": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。", "努": "nǔ 与 mǔ 声母不同（n／m），意思是努力。"}, "sentence_index": null, "correct_answer": "母"}, "level_3": {"options": [{"text": "母", "is_correct": true, "explanation": "母：指雌性的，与后半句“不是公的”相对，只有它能放入空格。"}, {"text": "公", "is_correct": false, "explanation": "语义：“公”与后半句“不是公的”重复且矛盾，句子说不通。"}, {"text": "女", "is_correct": false, "explanation": "搭配：“女”只用于人，不说“女的猫”。"}, {"text": "男", "is_correct": false, "explanation": "搭配：“男”只用于人，不说“男的猫”。"}], "explanations": {"母": "母：指雌性的，与后半句“不是公的”相对，只有它能放入空格。", "公": "语义：“公”与后半句“不是公的”重复且矛盾，句子说不通。", "女": "搭配：“女”只用于人，不说“女的猫”。", "男": "搭配：“男”只用于人，不说“男的猫”。"}, "sentence_index": 0, "correct_answer": "母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是一个母的，每天很早去上班。", "explanation": "这里应该用〈女〉。“母的”只用于动物的雌性，指人时用“女的”。"}, {"text": "这块石头是母的，形状很圆。", "explanation": "“母的”的雌性义只指有生命的动物，这里误用到了石头上。石头没有性别，应去掉“母的”，只描述形状。"}, {"text": "我爸爸是家里的母，每天做饭。", "explanation": "这里应该用〈父亲〉。“母”指女性家长，不能用于男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94658, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "母", "is_correct": true, "explanation": "母（mǔ，第三声）：雌性的，与“公”相对。"}, {"text": "牧", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是放牧。"}, {"text": "幕", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是幕布。"}, {"text": "府", "is_correct": false, "explanation": "fǔ 与 mǔ 声母不同（f／m），意思是官府、住所。"}, {"text": "补", "is_correct": false, "explanation": "bǔ 与 mǔ 声母不同（b／m），意思是补充。"}], "explanations": {"母": "母（mǔ，第三声）：雌性的，与“公”相对。", "牧": "mù（第四声）与 mǔ（第三声）声调不同，意思是放牧。", "幕": "mù（第四声）与 mǔ（第三声）声调不同，意思是幕布。", "府": "fǔ 与 mǔ 声母不同（f／m），意思是官府、住所。", "补": "bǔ 与 mǔ 声母不同（b／m），意思是补充。"}, "sentence_index": null, "correct_answer": "母"}, "level_3": {"options": [{"text": "母", "is_correct": true, "explanation": "母：指雌性的，与前面的“公的”构成对立，只有它合适。"}, {"text": "女", "is_correct": false, "explanation": "搭配：“女”只用于人，不说“女的鱼”。"}, {"text": "人", "is_correct": false, "explanation": "搭配：“人的”只用于人，不能用来描述“这条鱼”。"}, {"text": "猫", "is_correct": false, "explanation": "语义：鱼不是猫，“猫的”与前面的“公的”没有可比性。"}], "explanations": {"母": "母：指雌性的，与前面的“公的”构成对立，只有它合适。", "女": "搭配：“女”只用于人，不说“女的鱼”。", "人": "搭配：“人的”只用于人，不能用来描述“这条鱼”。", "猫": "语义：鱼不是猫，“猫的”与前面的“公的”没有可比性。"}, "sentence_index": 6, "correct_answer": "母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的母很大，有很多教室。", "explanation": "这里应该用〈母校〉。“母”单用不能指学校，只能组成“母校”。"}, {"text": "这台洗衣机是母的，声音很小。", "explanation": "“母的”的雌性义只指有生命的动物，洗衣机没有性别，这里误用了这个义项，应去掉“母的”。"}, {"text": "我的爷爷是母的，每天遛鸟。", "explanation": "这里应该用〈男的〉。“母的”指雌性，不用于男性；爷爷是男性，应说“男的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只狗是的母，不是公的。", "corrected_sentence": "这只狗是母的，不是公的。", "error_description": "错误：“的母”，正确：“母的”。“的”必须放在“母”之后，构成“母的”，表示雌性的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猫是的母，比公的活泼。", "corrected_sentence": "那只猫是母的，比公的活泼。", "error_description": "错误：“的母”，正确：“母的”。“的”必须放在“母”之后，构成“母的”，表示雌性的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
