INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大的河流，水面宽阔，常常通向大海。", "primary_collocate": null, "pronunciation": "jiāng", "ipa": "tɕjɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这条江很宽，一直流到大海。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江上有一座很长的桥。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江里有很多船，都往大海开去。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船过江，到对面去。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江的两边都是高高的山。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天下了大雨，江变得更宽了。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条江的水面很宽，小船看起来很小。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江从山里流出来，最后流进大海。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在江上看了一整天的船。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天江很安静，船也少了。", "target_word": "江", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条江", "label": "量词"}, {"form": "江水", "label": "复合"}, {"form": "江边", "label": "复合"}], "register": "中性", "sense_fingerprint": "水面宽阔、通向大海的大河流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "江", "is_correct": true, "explanation": "江（jiāng，第一声）：大的河流，水面宽阔，常常通向大海。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng 与 jiāng 声母不同（q／j），意思是枪。"}, {"text": "降", "is_correct": false, "explanation": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。"}, {"text": "尖", "is_correct": false, "explanation": "jiān 与 jiāng 韵母不同（an／ang），意思是尖。"}], "explanations": {"江": "江（jiāng，第一声）：大的河流，水面宽阔，常常通向大海。", "讲": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。", "枪": "qiāng 与 jiāng 声母不同（q／j），意思是枪。", "降": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。", "尖": "jiān 与 jiāng 韵母不同（an／ang），意思是尖。"}, "sentence_index": null, "correct_answer": "江"}, "level_3": {"options": [{"text": "江", "is_correct": true, "explanation": "江：大河，能一直流到大海，与“很宽”“流到大海”搭配。"}, {"text": "路", "is_correct": false, "explanation": "语义：路不会流动，“一直流到大海”说不通。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥不能流到大海，句子意思不通。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“海”一般不用“条”计量，“这条海”不这么说。"}], "explanations": {"江": "江：大河，能一直流到大海，与“很宽”“流到大海”搭配。", "路": "语义：路不会流动，“一直流到大海”说不通。", "桥": "语义：桥不能流到大海，句子意思不通。", "海": "搭配：“海”一般不用“条”计量，“这条海”不这么说。"}, "sentence_index": 0, "correct_answer": "江"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家院子里有一条江，里面养着几条鱼。", "explanation": "这里应该用〈池塘〉。“江”指大河，院子里的小水塘不能叫江。"}, {"text": "前面有一座江，水很清。", "explanation": "这里应该用〈条〉。江用“条”计量，“座”用于山或桥。"}, {"text": "我们在江里种了一片菜。", "explanation": "这里应该用〈地〉。菜要种在地里，江里不能种菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94660, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "江", "is_correct": true, "explanation": "江（jiāng，第一声）：大的河流，水面宽阔，常常通向大海。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖励。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 jiāng 声母不同（x／j），意思是香气。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。"}, {"text": "间", "is_correct": false, "explanation": "jiān 与 jiāng 韵母不同（an／ang），意思是房间。"}], "explanations": {"江": "江（jiāng，第一声）：大的河流，水面宽阔，常常通向大海。", "奖": "jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖励。", "香": "xiāng 与 jiāng 声母不同（x／j），意思是香气。", "酱": "jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。", "间": "jiān 与 jiāng 韵母不同（an／ang），意思是房间。"}, "sentence_index": null, "correct_answer": "江"}, "level_3": {"options": [{"text": "江", "is_correct": true, "explanation": "江：大河，有水面，小船可以在上面行驶，与前文搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有水面，“桌子的水面”说不通。"}, {"text": "山", "is_correct": false, "explanation": "语义：山没有水面，“山的水面很宽”说不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”用“本”计量，不说“这条书”。"}], "explanations": {"江": "江：大河，有水面，小船可以在上面行驶，与前文搭配。", "桌子": "语义：桌子没有水面，“桌子的水面”说不通。", "山": "语义：山没有水面，“山的水面很宽”说不通。", "书": "搭配：“书”用“本”计量，不说“这条书”。"}, "sentence_index": 6, "correct_answer": "江"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前面有一幅江，景色很美。", "explanation": "这里应该用〈条〉。“幅”用于画，江不能用“幅”计量。"}, {"text": "江里长满了稻子，很好看。", "explanation": "这里应该用〈田〉。稻子长在田里，江里不能长稻子。"}, {"text": "江上结满了果子，很好吃。", "explanation": "这里应该用〈树〉。果子长在树上，江上不会结果子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座江很宽，一直流到海边。", "corrected_sentence": "这条江很宽，一直流到海边。", "error_description": "错误：“这座江”，正确：“这条江”。江用“条”计量，“座”用于山、桥等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根江的水很清，鱼也很多。", "corrected_sentence": "这条江的水很清，鱼也很多。", "error_description": "错误：“这根江”，正确：“这条江”。江用“条”计量，“根”用于细长的东西，不用于江。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
