INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94661, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没用是人做不成事、帮不上忙，能力不足。", "primary_collocate": null, "pronunciation": "méi yòng", "ipa": "mei̯˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他觉得自己帮不上忙，真没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太没用了，连这点小事也做不好。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病时，我只能看着，真没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己没用，什么忙都帮不上。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说自己没用，你已经帮了大忙。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一遇到事就慌，真没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这个人没用，所以帮不了你搬家。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，没用的人不能留在公司。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕自己没用，不敢接这个工作。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友难过时，我觉得自己很没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有用", "label": "全称"}, {"form": "沒用", "label": "繁体"}], "register": "口语", "sense_fingerprint": "人做不成事、帮不上忙，觉得自己无能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没用", "is_correct": true, "explanation": "没用：做不成事，帮不上忙，与“真”的语境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外表，与“帮不上忙”无关，不能用来评价能力。"}, {"text": "有用", "is_correct": false, "explanation": "语义：“有用”表示能帮上忙，与“帮不上忙”矛盾。"}, {"text": "厉害", "is_correct": false, "explanation": "语义：“厉害”表示能力强，与“帮不上忙”的意思相反。"}], "explanations": {"没用": "没用：做不成事，帮不上忙，与“真”的语境相符。", "漂亮": "体貌：“漂亮”说外表，与“帮不上忙”无关，不能用来评价能力。", "有用": "语义：“有用”表示能帮上忙，与“帮不上忙”矛盾。", "厉害": "语义：“厉害”表示能力强，与“帮不上忙”的意思相反。"}, "sentence_index": 0, "correct_answer": "没用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很没用，总能把孩子哄好。", "explanation": "这里应该用〈能干〉（有能力）。“没用”表示做不成事，与“总能把孩子哄好”相反。"}, {"text": "我这个人没用，却帮了全家人的大忙。", "explanation": "这里“没用”（做不成事）与“帮了全家人的大忙”矛盾；应说〈能干〉。"}, {"text": "我太没用，连这点小事也做得很好。", "explanation": "这里“没用”（做不成事）与“连这点小事也做得很好”矛盾；应说〈能干〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没用", "is_correct": true, "explanation": "没用：做不成事、帮不上忙，与“不能帮你搬家”相符。"}, {"text": "有本事", "is_correct": false, "explanation": "语义：“有本事”表示能力强，与“不能帮你搬家”矛盾。"}, {"text": "有能耐", "is_correct": false, "explanation": "语义：“有能耐”表示有办法，与“不能帮你搬家”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说身材，与“能不能帮忙”的能力无关。"}], "explanations": {"没用": "没用：做不成事、帮不上忙，与“不能帮你搬家”相符。", "有本事": "语义：“有本事”表示能力强，与“不能帮你搬家”矛盾。", "有能耐": "语义：“有能耐”表示有办法，与“不能帮你搬家”矛盾。", "高大": "体貌：“高大”说身材，与“能不能帮忙”的能力无关。"}, "sentence_index": 6, "correct_answer": "没用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法很没用，所以我们每天都用它。", "explanation": "这里“没用”与“所以我们每天都用它”矛盾；此句的“没用”指东西无用，属于另一义项，不是本词所教的人无能义。"}, {"text": "我在比赛中很没用，得了第一名。", "explanation": "这里“没用”（做不成事）与“得了第一名”矛盾；应说〈能干〉。"}, {"text": "老板说，我很没用，因此给我加了工资。", "explanation": "这里“没用”（做不成事）与“因此给我加了工资”矛盾；应说〈能干〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得自己真没用真，什么都做不好。", "corrected_sentence": "我觉得自己真没用，什么都做不好。", "error_description": "错误：“没用”后面多了一个“真”，句子不通。正确：“真”只放在“没用”前面，应说“真没用”，“没用”后面不加“真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他觉得自己了没用，就不再参加比赛了。", "corrected_sentence": "他觉得自己没用，就不再参加比赛了。", "error_description": "错误：“了”放在“自己”和“没用”之间，位置不对。正确：“没用”后直接接“就”，不需要在中间加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
