INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94662, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没用是没有用处，起不到作用。", "primary_collocate": null, "pronunciation": "méi yòng", "ipa": "mei̯˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这把旧伞坏了，留着也没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药吃了三天，还是没用，病没有好。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法太旧了，现在已经没用了。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有网络，手机再贵也没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一直哭也没用，要想办法。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧报纸放着没用，我们扔了吧。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票过期了，现在已经没用了。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧闹钟坏了，修也没用，还是买个新的吧。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是不努力，再好的书也没用。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了考试时间，现在复习没用了。", "target_word": "没用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有用", "label": "全称"}, {"form": "沒用", "label": "繁体"}], "register": "口语", "sense_fingerprint": "东西或办法没有用处、起不到作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7a188d6-0514-475b-a7b1-f7d5ab52b20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没用", "is_correct": true, "explanation": "没用：没有用处，与“留着也”的语境相符。"}, {"text": "好用", "is_correct": false, "explanation": "语义：“好用”表示有用处、有效果，与“坏了”的事实矛盾。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”表示坚固，与“伞坏了”的事实矛盾。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不能用来说留着一把旧伞便宜。"}], "explanations": {"没用": "没用：没有用处，与“留着也”的语境相符。", "好用": "语义：“好用”表示有用处、有效果，与“坏了”的事实矛盾。", "结实": "语义：“结实”表示坚固，与“伞坏了”的事实矛盾。", "便宜": "搭配：“便宜”说价格，不能用来说留着一把旧伞便宜。"}, "sentence_index": 0, "correct_answer": "没用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把雨伞很没用，每次下雨我们都靠它。", "explanation": "这里“没用”（没有用处）与“每次下雨我们都靠它”矛盾，应说〈好用〉。"}, {"text": "这个电池很没用，装上后手机能用一整天。", "explanation": "这里“没用”（没有用处）与“装上后手机能用一整天”矛盾，应说〈好用〉。"}, {"text": "这台电脑很没用，修好后运行得很快。", "explanation": "这里误把〈没用〉（没有用处）用于能正常运行的电脑，应说〈好用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没用", "is_correct": true, "explanation": "没用：已经没有用处了，与“现在已经”相符。"}, {"text": "有效", "is_correct": false, "explanation": "语义：票过期后不能说“有效”，与前面的“过期了”矛盾。"}, {"text": "有名", "is_correct": false, "explanation": "搭配：“有名”用于人或地方，不能用来形容票。"}, {"text": "新", "is_correct": false, "explanation": "体貌：“新”说的是外观或状态，过期的票不能说“新”。"}], "explanations": {"没用": "没用：已经没有用处了，与“现在已经”相符。", "有效": "语义：票过期后不能说“有效”，与前面的“过期了”矛盾。", "有名": "搭配：“有名”用于人或地方，不能用来形容票。", "新": "体貌：“新”说的是外观或状态，过期的票不能说“新”。"}, "sentence_index": 6, "correct_answer": "没用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病还没用，还得再休息几天。", "explanation": "这里应该用〈没好〉（未痊愈）。“没用”指没有用处，不能用来说病还没好。"}, {"text": "她的脸很没用，不好意思抬头。", "explanation": "这里应该用〈红〉（脸红）。“没用”指没有用处，不能用来描述脸的状态。"}, {"text": "这个方法很没用，但是效果非常好。", "explanation": "这里误把〈没用〉（没有用处）用于效果很好的方法，应说〈好用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧电脑已经没用了了，我们卖掉吧。", "corrected_sentence": "这台旧电脑已经没用了，我们卖掉吧。", "error_description": "错误：“了”重复出现在“没用了”后面。正确：“没用了”只用一个“了”，表示已经变得没有用处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子已经没用的了，可以扔掉。", "corrected_sentence": "这把椅子已经没用了，可以扔掉。", "error_description": "错误：“没用”后面多了“的”，“的”不能放在“没用”和“了”之间。正确：“没用了”，“了”直接放在形容词后，表示已经变得没有用处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70d4e3f8-b5cb-4988-8624-5b701ef797a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
