INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙是很小很小的石头颗粒，一粒一粒的。", "primary_collocate": null, "pronunciation": "shā", "ipa": "ʂa˥", "syllable_count": 1, "sentences": [{"text": "鞋里进了一粒沙，我走路很疼。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙是很细的石头粒，用手一抓就漏了。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在地上用小手抓沙玩。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，沙进了我的眼睛。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一袋沙倒进了小桶里。", "target_word": "沙", "complexity_tier": "T3", "furigana": "tā bǎ yí dài shā dào jìn le xiǎo tǒng lǐ", "sentence_source": "generated"}, {"text": "沙很细，从手指中间慢慢漏下去。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米里有沙，吃起来很不舒服。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们拿着小铲子挖沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上有很多沙，车开得很慢。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用车把沙运到了新房子旁边。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一粒沙", "label": "量词"}, {"form": "一堆沙", "label": "量词"}, {"form": "沙子", "label": "复合"}, {"form": "沙滩", "label": "复合"}], "register": "中性", "sense_fingerprint": "很小的石头颗粒，一粒一粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：很小的石头颗粒，一粒一粒。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。"}, {"text": "撒", "is_correct": false, "explanation": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。"}, {"text": "扎", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}], "explanations": {"沙": "沙（shā，第一声）：很小的石头颗粒，一粒一粒。", "傻": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。", "撒": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。", "扎": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：很小的石头颗粒，用“粒”计量，与前文搭配。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“粒”不计量书，书应说“一本”。"}, {"text": "车", "is_correct": false, "explanation": "语义：车进不了鞋里，句子不合常理。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不能进到鞋里，“鞋里进了一粒鞋”说不通。"}], "explanations": {"沙": "沙：很小的石头颗粒，用“粒”计量，与前文搭配。", "书": "搭配：“粒”不计量书，书应说“一本”。", "车": "语义：车进不了鞋里，句子不合常理。", "鞋": "语义：鞋不能进到鞋里，“鞋里进了一粒鞋”说不通。"}, "sentence_index": 0, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上捡到一块沙，很漂亮。", "explanation": "这里应该用〈粒〉。沙按“粒”计量，不说“一块沙”。"}, {"text": "我在汤里加了一勺沙，正好调味。", "explanation": "这里应该用〈盐〉。沙不是调料，不能用来调味。"}, {"text": "他把沙煮成了粥。", "explanation": "这里应该用〈米〉。沙不能吃，也不能煮粥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94663, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：很小的石头颗粒，一粒一粒。"}, {"text": "啥", "is_correct": false, "explanation": "shá（第二声）与 shā（第一声）声调不同，意思是什么。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 shā 声母不同（ch／sh），意思是插入。"}, {"text": "渣", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}], "explanations": {"沙": "沙（shā，第一声）：很小的石头颗粒，一粒一粒。", "啥": "shá（第二声）与 shā（第一声）声调不同，意思是什么。", "插": "chā 与 shā 声母不同（ch／sh），意思是插入。", "渣": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：很小的石头颗粒，会混在米里，与前文搭配。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会在米里，句子说不通。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不会混在米里，“吃起来很不舒服”也无从谈起。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会在米里，“吃起来很不舒服”也无从谈起。"}], "explanations": {"沙": "沙：很小的石头颗粒，会混在米里，与前文搭配。", "猫": "语义：猫不会在米里，句子说不通。", "纸": "语义：纸不会混在米里，“吃起来很不舒服”也无从谈起。", "桌子": "语义：桌子不会在米里，“吃起来很不舒服”也无从谈起。"}, "sentence_index": 6, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喊了一下午，声音都沙了。", "explanation": "这里的“沙”指声音沙哑，是另一个意思，不是颗粒状的沙子。"}, {"text": "我们在地里种了很多沙。", "explanation": "这里应该用〈菜〉。沙不能种，地里种的是菜。"}, {"text": "我每天喝一杯沙。", "explanation": "这里应该用〈水〉。沙不能喝，喝的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一阵风吹来，一块沙进了我的眼睛。", "corrected_sentence": "一阵风吹来，沙进了我的眼睛。", "error_description": "错误：“一块沙”，正确：“沙”或“一粒沙”。沙是细小颗粒，不用“块”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把几块沙搬进了仓库。", "corrected_sentence": "他把几袋沙搬进了仓库。", "error_description": "错误：“几块沙”，正确：“几袋沙”。沙用“袋”装运，“块”不用于沙。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
