INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岩石风化破碎形成的细小颗粒，常见于河滩、海边和沙漠。", "primary_collocate": null, "pronunciation": "shā", "ipa": "ʂa˥", "syllable_count": 1, "sentences": [{"text": "海边的沙又细又软，很舒服。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水退了以后，河滩上留下了很多沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片地方没有草，只有黄色的沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的石头被风雨慢慢变成了沙。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边的沙上走了很久。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风把远处的沙吹到了城里。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的沙是黄色的，那边的沙是白色的。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水带来了很多沙，堆在岸边。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河底的沙很干净，水也很清。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边的沙上写下了名字。", "target_word": "沙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层沙", "label": "量词"}, {"form": "一堆沙", "label": "量词"}, {"form": "沙子", "label": "复合"}, {"form": "沙漠", "label": "复合"}], "register": "中性", "sense_fingerprint": "岩石风化形成的细小颗粒，河滩海边沙漠常见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。"}, {"text": "傻", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。"}, {"text": "撒", "is_correct": false, "explanation": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。"}, {"text": "扎", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}], "explanations": {"沙": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。", "傻": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻。", "撒": "sā 与 shā 声母不同（s／sh），意思是撒开、撒种。", "扎": "zhā 与 shā 声母不同（zh／sh），意思是扎进。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：细小颗粒，质地细软，与“海边”搭配，只有它合适。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会“又细又软”，细软说的是颗粒或质地。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：“海水”不说“又细又软”，这种形容只用于颗粒或质地。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能“又细又软”，“海边的树很舒服”说不通。"}], "explanations": {"沙": "沙：细小颗粒，质地细软，与“海边”搭配，只有它合适。", "石头": "语义：石头不会“又细又软”，细软说的是颗粒或质地。", "海水": "搭配：“海水”不说“又细又软”，这种形容只用于颗粒或质地。", "树": "语义：树不能“又细又软”，“海边的树很舒服”说不通。"}, "sentence_index": 0, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的沙很清，可以直接喝。", "explanation": "这里应该用〈水〉。沙是石头颗粒，不能喝，“清”说的是水。"}, {"text": "那片沙很肥，适合种庄稼。", "explanation": "这里应该用〈土地〉。沙缺少养分，不能说“很肥”。"}, {"text": "他每天早上喝一杯沙，很提神。", "explanation": "这里应该用〈茶〉。沙不能喝，“喝一杯”应该用饮品，如茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。"}, {"text": "啥", "is_correct": false, "explanation": "shá（第二声）与 shā（第一声）声调不同，意思是什么。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 shā 声母不同（ch／sh），意思是插入。"}, {"text": "渣", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}], "explanations": {"沙": "沙（shā，第一声）：岩石风化形成的细小颗粒，常见于河滩、海边和沙漠。", "啥": "shá（第二声）与 shā（第一声）声调不同，意思是什么。", "插": "chā 与 shā 声母不同（ch／sh），意思是插入。", "渣": "zhā 与 shā 声母不同（zh／sh），意思是渣滓。"}, "sentence_index": null, "correct_answer": "沙"}, "level_3": {"options": [{"text": "沙", "is_correct": true, "explanation": "沙：细小颗粒，有颜色之分，与“黄色的”“白色的”搭配。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有颜色，不能说“黄色的声音”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能是黄色的，“这里的味道是黄色的”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "体貌：名字没有颜色或外貌，不能用“黄色的”来描述。"}], "explanations": {"沙": "沙：细小颗粒，有颜色之分，与“黄色的”“白色的”搭配。", "声音": "语义：声音没有颜色，不能说“黄色的声音”。", "味道": "语义：味道不能是黄色的，“这里的味道是黄色的”说不通。", "名字": "体貌：名字没有颜色或外貌，不能用“黄色的”来描述。"}, "sentence_index": 6, "correct_answer": "沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那里有一个很大的沙，人们都在看。", "explanation": "这里应该用〈堆〉。沙按“堆”计量，不说“一个沙”。"}, {"text": "春天到了，沙开了一片。", "explanation": "这里应该用〈花〉。“开”搭配花，沙不会开。"}, {"text": "我每天吃一碗沙，很饱。", "explanation": "这里应该用〈饭〉。沙不能吃，“吃一碗”应该是饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河边的沙们又细又软，很舒服。", "corrected_sentence": "河边的沙又细又软，很舒服。", "error_description": "错误：“沙们”，正确：“沙”。沙是不可数名词，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "岸边的沙们很干净，孩子们在玩。", "corrected_sentence": "岸边的沙很干净，孩子们在玩。", "error_description": "错误：“沙们”，正确：“沙”。沙是不可数名词，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加", "is_correct": true, "explanation": "加与减是算术中的一对反义词。"}, {"text": "看", "is_correct": false, "explanation": "看与减没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑与减没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写与减没有反义关系。"}], "correct_answer": "加", "explanations": {"加": "加与减是算术中的一对反义词。", "看": "看与减没有反义关系。", "跑": "跑与减没有反义关系。", "写": "写与减没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加", "is_correct": true, "explanation": "加与减是算术中的一对反义词。"}, {"text": "唱", "is_correct": false, "explanation": "唱与减没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃与减没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走与减没有反义关系。"}], "correct_answer": "加", "explanations": {"加": "加与减是算术中的一对反义词。", "唱": "唱与减没有反义关系。", "吃": "吃与减没有反义关系。", "走": "走与减没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "减是把数字变少，或者拿走一些。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "十减三等于七。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八减五是多少？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我，二十减六等于几？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五十减八，答案是四十二。", "target_word": "减", "complexity_tier": "T3", "furigana": "jiǎn", "sentence_source": "generated"}, {"text": "一百减三十，还剩七十。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九减四，你算对了吗？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先加三，再减二，最后是几？", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只会加，不会减。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用十五减七，得到八。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二减五比十二加五小得多。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "減", "label": "繁体"}, {"form": "减了", "label": "体标"}, {"form": "减过", "label": "体标"}, {"form": "减去", "label": "复合"}, {"form": "减少", "label": "复合"}], "register": "中性", "sense_fingerprint": "算术中的减法，从一个数里拿走另一个数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从数里拿走一部分，是算术中的减法。"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是尖锐。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}], "explanations": {"减": "减（jiǎn）指从数里拿走一部分，是算术中的减法。", "件": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。", "见": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。", "尖": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是尖锐。", "奖": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示算术中的减法，“十减三等于七”成立。"}, {"text": "剩", "is_correct": false, "explanation": "配价：“剩”只带一个宾语，不能连接两个数字，“十剩三”不成立。"}, {"text": "加", "is_correct": false, "explanation": "语义：“十加三”得十三，与“等于七”不符。"}, {"text": "乘", "is_correct": false, "explanation": "语义：“十乘三”得三十，与“等于七”不符。"}], "explanations": {"减": "减表示算术中的减法，“十减三等于七”成立。", "剩": "配价：“剩”只带一个宾语，不能连接两个数字，“十剩三”不成立。", "加": "语义：“十加三”得十三，与“等于七”不符。", "乘": "语义：“十乘三”得三十，与“等于七”不符。"}, "sentence_index": 0, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把十块钱减给了妹妹，妹妹很高兴。", "explanation": "这里应该用〈给〉。减是算术动作，不能表示把钱交给别人。"}, {"text": "他往杯子里减了两勺糖。", "explanation": "这里应该用〈放〉。减表示拿走或变少，往杯子里加东西要用〈放〉，不能用「减」。"}, {"text": "她一边做饭，一边减着歌。", "explanation": "这里应该用〈唱〉。减是算术动作，不能用来表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从数里拿走一部分，是算术中的减法。"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}], "explanations": {"减": "减（jiǎn）指从数里拿走一部分，是算术中的减法。", "建": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。", "间": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。", "讲": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示算术中的减法，“先加三，再减二”是正确的运算步骤。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”不是运算，“再买二”与算术题不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，不是运算，与算式不符。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”后接数字缺少量词，“再拿二”不成立。"}], "explanations": {"减": "减表示算术中的减法，“先加三，再减二”是正确的运算步骤。", "买": "语义：“买”不是运算，“再买二”与算术题不符。", "扔": "语义：“扔”表示丢弃，不是运算，与算式不符。", "拿": "配价：“拿”后接数字缺少量词，“再拿二”不成立。"}, "sentence_index": 6, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子每天减一首钢琴曲，很辛苦。", "explanation": "这里应该用〈弹〉。减是算术动作，不能用来表示弹奏乐曲。"}, {"text": "妈妈减下了一个女儿。", "explanation": "这里应该用〈生〉。减表示去掉一部分或降低，不能用来说生孩子，那要用〈生〉。"}, {"text": "他在湖边减了一阵笑声。", "explanation": "这里应该用〈听到〉。减表示去掉一部分或降低，不能用来说听见声音，那要用〈听到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二十减了六等于十四。", "corrected_sentence": "二十减六等于十四。", "error_description": "体标误用：算式里的「减」后直接接数字，不加「了」。「减了六」表示已完成的减少，不用于算式。错误形式是「减了」，正确形式是「减」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先加五，减再三，结果是多少？", "corrected_sentence": "我先加五，再减三，结果是多少？", "error_description": "语序错误：“再”应放在“减”之前，“减再三”不成立，应为“再减三”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增加", "is_correct": true, "explanation": "增加与减少是一对反义词，表示数量或价格的相反变化。"}, {"text": "唱", "is_correct": false, "explanation": "唱与减没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "跳与减没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗与减没有反义关系。"}], "correct_answer": "增加", "explanations": {"增加": "增加与减少是一对反义词，表示数量或价格的相反变化。", "唱": "唱与减没有反义关系。", "跳": "跳与减没有反义关系。", "洗": "洗与减没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
