INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从总数里去掉一部分；也指降低、减少。", "primary_collocate": null, "pronunciation": "jiǎn", "ipa": "tɕjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这件衣服太贵了，老板给我减了五十块。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总数里减十个，还剩九十个。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租太高，房东答应每月减三百。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作少了，这个月的工资也减了。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把每个人的奖金减了一半。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从名单里减三个人，只剩十个人。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买两件就减二十块，很便宜。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月花钱太多，下个月要减一点。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把糖减了一半，咖啡就不那么甜了。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜太咸，盐要减一点。", "target_word": "减", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "減", "label": "繁体"}, {"form": "减了", "label": "体标"}, {"form": "减过", "label": "体标"}, {"form": "减去", "label": "复合"}, {"form": "减少", "label": "复合"}], "register": "中性", "sense_fingerprint": "从总数里去掉一部分，降低或减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45b38437-d77e-4b5a-b704-9da1a1d884ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从总数里去掉一部分，或降低、减少。"}, {"text": "建", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}], "explanations": {"减": "减（jiǎn）指从总数里去掉一部分，或降低、减少。", "建": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是建立。", "间": "jiān（第一声）与 jiǎn（第三声）声调不同，意思是房间。", "讲": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是讲话。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示降低、减少，“老板给我减了五十块”指降价五十元，符合句意。"}, {"text": "加", "is_correct": false, "explanation": "语义：太贵的时候老板不会给我加价，与“太贵了”的语境冲突。"}, {"text": "赚", "is_correct": false, "explanation": "配价：“赚”的收益者是老板，不能说“给我赚”。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”的宾语应是商品，不能用金额作宾语。"}], "explanations": {"减": "减表示降低、减少，“老板给我减了五十块”指降价五十元，符合句意。", "加": "语义：太贵的时候老板不会给我加价，与“太贵了”的语境冲突。", "赚": "配价：“赚”的收益者是老板，不能说“给我赚”。", "卖": "配价：“卖”的宾语应是商品，不能用金额作宾语。"}, "sentence_index": 0, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们店今年进了五百件新货，把库存减进了仓库。", "explanation": "这里应该用〈搬〉。减表示去掉一部分或降低，把货物搬进仓库要用〈搬〉，不能用「减」。"}, {"text": "老师让我把这篇文章减成英文。", "explanation": "这里应该用〈翻译〉。减表示去掉一部分或降低，把文章改换成另一种语言要用〈翻译〉，不能用「减」。"}, {"text": "黑板上的字，他用湿布减干净了。", "explanation": "这里应该用〈擦〉。减表示数量或价格的减少，不用于擦掉字迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "减", "is_correct": true, "explanation": "减（jiǎn）指从总数里去掉一部分，或降低、减少。"}, {"text": "件", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。"}, {"text": "见", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}], "explanations": {"减": "减（jiǎn）指从总数里去掉一部分，或降低、减少。", "件": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是件。", "见": "jiàn（第四声）与 jiǎn（第三声）声调不同，意思是看见。", "奖": "jiǎng 与 jiǎn 韵母不同（ang 与 an），意思是奖励。"}, "sentence_index": null, "correct_answer": "减"}, "level_3": {"options": [{"text": "减", "is_correct": true, "explanation": "减表示降低价格，“买两件就减二十块”指优惠二十块，符合句意。"}, {"text": "赔", "is_correct": false, "explanation": "语义：赔是亏损或赔偿，与“很便宜”的语境冲突。"}, {"text": "涨", "is_correct": false, "explanation": "语义：涨是提高价格，与“很便宜”矛盾。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语应是文字，不能说“写二十块”。"}], "explanations": {"减": "减表示降低价格，“买两件就减二十块”指优惠二十块，符合句意。", "赔": "语义：赔是亏损或赔偿，与“很便宜”的语境冲突。", "涨": "语义：涨是提高价格，与“很便宜”矛盾。", "写": "配价：“写”的宾语应是文字，不能说“写二十块”。"}, "sentence_index": 6, "correct_answer": "减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上减到了老朋友。", "explanation": "这里应该用〈遇到〉。减表示去掉一部分或降低，在路上碰见熟人要用〈遇到〉，不能用「减」。"}, {"text": "他把旧玩具减给了弟弟。", "explanation": "这里应该用〈送〉。减表示去掉一部分或降低，把东西转交给别人要用〈送〉，不能用「减」。"}, {"text": "他把脏衣服减干净了。", "explanation": "这里应该用〈洗〉。减表示数量或价格的减少，不用于清洗衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的房租了减两百块。", "corrected_sentence": "这个月的房租减了两百块。", "error_description": "「了」的位置错误：「了」应放在动词之后，正确为「减了两百块」，「了减」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把孩子的零食了减一半。", "corrected_sentence": "我把孩子的零食减了一半。", "error_description": "「了」的位置错误：「了」应放在动词「减」之后，正确为「减了一半」，「了减」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600ff081-b9e6-4639-b094-f920b993636e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
