INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用水煮肉、菜等食物而成的、可以喝的液体食品。", "primary_collocate": null, "pronunciation": "tāng", "ipa": "tʰɑŋ˥", "syllable_count": 1, "sentences": [{"text": "妈妈用排骨和玉米煮了一锅汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这锅汤要煮两个小时。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把肉洗好，放进水里煮成汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里有很多肉和菜。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮汤的时候要放一点盐。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病时，奶奶会给我煮热汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用牛肉和西红柿做汤。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤是用鱼和豆腐煮的。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤煮好以后，再放青菜。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，一锅热汤让全家人都暖和起来。", "target_word": "汤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "锅", "label": "量词"}, {"form": "鸡汤", "label": "复合"}, {"form": "湯", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用水煮肉、菜等做成的可喝的液体食品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21b9fb63-3c69-458d-b44f-bee06f189b40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汤", "is_correct": true, "explanation": "汤（tāng）：用水煮肉、菜等食物而成的可以喝的液体食品。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 tāng（第一声）声调不同，意思是糖。"}, {"text": "烫", "is_correct": false, "explanation": "tàng（第四声）与 tāng（第一声）声调不同，意思是烫。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 tāng（第一声）声调不同，意思是躺下。"}, {"text": "滩", "is_correct": false, "explanation": "tān 与 tāng 韵母不同（an/ang），意思是海滩。"}], "explanations": {"汤": "汤（tāng）：用水煮肉、菜等食物而成的可以喝的液体食品。", "糖": "táng（第二声）与 tāng（第一声）声调不同，意思是糖。", "烫": "tàng（第四声）与 tāng（第一声）声调不同，意思是烫。", "躺": "tǎng（第三声）与 tāng（第一声）声调不同，意思是躺下。", "滩": "tān 与 tāng 韵母不同（an/ang），意思是海滩。"}, "sentence_index": null, "correct_answer": "汤"}, "level_3": {"options": [{"text": "衣服", "is_correct": false, "explanation": "语义：句中“排骨和玉米”是食材，“煮了一锅”后应是食物，衣服不符合句意。"}, {"text": "汤", "is_correct": true, "explanation": "“汤”是用排骨和玉米煮成的，与“煮了一锅”搭配。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能用锅煮，句子在语义上不成立。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“煮”不能与“作业”搭配，句子不通。"}], "explanations": {"衣服": "语义：句中“排骨和玉米”是食材，“煮了一锅”后应是食物，衣服不符合句意。", "汤": "“汤”是用排骨和玉米煮成的，与“煮了一锅”搭配。", "电脑": "语义：电脑不能用锅煮，句子在语义上不成立。", "作业": "搭配：“煮”不能与“作业”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "汤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸每天早上榨一杯汤。", "explanation": "这里应该用〈橙汁〉。榨是把水果取汁，汤是用水煮出来的，不能用“榨”来做。"}, {"text": "妈妈煮了一只汤。", "explanation": "这里应该用〈锅〉。汤用“锅”或“碗”计量，“只”不能用来数汤。"}, {"text": "他用汤写字。", "explanation": "这里应该用〈墨水〉。墨水可以用来写字，汤不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94668, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "汤", "is_correct": true, "explanation": "汤（tāng）：用水煮肉、菜等食物而成的可以喝的液体食品。"}, {"text": "堂", "is_correct": false, "explanation": "táng（第二声）与 tāng（第一声）声调不同，意思是厅堂。"}, {"text": "趟", "is_correct": false, "explanation": "tàng（第四声）与 tāng（第一声）声调不同，意思是一趟（量词）。"}, {"text": "摊", "is_correct": false, "explanation": "tān 与 tāng 韵母不同（an/ang），意思是摊子。"}], "explanations": {"汤": "汤（tāng）：用水煮肉、菜等食物而成的可以喝的液体食品。", "堂": "táng（第二声）与 tāng（第一声）声调不同，意思是厅堂。", "趟": "tàng（第四声）与 tāng（第一声）声调不同，意思是一趟（量词）。", "摊": "tān 与 tāng 韵母不同（an/ang），意思是摊子。"}, "sentence_index": null, "correct_answer": "汤"}, "level_3": {"options": [{"text": "电话", "is_correct": false, "explanation": "搭配：“做”不能与“电话”搭配，句子不通。"}, {"text": "汤", "is_correct": true, "explanation": "“汤”是用牛肉和西红柿做成的，与“做”搭配。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“做”不能与“声音”搭配，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：用牛肉和西红柿不能做出月亮，句意不成立。"}], "explanations": {"电话": "搭配：“做”不能与“电话”搭配，句子不通。", "汤": "“汤”是用牛肉和西红柿做成的，与“做”搭配。", "声音": "搭配：“做”不能与“声音”搭配，句子不通。", "月亮": "语义：用牛肉和西红柿不能做出月亮，句意不成立。"}, "sentence_index": 6, "correct_answer": "汤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每晚在脸上涂汤。", "explanation": "这里应该用〈面膜〉。涂在脸上的是面膜，汤不能用来敷脸。"}, {"text": "妈妈用汤浇花。", "explanation": "这里应该用〈水〉。给花浇水用水，汤不能用来浇花。"}, {"text": "他用汤画了一幅画。", "explanation": "这里应该用〈颜料〉。画画用颜料，汤不能用来画画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈煮了一块汤，全家人都喝了。", "corrected_sentence": "妈妈煮了一锅汤，全家人都喝了。", "error_description": "错误在“汤”的量词。汤应用“锅”计量，“块”多用于固体，不能用来数汤，应改为“一锅汤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他煮了一台汤，味道很好。", "corrected_sentence": "他煮了一锅汤，味道很好。", "error_description": "错误在“汤”的量词。汤应用“锅”计量，“台”不能用来数汤，应改为“一锅汤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce8334a-a829-4949-82bc-6cb7af2ab02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
