INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94669, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爆是东西突然裂开，还发出很大的声音。", "primary_collocate": null, "pronunciation": "bào", "ipa": "pɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "气球突然爆了，吓了我一跳。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开到一半，轮胎爆了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的玉米一粒一粒地爆开。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯泡爆了，房间一下子黑了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一踩，那个塑料袋就爆了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "栗子放进火里，很快就爆开了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子遇热突然爆了，水洒了一地。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天水管冻爆了，家里到处是水。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点儿，气球再吹就要爆了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把气球吹得太大，结果爆了。", "target_word": "爆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爆了", "label": "完成体"}, {"form": "爆过", "label": "经历体"}, {"form": "爆开", "label": "复合"}], "register": "通用", "sense_fingerprint": "气球、轮胎等东西突然裂开并发出响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e262c980-de0c-4b91-944b-cfed1898ea21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94669, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爆", "is_correct": true, "explanation": "bào（第四声）：东西突然裂开并发出响声，即本义。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹。"}, {"text": "保", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护、保持。"}, {"text": "炮", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是大炮或炮竹。"}, {"text": "泡", "is_correct": false, "explanation": "pào 与 bào 声母不同（p 与 b），意思是泡水或气泡。"}], "explanations": {"爆": "bào（第四声）：东西突然裂开并发出响声，即本义。", "包": "bāo（第一声）与 bào（第四声）声调不同，意思是包裹。", "保": "bǎo（第三声）与 bào（第四声）声调不同，意思是保护、保持。", "炮": "pào 与 bào 声母不同（p 与 b），意思是大炮或炮竹。", "泡": "pào 与 bào 声母不同（p 与 b），意思是泡水或气泡。"}, "sentence_index": null, "correct_answer": "爆"}, "level_3": {"options": [{"text": "爆", "is_correct": true, "explanation": "爆：突然裂开并发出响声，与“吓了我一跳”呼应。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”要求唱出歌曲，气球不会唱歌，句子说不通。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”指人或物直立，不能说气球突然“站了”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要能进食的主语，气球不能吃东西。"}], "explanations": {"爆": "爆：突然裂开并发出响声，与“吓了我一跳”呼应。", "唱": "语义：“唱”要求唱出歌曲，气球不会唱歌，句子说不通。", "站": "搭配：“站”指人或物直立，不能说气球突然“站了”。", "吃": "配价：“吃”需要能进食的主语，气球不能吃东西。"}, "sentence_index": 0, "correct_answer": "爆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一不小心把花瓶打翻了。", "explanation": "这里应该用〈打翻〉。爆指东西自己突然裂开并发出响声，花瓶被碰倒要用打翻。"}, {"text": "水倒得太满，都爆出来了。", "explanation": "这里应该用〈溢〉。爆指东西突然裂开或猛然发出，水满得流出来要用溢出。"}, {"text": "雪在阳光下慢慢爆化了。", "explanation": "这里应该用〈融化〉。爆指猛然裂开或发出响声，雪慢慢变成水要用融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爆", "is_correct": true, "explanation": "bào（第四声）：东西突然裂开并发出响声，即本义。"}, {"text": "薄", "is_correct": false, "explanation": "báo（第二声）与 bào（第四声）声调不同，意思是薄厚的薄。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo（第三声）与 bào（第四声）声调不同，意思是宝贝。"}, {"text": "剥", "is_correct": false, "explanation": "bāo（第一声）与 bào（第四声）声调不同，意思是剥开。"}], "explanations": {"爆": "bào（第四声）：东西突然裂开并发出响声，即本义。", "薄": "báo（第二声）与 bào（第四声）声调不同，意思是薄厚的薄。", "饱": "bǎo（第三声）与 bào（第四声）声调不同，意思是吃饱。", "宝": "bǎo（第三声）与 bào（第四声）声调不同，意思是宝贝。", "剥": "bāo（第一声）与 bào（第四声）声调不同，意思是剥开。"}, "sentence_index": null, "correct_answer": "爆"}, "level_3": {"options": [{"text": "爆", "is_correct": true, "explanation": "爆：遇热突然裂开并发出响声，与“水洒了一地”的结果相符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”的主语是人或动物，杯子不会睡觉。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要有人施动，句中没有人扔杯子，不成立。"}, {"text": "咳", "is_correct": false, "explanation": "语义：咳嗽的主语是人或动物，杯子不会咳嗽。"}], "explanations": {"爆": "爆：遇热突然裂开并发出响声，与“水洒了一地”的结果相符。", "睡": "语义：“睡”的主语是人或动物，杯子不会睡觉。", "扔": "配价：“扔”需要有人施动，句中没有人扔杯子，不成立。", "咳": "语义：咳嗽的主语是人或动物，杯子不会咳嗽。"}, "sentence_index": 6, "correct_answer": "爆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花瓣一片片地爆下来。", "explanation": "这里应该用〈落〉。爆指猛然裂开或发出响声，花瓣慢慢飘落要用落。"}, {"text": "眼泪一滴滴爆下来。", "explanation": "这里应该用〈流〉。爆指猛然裂开或发出响声，眼泪一滴滴流下要用流。"}, {"text": "他一拳把玻璃爆了。", "explanation": "这里应该用〈打碎〉。爆是东西自己裂开，人用拳头弄碎玻璃要用打碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的自行车胎在路上被突然爆了。", "corrected_sentence": "我的自行车胎在路上突然爆了。", "error_description": "多了“被”。“爆”是不及物动词，表示物体自己裂开，不能用被字句。应说“……突然爆了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天的水管突然爆着了。", "corrected_sentence": "冬天的水管突然爆了。", "error_description": "多了“着”。表示“爆”这一变化已经发生，要用“了”，不能用“着”，应说“……突然爆了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3f1368e-f69d-4bfd-ba8b-3099d3380707') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失效", "is_correct": true, "explanation": "反义：“失效”指规定、通知失去效力，与“生效”正好相反。"}, {"text": "颁布", "is_correct": false, "explanation": "“颁布”指正式公布法令，是生效前的步骤，不是反义词。"}, {"text": "制定", "is_correct": false, "explanation": "“制定”指拟定条文，与“生效”没有反义关系。"}, {"text": "执行", "is_correct": false, "explanation": "“执行”指按规定去做，与“生效”不构成反义。"}], "correct_answer": "失效", "explanations": {"失效": "反义：“失效”指规定、通知失去效力，与“生效”正好相反。", "颁布": "“颁布”指正式公布法令，是生效前的步骤，不是反义词。", "制定": "“制定”指拟定条文，与“生效”没有反义关系。", "执行": "“执行”指按规定去做，与“生效”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失效", "is_correct": true, "explanation": "反义：“失效”指失去效力，与“生效”正好相反。"}, {"text": "公布", "is_correct": false, "explanation": "“公布”指向社会发布信息，是生效前的环节，不是反义词。"}, {"text": "草拟", "is_correct": false, "explanation": "“草拟”指初步起草文件，与“生效”没有反义关系。"}, {"text": "落实", "is_correct": false, "explanation": "“落实”指使计划、规定真正实行，与“生效”不构成反义。"}], "correct_answer": "失效", "explanations": {"失效": "反义：“失效”指失去效力，与“生效”正好相反。", "公布": "“公布”指向社会发布信息，是生效前的环节，不是反义词。", "草拟": "“草拟”指初步起草文件，与“生效”没有反义关系。", "落实": "“落实”指使计划、规定真正实行，与“生效”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生效是规定从这时候开始有用。", "primary_collocate": null, "pronunciation": "shēng xiào", "ipa": "ʂɤŋ˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "新的规定从明天起生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规则从今天开始生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的新制度下个月一号生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份通知今天中午十二点生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定生效了，大家都要遵守。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法什么时候生效？", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通知上写着，新规则下周一生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车的新规定已经生效了。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定生效以后，公司上班时间变了。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项制度明年三月正式生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生效了", "label": "体标"}, {"form": "生效日期", "label": "复合"}], "register": "书面", "sense_fingerprint": "规定、制度、通知从某个时间点起开始有效", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生效", "is_correct": true, "explanation": "表示新规定从明天起开始有效，与句意相符。"}, {"text": "作废", "is_correct": false, "explanation": "语义：“作废”指失去效力，与“新的规定从明天起”刚开始有效的语境相矛盾。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”的主体是人，规定不能“下班”。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”指表决或审核这一行为，不表示从某时起开始有效。"}], "explanations": {"生效": "表示新规定从明天起开始有效，与句意相符。", "作废": "语义：“作废”指失去效力，与“新的规定从明天起”刚开始有效的语境相矛盾。", "下班": "搭配：“下班”的主体是人，规定不能“下班”。", "通过": "语义：“通过”指表决或审核这一行为，不表示从某时起开始有效。"}, "sentence_index": 0, "correct_answer": "生效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试已经生效了。", "explanation": "这里应该用〈结束〉。“生效”指规定、制度等从某时起开始有效，考试没有这样的过程，应说“结束”。"}, {"text": "这辆汽车从今天起生效。", "explanation": "这里应该用〈启用〉。“生效”指规定、制度等从某时起有效，汽车应说“启用”。"}, {"text": "我从下周一开始生效。", "explanation": "这里应该用〈上班〉。“生效”的主语只能是规定、制度、通知等，人不能“生效”，应说“上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生效", "is_correct": true, "explanation": "表示新规则下周一开始有效，与句意相符。"}, {"text": "下课", "is_correct": false, "explanation": "搭配：“下课”用于课堂，规则不能“下课”。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于会议、比赛等活动，不能用于规则。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指停止上课或上班，与规则从某日起有效的语境不符。"}], "explanations": {"生效": "表示新规则下周一开始有效，与句意相符。", "下课": "搭配：“下课”用于课堂，规则不能“下课”。", "开幕": "搭配：“开幕”用于会议、比赛等活动，不能用于规则。", "放假": "语义：“放假”指停止上课或上班，与规则从某日起有效的语境不符。"}, "sentence_index": 6, "correct_answer": "生效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司明年三月正式生效。", "explanation": "这里应该用〈成立〉。“生效”只用于规定、制度、合同等，公司应说“成立”。"}, {"text": "这间教室明年三月正式生效。", "explanation": "这里应该用〈启用〉。“生效”只用于规定、制度等，教室应说“启用”。"}, {"text": "这位学生明年三月正式生效。", "explanation": "这里应该用〈入学〉。“生效”只用于规定、制度等，人不能“生效”，学生应说“入学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份通知下周一生效了。", "corrected_sentence": "这份通知下周一生效。", "error_description": "表示尚未到来的时间（下周一），不能用“了”表示已完成；应说“下周一生效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的停车规定明天开始生效了。", "corrected_sentence": "新的停车规定明天开始生效。", "error_description": "表示尚未到来的时间（明天），不能用“了”表示已完成；应说“明天开始生效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失效", "is_correct": true, "explanation": "反义：“失效”指药效消失、不再起作用，与“生效”正好相反。"}, {"text": "运转", "is_correct": false, "explanation": "“运转”指机器、组织等运行，与“生效”没有反义关系。"}, {"text": "签署", "is_correct": false, "explanation": "“签署”指在文件上签字，与“生效”不构成反义。"}, {"text": "销毁", "is_correct": false, "explanation": "“销毁”指彻底毁掉，与“生效”没有反义关系。"}], "correct_answer": "失效", "explanations": {"失效": "反义：“失效”指药效消失、不再起作用，与“生效”正好相反。", "运转": "“运转”指机器、组织等运行，与“生效”没有反义关系。", "签署": "“签署”指在文件上签字，与“生效”不构成反义。", "销毁": "“销毁”指彻底毁掉，与“生效”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失效", "is_correct": true, "explanation": "反义：“失效”指失去效力，与“生效”正好相反。"}, {"text": "颁布", "is_correct": false, "explanation": "“颁布”指正式公布法令，是生效前的步骤，不是反义词。"}, {"text": "制定", "is_correct": false, "explanation": "“制定”指拟定条文，与“生效”没有反义关系。"}, {"text": "执行", "is_correct": false, "explanation": "“执行”指按规定去做，与“生效”不构成反义。"}], "correct_answer": "失效", "explanations": {"失效": "反义：“失效”指失去效力，与“生效”正好相反。", "颁布": "“颁布”指正式公布法令，是生效前的步骤，不是反义词。", "制定": "“制定”指拟定条文，与“生效”没有反义关系。", "执行": "“执行”指按规定去做，与“生效”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法律、合同、药物等开始产生效力或效果。", "primary_collocate": null, "pronunciation": "shēng xiào", "ipa": "ʂɤŋ˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药要半小时才能生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法律明年一月生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同签字后，马上就生效了。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒药已经生效，我不咳嗽了。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同还没有生效，你先别着急。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药物生效以后，病人睡着了。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协议要双方签字才能生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法律对所有人都生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫苗打了两周才生效。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法生效后，司机不能再开车打电话。", "target_word": "生效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生效了", "label": "体标"}, {"form": "生效日期", "label": "复合"}], "register": "书面", "sense_fingerprint": "法律、合同、药物等开始产生效力或效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生效", "is_correct": true, "explanation": "表示药物需要半小时才开始起作用，与句意相符。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”用于法令、规定，不能用于药品。"}, {"text": "签署", "is_correct": false, "explanation": "搭配：“签署”用于文件、协议，药品不能被签署。"}, {"text": "作废", "is_correct": false, "explanation": "语义：“作废”指失去效力，与“要半小时才能”才起作用的语境相矛盾。"}], "explanations": {"生效": "表示药物需要半小时才开始起作用，与句意相符。", "颁布": "搭配：“颁布”用于法令、规定，不能用于药品。", "签署": "搭配：“签署”用于文件、协议，药品不能被签署。", "作废": "语义：“作废”指失去效力，与“要半小时才能”才起作用的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "生效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的感冒已经生效了，今天好多了。", "explanation": "这里应该用〈好转〉。“生效”的对象是药物、法律等，病症本身只能说“好转”，不能说“生效”。"}, {"text": "张医生已经生效了。", "explanation": "这里应该用〈上任〉。“生效”只用于法律、合同、药物等，人不能“生效”，应说“上任”。"}, {"text": "我吃了药，身体已经生效。", "explanation": "这里应该用〈康复〉。“生效”的主语应是药物本身，不能说“身体生效”，身体好转应说“康复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生效", "is_correct": true, "explanation": "表示协议经双方签字后开始产生效力，与句意相符。"}, {"text": "起草", "is_correct": false, "explanation": "搭配：“起草”是拟写文件的初步工作，不以双方签字为条件，与句意不符。"}, {"text": "朗诵", "is_correct": false, "explanation": "语义：“朗诵”指出声诵读作品，与协议需双方签字的条件无关。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与“双方签字才能”开始产生效力的语境不符。"}], "explanations": {"生效": "表示协议经双方签字后开始产生效力，与句意相符。", "起草": "搭配：“起草”是拟写文件的初步工作，不以双方签字为条件，与句意不符。", "朗诵": "语义：“朗诵”指出声诵读作品，与协议需双方签字的条件无关。", "翻译": "语义：“翻译”指转换语言，与“双方签字才能”开始产生效力的语境不符。"}, "sentence_index": 6, "correct_answer": "生效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演唱会明天正式生效。", "explanation": "这里应该用〈开幕〉。“生效”只用于法律、合同、药物等，演唱会应说“开幕”。"}, {"text": "这栋大楼明天正式生效。", "explanation": "这里应该用〈竣工〉。“生效”只用于法律、合同、药物等，建筑物应说“竣工”。"}, {"text": "这位学生明天正式生效。", "explanation": "这里应该用〈入学〉。“生效”只用于法律、合同、药物等，人不能“生效”，学生应说“入学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药大概二十分钟后才能生效了。", "corrected_sentence": "这种药大概二十分钟后才能生效。", "error_description": "“才能”表示尚未发生的条件，后面不能加“了”；应说“才能生效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项规定生效了后，大家都要遵守。", "corrected_sentence": "这项规定生效后，大家都要遵守。", "error_description": "“生效”与“后”之间不能直接插入“了”（“生效了以后”可以，“生效了后”不行）；应说“生效后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
