INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男友是一个女孩喜欢的、常在一起的男生。", "primary_collocate": null, "pronunciation": "nán yǒu", "ipa": "nan˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她的男友今天来接她下班。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我男友很喜欢做饭。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末她和男友去公园玩。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小美给男友买了一件衣服。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她男友个子很高，也很爱笑。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常和男友一起看电影。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男友住在她家旁边。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，男友给她送来一把伞。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天带着男友回家见爸爸妈妈。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有男友，我只有几个好朋友。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "前男友", "label": "复合"}], "register": "口语", "sense_fingerprint": "女孩喜欢、常在一起的男生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男友", "is_correct": true, "explanation": "正确：男友指女子的男性恋爱对象，读作 nán yǒu。"}, {"text": "篮友", "is_correct": false, "explanation": "lán 与 nán 声母不同（l 与 n），篮友指一起打篮球的朋友。"}, {"text": "难友", "is_correct": false, "explanation": "第一个音节声调不同（nàn 第四声与 nán 第二声），难友指一同受难的人。"}, {"text": "男优", "is_correct": false, "explanation": "第二个音节声调不同（yōu 第一声与 yǒu 第三声），男优指男演员。"}], "explanations": {"男友": "正确：男友指女子的男性恋爱对象，读作 nán yǒu。", "篮友": "lán 与 nán 声母不同（l 与 n），篮友指一起打篮球的朋友。", "难友": "第一个音节声调不同（nàn 第四声与 nán 第二声），难友指一同受难的人。", "男优": "第二个音节声调不同（yōu 第一声与 yǒu 第三声），男优指男演员。"}, "sentence_index": null, "correct_answer": "男友"}, "level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不会来接人下班，句子荒谬。"}, {"text": "男友", "is_correct": true, "explanation": "正确：男友是女子的恋爱对象，符合“今天来接她下班”的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“来接”要求有生命的人作主语，冰箱不能充当。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不会来接人下班，句意不通。"}], "explanations": {"老鼠": "语义：老鼠不会来接人下班，句子荒谬。", "男友": "正确：男友是女子的恋爱对象，符合“今天来接她下班”的语境。", "冰箱": "搭配：“来接”要求有生命的人作主语，冰箱不能充当。", "猫": "语义：猫不会来接人下班，句意不通。"}, "sentence_index": 0, "correct_answer": "男友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和男友结婚已经十年了，孩子也上小学了。", "explanation": "这里应该用〈丈夫〉。男友指还没有结婚的恋爱对象，已经结婚就用丈夫。"}, {"text": "我们班里有很多男友，都很喜欢打篮球。", "explanation": "这里应该用〈男生〉。男友指恋爱对象，不能泛指班里的男同学。"}, {"text": "医院里有一个男友，刚出生三天。", "explanation": "这里应该用〈男婴〉。男友指恋爱对象，刚出生的婴儿不能称为男友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：小说不能住在某个地方，句意荒谬。"}, {"text": "男友", "is_correct": true, "explanation": "正确：男友是恋爱对象，可以住在她家旁边。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“住”要求人或动物作主语，房子不能说“住”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能住在她家旁边，句子不通。"}], "explanations": {"小说": "语义：小说不能住在某个地方，句意荒谬。", "男友": "正确：男友是恋爱对象，可以住在她家旁边。", "房子": "搭配：“住”要求人或动物作主语，房子不能说“住”。", "手机": "语义：手机不能住在她家旁边，句子不通。"}, "sentence_index": 6, "correct_answer": "男友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和男友只是普通的交情，平时很少见面。", "explanation": "这里应该用〈朋友〉。男友指恋爱对象，只是普通交往的人应说朋友。"}, {"text": "路边站着一个小孩，大概五岁。", "explanation": "这里应该用〈小孩〉。男友指恋爱对象，五岁的小孩不能称为男友。"}, {"text": "春节时，男友来我家吃饭，他是我舅舅的孩子。", "explanation": "这里应该用〈表亲〉。男友指恋爱对象，亲戚不能称为男友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月认识了一条男友，他是老师。", "corrected_sentence": "她上个月认识了一个男友，他是老师。", "error_description": "量词错误：男友指人，应说〈一个男友〉；〈条〉用于细长的东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从前过有男友，后来分手了。", "corrected_sentence": "她从前有过男友，后来分手了。", "error_description": "体标位置错误：经历体“过”要紧跟动词，应说〈有过男友〉，不能说〈过有男友〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
