INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女子的男性恋爱对象，男朋友的简称。", "primary_collocate": null, "pronunciation": "nán yǒu", "ipa": "nan˧˥ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她的男友是一位医生。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和男友已经谈了三年恋爱。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把男友介绍给自己的父母。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男友过生日，她送了他一块手表。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和男友吵架了，心情不好。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林的男友在北京工作，她很想他。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟男友说好明年结婚。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的男友每天晚上都给我打电话。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是情人节，男友送给她一束花。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她男友很会照顾人，大家都喜欢他。", "target_word": "男友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "前男友", "label": "复合"}], "register": "口语", "sense_fingerprint": "男朋友的简称，女子的恋爱对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
