INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是人，不能说“跟海洋说好明年结婚”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“说好结婚”要求有意识的人作对象，石头不能与之搭配。"}, {"text": "男友", "is_correct": true, "explanation": "正确：男友是恋爱对象，可以和她约定结婚。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能和人约定结婚，句意荒谬。"}], "explanations": {"海洋": "语义：海洋不是人，不能说“跟海洋说好明年结婚”。", "石头": "搭配：“说好结婚”要求有意识的人作对象，石头不能与之搭配。", "男友": "正确：男友是恋爱对象，可以和她约定结婚。", "雨伞": "语义：雨伞不能和人约定结婚，句意荒谬。"}, "sentence_index": 6, "correct_answer": "男友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和男友在公司只是点头之交，平时很少说话。", "explanation": "这里应该用〈同事〉。男友指恋爱对象，公司里的普通同事不能称男友。"}, {"text": "路上有个男友，偷走了一位老人的钱包。", "explanation": "这里应该用〈小偷〉。男友指恋爱对象，偷东西的陌生人不能这样称呼。"}, {"text": "我的男友是我爸爸的小儿子。", "explanation": "这里应该用〈弟弟〉。男友指恋爱对象，家人不能称为男友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐上个月有了一张男友。", "corrected_sentence": "姐姐上个月有了一个男友。", "error_description": "量词错误：男友指人，应说〈一个男友〉；〈张〉用于平面的东西，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的男友的很温柔，大家都喜欢他。", "corrected_sentence": "她的男友很温柔，大家都喜欢他。", "error_description": "结构错误：〈男友〉后面不应再加〈的〉，应说〈她的男友很温柔〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
