INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "监视是一直看着，不让对方走开或做坏事。", "primary_collocate": null, "pronunciation": "jiān shì", "ipa": "tɕjɛn˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "警察一直监视着那个小偷。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕妻子乱花钱，天天监视她。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在后面监视着工人干活，不让他们休息。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个警察监视着坐在地上的人，不让他跑。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想让我走，所以一直监视我。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别监视我，我不会做坏事的。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安监视着门口，不让陌生人进来。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥监视着弟弟，不让他玩手机。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把他关在房间里，还派人监视他。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狱警一直监视着那个犯人，怕他逃跑。", "target_word": "监视", "complexity_tier": "T3", "furigana": "yù jǐng yì zhí jiān shì zhe nà ge fàn rén, pà tā táo pǎo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "监视着", "label": "体标"}, {"form": "监视了", "label": "体标"}, {"form": "监视过", "label": "体标"}, {"form": "监视器", "label": "复合"}], "register": "书面", "sense_fingerprint": "一直盯着对方，不让他走开或做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着对方，不让他走开或做坏事。"}, {"text": "监制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。"}, {"text": "家事", "is_correct": false, "explanation": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。"}, {"text": "今世", "is_correct": false, "explanation": "jīn 与 jiān 韵母不同（少一个 a），意思是今生、这一辈子。"}], "explanations": {"监视": "监视：一直看着对方，不让他走开或做坏事。", "监制": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。", "家事": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。", "今世": "jīn 与 jiān 韵母不同（少一个 a），意思是今生、这一辈子。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着，不让对方走开，与“抓小偷”的语境相合。"}, {"text": "陪伴", "is_correct": false, "explanation": "语义：“陪伴”表示陪同做伴，与警察抓小偷的语境相反。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”用于远处的景物，不能用于近距离盯着一个人。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”表示良好的祝愿，与小偷的语境不合。"}], "explanations": {"监视": "监视：一直看着，不让对方走开，与“抓小偷”的语境相合。", "陪伴": "语义：“陪伴”表示陪同做伴，与警察抓小偷的语境相反。", "眺望": "搭配：“眺望”用于远处的景物，不能用于近距离盯着一个人。", "祝福": "语义：“祝福”表示良好的祝愿，与小偷的语境不合。"}, "sentence_index": 0, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在剧院监视了一场精彩的演出。", "explanation": "这里应该用〈观看〉。监视针对需要防止走开或作恶的人，看演出要用观看。"}, {"text": "他们在湖边监视美妙的音乐。", "explanation": "这里应该用〈聆听〉。音乐不会走开或作恶，听音乐要用聆听。"}, {"text": "他蹲在河边监视鱼儿游来游去，看得入迷。", "explanation": "这里应该用〈观赏〉。监视是为了防止走开或作恶而一直看着，为欣赏鱼儿游动而看，要用观赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着对方，不让他走开或做坏事。"}, {"text": "坚实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。"}, {"text": "检视", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。"}, {"text": "将士", "is_correct": false, "explanation": "jiàng 与 jiān 韵母不同（ang 与 an），意思是军队里的士兵。"}], "explanations": {"监视": "监视：一直看着对方，不让他走开或做坏事。", "坚实": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。", "检视": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。", "将士": "jiàng 与 jiān 韵母不同（ang 与 an），意思是军队里的士兵。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：一直看着，不让对方走开或进入，与“不让陌生人进来”的语境相合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对损坏的东西，与“不让陌生人进来”的语境不合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱地看，与防止陌生人进入的语境不合。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是可以移动的物品，“门口”是地点，不能被搬运。"}], "explanations": {"监视": "监视：一直看着，不让对方走开或进入，与“不让陌生人进来”的语境相合。", "修理": "语义：“修理”针对损坏的东西，与“不让陌生人进来”的语境不合。", "欣赏": "语义：“欣赏”表示喜爱地看，与防止陌生人进入的语境不合。", "搬运": "搭配：“搬运”的对象是可以移动的物品，“门口”是地点，不能被搬运。"}, "sentence_index": 6, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在门口监视新同学的到来。", "explanation": "这里应该用〈欢迎〉。监视是防范性的注意观察，不能表示热情的迎接。"}, {"text": "我们在山顶监视日出。", "explanation": "这里应该用〈欣赏〉。日出不会走开或作恶，看日出要用欣赏。"}, {"text": "他细细监视这杯茶的味道。", "explanation": "这里应该用〈品尝〉。监视针对需要防范的人或情况，尝味道要用品尝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把那个小偷监视很紧，他跑不了。", "corrected_sentence": "警察把那个小偷监视得很紧，他跑不了。", "error_description": "错误：“监视很紧”。动词后带程度补语时，中间要加“得”：“监视得很紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保安正在监视了后门，不让陌生人进来。", "corrected_sentence": "保安正在监视着后门，不让陌生人进来。", "error_description": "错误：“正在监视了”。“正在”表示动作进行，要与“着”搭配，不能与“了”同用：应为“正在监视着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
