INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从旁边注意观察，防止发生意外或不法行为。", "primary_collocate": null, "pronunciation": "jiān shì", "ipa": "tɕjɛn˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "警察在门口监视着可疑的人。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员用电脑监视机器的情况。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生一直监视着病人的变化。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察监视了他很久，最后抓住了他。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄像头监视着店里的一切。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在远处监视这个地方。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在楼上监视着这条街。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们夜里轮流监视堤坝，怕出现险情。", "target_word": "监视", "complexity_tier": "T3", "furigana": "gōng rén men yè lǐ lún liú jiān shì dī bà, pà chū xiàn xiǎn qíng.", "sentence_source": "generated"}, {"text": "警察已经监视这家店三天了。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得有人在监视自己。", "target_word": "监视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监视着", "label": "体标"}, {"form": "监视了", "label": "体标"}, {"form": "监视过", "label": "体标"}, {"form": "监视器", "label": "复合"}], "register": "书面", "sense_fingerprint": "从旁边观察，防止意外或不法行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：从旁边注意观察，防止发生意外或不法行为。"}, {"text": "坚实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。"}, {"text": "检视", "is_correct": false, "explanation": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。"}, {"text": "将士", "is_correct": false, "explanation": "jiàng 与 jiān 韵母不同（ang 与 an），意思是军队里的士兵。"}], "explanations": {"监视": "监视：从旁边注意观察，防止发生意外或不法行为。", "坚实": "shí（第二声）与 shì（第四声）声调不同，意思是结实、可靠。", "检视": "jiǎn（第三声）与 jiān（第一声）声调不同，意思是仔细检查、审视。", "将士": "jiàng 与 jiān 韵母不同（ang 与 an），意思是军队里的士兵。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：从旁边注意观察，防止意外或不法行为，与“可疑的人”的语境相合。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”指照料、关怀，与“可疑的人”的防范语境相反。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”用于远处的景物，不能用于近处盯着某个人。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示善意的接待，与“可疑”的防范语境冲突。"}], "explanations": {"监视": "监视：从旁边注意观察，防止意外或不法行为，与“可疑的人”的语境相合。", "照顾": "语义：“照顾”指照料、关怀，与“可疑的人”的防范语境相反。", "眺望": "搭配：“眺望”用于远处的景物，不能用于近处盯着某个人。", "欢迎": "语义：“欢迎”表示善意的接待，与“可疑”的防范语境冲突。"}, "sentence_index": 0, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在广场上监视了一场精彩的表演。", "explanation": "这里应该用〈观看〉。监视是为了防止意外或不法行为而注意观察，看表演要用观看。"}, {"text": "他每天都监视自己最喜欢的歌手的动态。", "explanation": "这里应该用〈关注〉。监视含有防范的意味，关心偶像的动态只能用关注。"}, {"text": "游客们在山顶监视壮丽的风景。", "explanation": "这里应该用〈欣赏〉。风景不会带来意外或不法行为，无需监视，欣赏美景要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：从旁边注意观察，防止发生意外或不法行为。"}, {"text": "监制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。"}, {"text": "家事", "is_correct": false, "explanation": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。"}, {"text": "今世", "is_correct": false, "explanation": "jīn 与 jiān 韵母不同（少一个 a），意思是今生、这一辈子。"}], "explanations": {"监视": "监视：从旁边注意观察，防止发生意外或不法行为。", "监制": "zhì 与 shì 声母不同（zh 与 sh），意思是监督制作，常用于影视、产品。", "家事": "jiā 与 jiān 韵母不同（少一个 n），意思是家里的事情。", "今世": "jīn 与 jiān 韵母不同（少一个 a），意思是今生、这一辈子。"}, "sentence_index": null, "correct_answer": "监视"}, "level_3": {"options": [{"text": "监视", "is_correct": true, "explanation": "监视：从旁边注意观察，防止发生意外，与“有人在楼上”的语境相合。"}, {"text": "教训", "is_correct": false, "explanation": "语义：“教训”针对做错事的人，不能用于一条街。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”的对象多是人或动物，“这条街”不能被驱赶。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”指从多个对象中选取，与“在楼上”的观察语境不合。"}], "explanations": {"监视": "监视：从旁边注意观察，防止发生意外，与“有人在楼上”的语境相合。", "教训": "语义：“教训”针对做错事的人，不能用于一条街。", "驱赶": "搭配：“驱赶”的对象多是人或动物，“这条街”不能被驱赶。", "挑选": "语义：“挑选”指从多个对象中选取，与“在楼上”的观察语境不合。"}, "sentence_index": 6, "correct_answer": "监视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班同学一起监视新来的老师。", "explanation": "这里应该用〈迎接〉。监视是防范性的注意观察，不能表示欢迎。"}, {"text": "大家纷纷监视他取得的成功。", "explanation": "这里应该用〈祝贺〉。监视是为了防止意外，不能用来向别人表达庆贺。"}, {"text": "我们常常监视远去的朋友。", "explanation": "这里应该用〈怀念〉。监视针对需要防范的人或情况，想念远去的朋友要用怀念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一直在那个路口监视了那辆可疑的车，不敢走开。", "corrected_sentence": "我们一直在那个路口监视着那辆可疑的车，不敢走开。", "error_description": "错误：“在……”表示动作正在进行，句中已用“在”，动词后不能再带“了”，应改为“监视着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他夜里监视很仔细，没漏掉任何动静。", "corrected_sentence": "他夜里监视得很仔细，没漏掉任何动静。", "error_description": "错误：“监视很仔细”。动词后带程度补语时，中间要加“得”：“监视得很仔细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
