INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94687, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼泪是难过或太开心时，从眼睛里流出来的水。", "primary_collocate": null, "pronunciation": "yǎn lèi", "ipa": "jɛn˨˩˦ leɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个好消息，妈妈高兴得流下了眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看完电影，眼泪一下子流出来了。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，脸上都是眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思让别人看到自己的眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶笑着笑着，眼泪就掉了下来。", "target_word": "眼泪", "complexity_tier": "T3", "furigana": "nǎi nai xiào zhe xiào zhe yǎn lèi jiù diào le xià lái", "sentence_source": "generated"}, {"text": "请你擦一擦眼泪，别哭了。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她难过得眼泪一直往下流。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到女儿毕业，爸爸的眼泪出来了。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼泪掉在了信纸上。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太开心了，我的眼泪停不下来。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "眼淚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "难过或太开心时从眼睛流出的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼泪", "is_correct": true, "explanation": "眼泪是高兴或难过时从眼睛流出的水，与“高兴得”相合。"}, {"text": "汗水", "is_correct": false, "explanation": "语义：汗水是出汗时流出的，与“高兴得”的情绪不合。"}, {"text": "血", "is_correct": false, "explanation": "语义：“血”不会因高兴而流出，此处语境不合。"}, {"text": "鼻涕", "is_correct": false, "explanation": "语义：鼻涕是从鼻子流出的黏液，不是眼睛里的液体；“高兴得”流出的是眼泪，不是鼻涕，与语境不合。"}], "explanations": {"眼泪": "眼泪是高兴或难过时从眼睛流出的水，与“高兴得”相合。", "汗水": "语义：汗水是出汗时流出的，与“高兴得”的情绪不合。", "血": "语义：“血”不会因高兴而流出，此处语境不合。", "鼻涕": "语义：鼻涕是从鼻子流出的黏液，不是眼睛里的液体；“高兴得”流出的是眼泪，不是鼻涕，与语境不合。"}, "sentence_index": 0, "correct_answer": "眼泪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气太热，他的眼泪湿透了衣服。", "explanation": "这里应该用〈汗水〉。眼泪是难过或激动时流出的，天热时湿透衣服的是汗水。"}, {"text": "锅里的眼泪溢了出来，灶台上到处都是。", "explanation": "这里应该用〈油〉。眼泪是眼睛分泌的液体，不会从锅里溢出；锅里溢出的是油。"}, {"text": "伤口的眼泪一滴一滴地落在地上。", "explanation": "这里应该用〈血〉。眼泪是眼睛分泌的液体，伤口流出的是血，不能说“伤口的眼泪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼泪", "is_correct": true, "explanation": "眼泪是难过时从眼睛流出的液体，与“她难过得”相合。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水来自天空，不是人因难过而流出的液体。"}, {"text": "油", "is_correct": false, "explanation": "语义：“油”不是眼睛分泌的液体，与“难过得”的情绪无关。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“难过得……一直往下流”的是泪，“墨水”不能与这个结构搭配。"}], "explanations": {"眼泪": "眼泪是难过时从眼睛流出的液体，与“她难过得”相合。", "雨水": "语义：雨水来自天空，不是人因难过而流出的液体。", "油": "语义：“油”不是眼睛分泌的液体，与“难过得”的情绪无关。", "墨水": "搭配：“难过得……一直往下流”的是泪，“墨水”不能与这个结构搭配。"}, "sentence_index": 6, "correct_answer": "眼泪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把眼泪晒在了阳光下。", "explanation": "这里应该用〈衣服〉。衣服可以被晒干，眼泪是液体，不能像衣服那样被晒。"}, {"text": "他把眼泪折成了纸鹤。", "explanation": "这里应该用〈纸〉。纸张可以折成纸鹤，眼泪是液体，不能折叠。"}, {"text": "她把桌上的眼泪点燃了。", "explanation": "这里应该用〈酒精〉。酒精可以点燃，眼泪是水分，不能燃烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这首歌，他掉下了一个眼泪。", "corrected_sentence": "听到这首歌，他掉下了一滴眼泪。", "error_description": "错误：“一个眼泪”；正确：“一滴眼泪”。“眼泪”以量词“滴”计量，用“个”不合习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子摔倒了，眼泪一下子就掉下了来。", "corrected_sentence": "孩子摔倒了，眼泪一下子就掉了下来。", "error_description": "错误：“掉下了来”；正确：“掉了下来”。“了”应放在动词与趋向补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
