INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "眼睛里分泌出来的液体，在悲伤、激动或受刺激时流出。", "primary_collocate": null, "pronunciation": "yǎn lèi", "ipa": "jɛn˨˩˦ leɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "切洋葱的时候，辣得我直流眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "furigana": "qiē yáng cōng de shí hou, là de wǒ zhí liú yǎn lèi", "sentence_source": "generated"}, {"text": "风太大了，吹得我直流眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里很难过，眼泪忍不住流了下来。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他激动地握着我的手，眼泪流了出来。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟太呛了，我的眼泪都出来了。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手背擦掉了脸上的眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，她的眼泪一滴一滴往下掉。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩的眼泪像小雨一样落下来。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，眼泪可以保护眼睛。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头转过去，不让别人看见眼泪。", "target_word": "眼泪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "眼淚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "眼睛分泌的液体，悲伤、激动或受刺激时流出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1cc6afb-d9ef-4bf0-9c1b-33171e53fc3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼泪", "is_correct": true, "explanation": "洋葱的辣刺激眼睛会流出眼泪，与“切洋葱的时候，辣得我直流”相合。"}, {"text": "血", "is_correct": false, "explanation": "语义：洋葱的辣刺激眼睛流出的是泪水，不会流血。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水来自天空，与切洋葱时的刺激无关。"}, {"text": "沙子", "is_correct": false, "explanation": "搭配：“直流”接的是液体，不能接固体“沙子”。"}], "explanations": {"眼泪": "洋葱的辣刺激眼睛会流出眼泪，与“切洋葱的时候，辣得我直流”相合。", "血": "语义：洋葱的辣刺激眼睛流出的是泪水，不会流血。", "雨水": "语义：雨水来自天空，与切洋葱时的刺激无关。", "沙子": "搭配：“直流”接的是液体，不能接固体“沙子”。"}, "sentence_index": 0, "correct_answer": "眼泪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动以后，他的眼泪湿透了衣服。", "explanation": "这里应该用〈汗水〉。运动时出的是汗，眼泪不会湿透衣服。"}, {"text": "杯子打翻了，眼泪流了一桌子。", "explanation": "这里应该用〈果汁〉。眼泪是眼睛分泌的液体，打翻的杯子里流出的是果汁。"}, {"text": "他的伤口一直在流眼泪。", "explanation": "这里应该用〈血〉。伤口流出的是血，眼泪是眼睛分泌的液体，不能从伤口流出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼泪", "is_correct": true, "explanation": "眼泪是情绪激动或悲伤时从眼睛流出的液体，与“听到坏消息”相合。"}, {"text": "油", "is_correct": false, "explanation": "语义：“油”不是人体分泌的液体，与“听到坏消息”的情绪无关。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是眼睛分泌的，听到坏消息不会流出墨水。"}, {"text": "石子", "is_correct": false, "explanation": "搭配：量词“滴”只用于液体，“石子”不能说“一滴一滴”。"}], "explanations": {"眼泪": "眼泪是情绪激动或悲伤时从眼睛流出的液体，与“听到坏消息”相合。", "油": "语义：“油”不是人体分泌的液体，与“听到坏消息”的情绪无关。", "墨水": "语义：墨水不是眼睛分泌的，听到坏消息不会流出墨水。", "石子": "搭配：量词“滴”只用于液体，“石子”不能说“一滴一滴”。"}, "sentence_index": 6, "correct_answer": "眼泪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用刀把眼泪切成了小块。", "explanation": "这里应该用〈豆腐〉。豆腐可以用刀切成小块，眼泪是液体，不能切。"}, {"text": "她把眼泪搬到了楼上。", "explanation": "这里应该用〈行李〉。行李可以搬到楼上，眼泪是液体，不能搬动。"}, {"text": "他把眼泪钉在了墙上。", "explanation": "这里应该用〈海报〉。海报可以钉在墙上，眼泪是液体，不能钉在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影很感人，观众的眼泪一个一个地流了下来。", "corrected_sentence": "这部电影很感人，观众的眼泪一滴一滴地流了下来。", "error_description": "错误：量词用“个”；正确：用“滴”。眼泪的量词是“滴”，应说“一滴一滴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她看到老照片，眼泪被静静地落了下来。", "corrected_sentence": "她看到老照片，眼泪静静地落了下来。", "error_description": "错误：“被”用在不及物动词“落”前；正确：去掉“被”。“落”是不及物动词，不能构成“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e537354-3ac4-44b3-b4cd-a66f8945b98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
