INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94693, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等位是去饭馆吃饭时，站着等空位子。", "primary_collocate": null, "pronunciation": "děng wèi", "ipa": "təŋ˨˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "饭馆人很多，我们要等位。", "target_word": "等位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末去火锅店，常常要等位。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在门口等位，等了半小时才有座。", "target_word": "等位", "complexity_tier": "T3", "furigana": "wǒmen zài ménkǒu děngwèi, děng le bàn xiǎoshí cái yǒu zuò", "sentence_source": "generated"}, {"text": "这家店没有空位，客人都在外面等位。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先去等位，我去买饮料。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们站着等位，肚子都饿了。", "target_word": "等位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上七点去吃饭，得等位。", "target_word": "等位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭馆很有名，要提前来等位。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人太多了，我不想等位，咱们换一家吧。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在餐厅门口等位，爸爸去停车。", "target_word": "等位", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等位了", "label": "体标"}, {"form": "等位过", "label": "体标"}], "register": "口语", "sense_fingerprint": "去饭馆吃饭时站着等空位子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等位", "is_correct": true, "explanation": "正确：“等位”指在饭馆等候空出座位，与“饭馆人很多”相符。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”需要带文字内容作宾语，这里没有可译的对象。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补损坏的东西，与在饭馆里因人多而等待无关。"}, {"text": "入睡", "is_correct": false, "explanation": "语义：“入睡”指进入睡眠，与饭馆人多时的等候完全不符。"}], "explanations": {"等位": "正确：“等位”指在饭馆等候空出座位，与“饭馆人很多”相符。", "翻译": "配价：“翻译”需要带文字内容作宾语，这里没有可译的对象。", "修理": "语义：“修理”指修补损坏的东西，与在饭馆里因人多而等待无关。", "入睡": "语义：“入睡”指进入睡眠，与饭馆人多时的等候完全不符。"}, "sentence_index": 0, "correct_answer": "等位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在售票窗口等位买票。", "explanation": "这里应该用〈排队〉。等位专指在饭馆等候空出座位，买票时排队要用排队。"}, {"text": "演员在后台等位，等待上台。", "explanation": "这里应该用〈候场〉。等位专指在饭馆等候空位，演员在后台等待上场要用候场。"}, {"text": "夜班护士在病房等位，随时待命。", "explanation": "这里应该用〈值班〉。等位专指在饭馆等候空位，在岗位上随时待命要用值班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等位", "is_correct": true, "explanation": "正确：“等位”指到饭馆等候空位，与“晚上七点去吃饭”相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与去吃饭的安排毫无关联，句意荒谬。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”指创作文章，与吃饭这件事无关。"}, {"text": "洗车", "is_correct": false, "explanation": "搭配：“洗车”的宾语是车，不能用于吃饭的安排。"}], "explanations": {"等位": "正确：“等位”指到饭馆等候空位，与“晚上七点去吃饭”相符。", "结婚": "语义：“结婚”与去吃饭的安排毫无关联，句意荒谬。", "写作": "语义：“写作”指创作文章，与吃饭这件事无关。", "洗车": "搭配：“洗车”的宾语是车，不能用于吃饭的安排。"}, "sentence_index": 6, "correct_answer": "等位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乘客在站台等位，等车进站。", "explanation": "这里应该用〈等车〉。等位专指在饭馆等候空位，在站台等车要用等车。"}, {"text": "他先到前台等位入住。", "explanation": "这里应该用〈登记〉。等位指在饭馆等空位，办理住宿手续要用登记。"}, {"text": "学生们在操场上等位，准备升旗。", "explanation": "这里应该用〈列队〉。等位专指在饭馆等候空位，集合准备升旗要用列队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭馆人很多，我们正在等位了。", "corrected_sentence": "饭馆人很多，我们正在等位。", "error_description": "错误：“正在”表示动作进行中，与“了”不能同时用。应删去“了”，说“我们正在等位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们等位得很久，才有座位。", "corrected_sentence": "我们等位等得很久，才有座位。", "error_description": "错误：述补结构“V得C”中，“等位”后要重复动词“等”，应说“等位等得很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
