INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94703, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "编号是给每个东西排上一个数字。", "primary_collocate": null, "pronunciation": "biān hào", "ipa": "pjɛn˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈给每个盒子编号。", "target_word": "编号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给我的照片编号。", "target_word": "编号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先编号，再找东西就快了。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，请给每道题编号。", "target_word": "编号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把书架上的书都编号了。", "target_word": "编号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明给自己的玩具车编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些椅子没有编号，所以大家乱坐。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们给这些信封编号，免得弄混。", "target_word": "编号", "complexity_tier": "T3", "furigana": "wǒ men gěi zhè xiē xìn fēng biān hào, miǎn de nòng hùn.", "sentence_source": "generated"}, {"text": "我们给所有的杯子编号，免得拿错。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给每个文件夹编号，以后找起来很方便。", "target_word": "编号", "complexity_tier": "T3", "furigana": "lǎo shī gěi měi gè wén jiàn jiā biān hào, yǐ hòu zhǎo qǐ lái hěn fāng biàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "编号了", "label": "体标"}, {"form": "编号过", "label": "体标"}], "register": "中性", "sense_fingerprint": "给每个东西排上一个数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：给每个东西排上一个数字。"}, {"text": "偏好", "is_correct": false, "explanation": "piān（第一声）与 biān 声母不同（p 与 b），意思是特别喜欢。"}, {"text": "班号", "is_correct": false, "explanation": "bān 与 biān 韵母不同（少一个 i），意思是班级或班次的号码。"}, {"text": "标号", "is_correct": false, "explanation": "biāo 与 biān 韵母不同（ao 与 an），意思是标示的号码或等级。"}, {"text": "编好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是编排或编写完成。"}], "explanations": {"编号": "编号：给每个东西排上一个数字。", "偏好": "piān（第一声）与 biān 声母不同（p 与 b），意思是特别喜欢。", "班号": "bān 与 biān 韵母不同（少一个 i），意思是班级或班次的号码。", "标号": "biāo 与 biān 韵母不同（ao 与 an），意思是标示的号码或等级。", "编好": "hǎo（第三声）与 hào（第四声）声调不同，意思是编排或编写完成。"}, "sentence_index": null, "correct_answer": "编号"}, "level_3": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：给每个东西排上一个数字，与“每个盒子”的语境相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”针对食物，盒子不能煮。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于盒子。"}, {"text": "酿", "is_correct": false, "explanation": "语义：“酿”针对酒、醋等食品，与盒子不合。"}], "explanations": {"编号": "编号：给每个东西排上一个数字，与“每个盒子”的语境相合。", "煮": "语义：“煮”针对食物，盒子不能煮。", "唱": "搭配：“唱”的对象是歌曲，不能用于盒子。", "酿": "语义：“酿”针对酒、醋等食品，与盒子不合。"}, "sentence_index": 0, "correct_answer": "编号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上编号了一朵白云。", "explanation": "这里应该用〈画〉。编号指排上数字，在纸上描绘景物要用画。"}, {"text": "妈妈在厨房编号了一锅粥。", "explanation": "这里应该用〈煮〉。编号不能用于烹饪，煮粥要用煮。"}, {"text": "孩子们在操场上编号歌。", "explanation": "这里应该用〈唱〉。编号指排上数字，不能指唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：给每个东西排上数字，与“大家乱坐”的语境相合。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：椅子不能被翻译，这个说法不成立。"}, {"text": "漂白", "is_correct": false, "explanation": "语义：“漂白”针对布料、衣物等，与椅子乱坐的语境无关。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、灯等，不能用于椅子。"}], "explanations": {"编号": "编号：给每个东西排上数字，与“大家乱坐”的语境相合。", "翻译": "语义：椅子不能被翻译，这个说法不成立。", "漂白": "语义：“漂白”针对布料、衣物等，与椅子乱坐的语境无关。", "点燃": "搭配：“点燃”的对象是火、灯等，不能用于椅子。"}, "sentence_index": 6, "correct_answer": "编号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上编号澡。", "explanation": "这里应该用〈洗〉。编号指排上数字，不能用于洗澡。"}, {"text": "妈妈给客人编号茶。", "explanation": "这里应该用〈泡〉。编号指排上数字，不能用于泡茶。"}, {"text": "演员在舞台上编号精彩的节目。", "explanation": "这里应该用〈表演〉。编号是排上数字，在台上演出要用表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天妈妈给每个盒子编号了。", "corrected_sentence": "明天妈妈给每个盒子编号。", "error_description": "错误：“编号了”。“了”表示已经完成，不能与表示将来的“明天”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经给这些信封编号着，免得弄混。", "corrected_sentence": "我们已经给这些信封编号了，免得弄混。", "error_description": "错误：“编号着”。“已经”表示动作已完成，要用“了”而不是“着”：应为“编号了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
