INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照顺序给事物排定号码；也指所排的号码。", "primary_collocate": null, "pronunciation": "biān hào", "ipa": "pjɛn˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "老师给每张桌子编号。", "target_word": "编号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你把这些书都编号。", "target_word": "编号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的编号是三五八。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先编号，再按顺序排队。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在表格上写下你的编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人给仓库里的箱子编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个座位都有编号，别坐错了。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你查一下这个包裹的编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆要给新书编号，再放上书架。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，老师给每位选手编号。", "target_word": "编号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "编号了", "label": "体标"}, {"form": "编号过", "label": "体标"}], "register": "中性", "sense_fingerprint": "按顺序给事物排号码，也指所排的号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：按照顺序给事物排定号码。"}, {"text": "偏好", "is_correct": false, "explanation": "piān（第一声）与 biān 声母不同（p 与 b），意思是特别喜欢。"}, {"text": "班号", "is_correct": false, "explanation": "bān 与 biān 韵母不同（少一个 i），意思是班级或班次的号码。"}, {"text": "标号", "is_correct": false, "explanation": "biāo 与 biān 韵母不同（ao 与 an），意思是标示的号码或等级。"}, {"text": "编好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是编排或编写完成。"}], "explanations": {"编号": "编号：按照顺序给事物排定号码。", "偏好": "piān（第一声）与 biān 声母不同（p 与 b），意思是特别喜欢。", "班号": "bān 与 biān 韵母不同（少一个 i），意思是班级或班次的号码。", "标号": "biāo 与 biān 韵母不同（ao 与 an），意思是标示的号码或等级。", "编好": "hǎo（第三声）与 hào（第四声）声调不同，意思是编排或编写完成。"}, "sentence_index": null, "correct_answer": "编号"}, "level_3": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：按顺序给事物排定号码，与“每张桌子”的语境相合。"}, {"text": "加热", "is_correct": false, "explanation": "语义：“加热”指使物体变热，给桌子加热与前后语境不合。"}, {"text": "点名", "is_correct": false, "explanation": "语义：“点名”针对的是人，不能用于桌子。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于树木、头发等，不能用于桌子。"}], "explanations": {"编号": "编号：按顺序给事物排定号码，与“每张桌子”的语境相合。", "加热": "语义：“加热”指使物体变热，给桌子加热与前后语境不合。", "点名": "语义：“点名”针对的是人，不能用于桌子。", "修剪": "搭配：“修剪”用于树木、头发等，不能用于桌子。"}, "sentence_index": 0, "correct_answer": "编号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用电脑编号了这段风声。", "explanation": "这里应该用〈编码〉。编号是按顺序排上数字，把声音转换成代码要用编码。"}, {"text": "妈妈在灯下编号毛衣。", "explanation": "这里应该用〈编织〉。编号指排上数字，织毛衣要用编织。"}, {"text": "他从小就喜欢编号谎言。", "explanation": "这里应该用〈编造〉。编号指排上数字，虚构谎言要用编造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编号", "is_correct": true, "explanation": "编号：给每个座位排上号码，与“别坐错了”的语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：座位没有年龄，这个说法不成立，也与“别坐错了”无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：座位的重量与会不会坐错没有关系，语境不合。"}, {"text": "作者", "is_correct": false, "explanation": "语义：座位不会有作者，这个说法不成立，也与“别坐错了”无关。"}], "explanations": {"编号": "编号：给每个座位排上号码，与“别坐错了”的语境相合。", "年龄": "语义：座位没有年龄，这个说法不成立，也与“别坐错了”无关。", "重量": "语义：座位的重量与会不会坐错没有关系，语境不合。", "作者": "语义：座位不会有作者，这个说法不成立，也与“别坐错了”无关。"}, "sentence_index": 6, "correct_answer": "编号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给蛋糕编号了一圈花边。", "explanation": "这里应该用〈装饰〉。编号是排上数字，给蛋糕加花边要用装饰。"}, {"text": "他用绳子编号了一个中国结。", "explanation": "这里应该用〈编结〉。编号指排上数字，用绳子打结做装饰要用编结。"}, {"text": "他在窗边编号了一缕阳光。", "explanation": "这里应该用〈捕捉〉。编号指排上数字，阳光无法排号，抓住光线要用捕捉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子上有一只编号。", "corrected_sentence": "这个盒子上有一个编号。", "error_description": "错误：“一只编号”。“编号”作名词时用量词“个”，不用“只”：应为“一个编号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经给每个选手编号着。", "corrected_sentence": "老师已经给每个选手编号了。", "error_description": "错误：“编号着”。“已经”表示动作已完成，应用“了”：应为“编号了”，“着”表示动作持续，不能用于已完成的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
