INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城镇中供人车通行、两旁有房屋商店的道路上。", "primary_collocate": null, "pronunciation": "jiē shang", "ipa": "tɕje⁵⁵ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "街上两边都是商店，东西很多。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近的街上有一家很大的书店。", "target_word": "街上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的房子都很老。", "target_word": "街上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小城的街上有很多小商店和饭馆。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上的路灯晚上七点就开了。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在街上买了一杯热咖啡。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪下了一夜，街上的路很滑。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路两旁是房子，街上还有很多树。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老城的街上到处都是小吃店。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在街上的水果店买了苹果。", "target_word": "街上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "城镇里两旁有房屋商店的道路上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街上", "is_correct": true, "explanation": "「街上」指城镇里两旁有商店的道路，与「两边都是商店」吻合。"}, {"text": "草原上", "is_correct": false, "explanation": "语义：草原上没有两边都是商店的道路。"}, {"text": "海上", "is_correct": false, "explanation": "语义：海上不会有两边都是商店的道路。"}, {"text": "沙漠里", "is_correct": false, "explanation": "搭配：沙漠里很少有两边排列商店的道路，不与「东西很多」搭配。"}], "explanations": {"街上": "「街上」指城镇里两旁有商店的道路，与「两边都是商店」吻合。", "草原上": "语义：草原上没有两边都是商店的道路。", "海上": "语义：海上不会有两边都是商店的道路。", "沙漠里": "搭配：沙漠里很少有两边排列商店的道路，不与「东西很多」搭配。"}, "sentence_index": 0, "correct_answer": "街上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼的街上有很多小商店。", "explanation": "这里应该用〈楼里〉。「街上」指室外的城镇道路，大楼内部的商店不能用「街上」。"}, {"text": "这间体育馆的街上有很多饭馆。", "explanation": "这里应该用〈馆里〉。「街上」指室外道路，体育馆内的饭馆不能用「街上」。"}, {"text": "这间教室的街上有很多小饭馆。", "explanation": "这里应该用〈教室里〉。「街上」不能指室内空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街上", "is_correct": true, "explanation": "「街上」指道路上，与「雪下了一夜，路很滑」的情境吻合。"}, {"text": "房间里", "is_correct": false, "explanation": "语义：房间里不会因为下雪而路滑，与句意冲突。"}, {"text": "海上", "is_correct": false, "explanation": "语义：海上不存在供人走的路，与句意冲突。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：桌上没有「路」可言，与「很滑」不搭配。"}], "explanations": {"街上": "「街上」指道路上，与「雪下了一夜，路很滑」的情境吻合。", "房间里": "语义：房间里不会因为下雪而路滑，与句意冲突。", "海上": "语义：海上不存在供人走的路，与句意冲突。", "桌上": "搭配：桌上没有「路」可言，与「很滑」不搭配。"}, "sentence_index": 6, "correct_answer": "街上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在街上的仓库里清点货物。", "explanation": "这里应该用〈屋里〉。「街上」指室外的道路，仓库是室内场所，不能说在「街上」。"}, {"text": "书都放在街上的抽屉里。", "explanation": "这里应该用〈屋里〉。「街上」指室外的道路，抽屉是室内的家具，不能说在「街上」。"}, {"text": "街上的稻田里插满了秧苗。", "explanation": "这里应该用〈田间〉。「街上」指城镇中两旁有房屋商店的道路，稻田不在街上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上在很多卖花的小摊。", "corrected_sentence": "街上有很多卖花的小摊。", "error_description": "错误：表示存在要用「有」，不能用「在」。应为「街上有很多卖花的小摊」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
