INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这时是说话的这一小会儿，或者刚才说的那个时候。", "primary_collocate": null, "pronunciation": "zhè shí", "ipa": "ʈʂɤ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "我刚走到门口，这时电话响了。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，这时他才想起没带伞。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家正在吃饭，这时门开了。", "target_word": "这时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她打开信，这时眼泪流了下来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在看书，这时妈妈走了进来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车慢慢停下，这时下起了大雨。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛快结束了，这时他进了一个球。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到山顶，这时太阳正好出来。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师刚讲完课，这时下课铃响了。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，这时屋里很安静。", "target_word": "这时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "這時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "这时：刚说到的那个时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1d2176-a13c-4769-a424-d290b8720390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这时", "is_correct": true, "explanation": "正确：这时指刚说到的那个时刻，即刚走到门口的这一刻，与电话响起的时间相接。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜指深夜的一段时间，与“刚走到门口”的那一刻对不上，句意不通。"}, {"text": "明天", "is_correct": false, "explanation": "语义：明天指将来，与“刚走到门口”这一已经发生的情况冲突。"}, {"text": "平时", "is_correct": false, "explanation": "体貌：平时表示惯常的时段，与“电话响了”这种一次性的事件不相符。"}], "explanations": {"这时": "正确：这时指刚说到的那个时刻，即刚走到门口的这一刻，与电话响起的时间相接。", "半夜": "语义：半夜指深夜的一段时间，与“刚走到门口”的那一刻对不上，句意不通。", "明天": "语义：明天指将来，与“刚走到门口”这一已经发生的情况冲突。", "平时": "体貌：平时表示惯常的时段，与“电话响了”这种一次性的事件不相符。"}, "sentence_index": 0, "correct_answer": "这时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这时我上小学的时候，全家搬到了北京。", "explanation": "这里应该用〈那时〉。这时只指说话当下或上文提到的时刻，不能指“上小学的时候”这样已过去的时段。"}, {"text": "这时我们昨天就到了北京。", "explanation": "这里应该用〈那天〉。这时指说话当下或上文的时刻，不能与“昨天”这样的具体日期并用。"}, {"text": "这时我三岁的时候，还不会说话。", "explanation": "这里应该用〈当时〉。这时只指说话当下或上文的时刻，不能指“三岁的时候”这样已过去的时段；回指过去的某一时刻要用当时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这时", "is_correct": true, "explanation": "正确：这时指刚说到的那个时刻，即比赛快结束时他进球的这一刻。"}, {"text": "开场时", "is_correct": false, "explanation": "语义：开场时指比赛刚开始的阶段，与“快结束了”的时间背景相反。"}, {"text": "赛前", "is_correct": false, "explanation": "语义：赛前指比赛开始以前，与“快结束了”矛盾，且进球不可能发生在赛前。"}, {"text": "中场休息时", "is_correct": false, "explanation": "语义：中场休息时是比赛过半的时候，与“快结束了”的时间背景矛盾。"}], "explanations": {"这时": "正确：这时指刚说到的那个时刻，即比赛快结束时他进球的这一刻。", "开场时": "语义：开场时指比赛刚开始的阶段，与“快结束了”的时间背景相反。", "赛前": "语义：赛前指比赛开始以前，与“快结束了”矛盾，且进球不可能发生在赛前。", "中场休息时": "语义：中场休息时是比赛过半的时候，与“快结束了”的时间背景矛盾。"}, "sentence_index": 6, "correct_answer": "这时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这时我上个月搬了家。", "explanation": "这里应该去掉〈这时〉，直接说“我上个月搬了家”。这时指说话当下或上文的时刻，不能与“上个月”这样的具体过去时段并用。"}, {"text": "这时昨天下了雨。", "explanation": "这里应该用〈那天〉。这时只指说话当下或上文的时刻，不能与“昨天”这样的具体日期并用。"}, {"text": "我这时每天都早起跑步。", "explanation": "这里应该用〈平时〉。这时指一个具体时刻，与表示惯常的“每天”矛盾；说惯常要用平时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚进屋，这时了手机响了。", "corrected_sentence": "我刚进屋，这时手机响了。", "error_description": "错误：“这时”是时间名词，后面不能直接加“了”。去掉“了”即正确：“这时手机响了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我刚坐下，这时的有人敲门了。", "corrected_sentence": "我刚坐下，这时有人敲门了。", "error_description": "错误：“的”不能加在“这时”后面、直接接“有人”。去掉“的”即正确：“这时有人敲门了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇见是走路时，没想到看到了一个人。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我走路回家时遇见了张阿姨。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在街上走着，遇见了小学同学。", "target_word": "遇见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买菜，在路上遇见邻居。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天走在路上，我遇见了老师。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她散步时遇见了一个好久不见的朋友。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下楼的时候，我遇见了房东。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没想到会在街上遇见你。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟走去学校，半路遇见了同桌。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天下班走路回家，我遇见了经理。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天走这条路，从没遇见过熟人。", "target_word": "遇见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇见了", "label": "体标"}, {"form": "遇见过", "label": "体标"}], "register": "中性", "sense_fingerprint": "走路时没想到看到了一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遇见", "is_correct": true, "explanation": "遇见：走路时没想到碰到或看到某人。"}, {"text": "愚见", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。"}, {"text": "预交", "is_correct": false, "explanation": "yù jiāo 与 yù jiàn 第二音节的韵母和声调不同，意思是事先交付（费用）。"}, {"text": "预检", "is_correct": false, "explanation": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}], "explanations": {"遇见": "遇见：走路时没想到碰到或看到某人。", "愚见": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。", "预交": "yù jiāo 与 yù jiàn 第二音节的韵母和声调不同，意思是事先交付（费用）。", "预检": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}, "sentence_index": null, "correct_answer": "遇见"}, "level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示走路时没想到碰到人，与“我走路回家时”相符。"}, {"text": "报告", "is_correct": false, "explanation": "配价：“报告”的宾语是情况或信息，不能直接带“张阿姨”这样的人作宾语。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”需要主人与客人的关系，走路回家时偶然碰到不能用“招待”。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走，与路上碰到张阿姨的情景完全不符。"}], "explanations": {"遇见": "正确：“遇见”表示走路时没想到碰到人，与“我走路回家时”相符。", "报告": "配价：“报告”的宾语是情况或信息，不能直接带“张阿姨”这样的人作宾语。", "招待": "搭配：“招待”需要主人与客人的关系，走路回家时偶然碰到不能用“招待”。", "驱赶": "语义：“驱赶”指赶走，与路上碰到张阿姨的情景完全不符。"}, "sentence_index": 0, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前一周跟他约好，要在地铁站遇见他。", "explanation": "这里应该用〈约见〉。遇见指没有事先约定而碰到，已经约好时间的见面要用约见。"}, {"text": "我特意去养老院遇见爷爷。", "explanation": "这里应该用〈看望〉。遇见是偶然碰到，“特意去”说明是有目的的探访，要用看望。"}, {"text": "我们早就约好在机场遇见远道来的客人。", "explanation": "这里应该用〈迎接〉。遇见不能用于有计划地去接人，约好的接机要用迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示没想到而碰到，与“没想到会在街上”相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”指热情接待来访的人，与在街上偶然碰到的情景不符。"}, {"text": "看望", "is_correct": false, "explanation": "语义：“看望”是有意去探访，与“没想到”的偶然性矛盾。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指丢下不管，与街上偶然碰到你的情景完全不同。"}], "explanations": {"遇见": "正确：“遇见”表示没想到而碰到，与“没想到会在街上”相符。", "欢迎": "语义：“欢迎”指热情接待来访的人，与在街上偶然碰到的情景不符。", "看望": "语义：“看望”是有意去探访，与“没想到”的偶然性矛盾。", "抛弃": "语义：“抛弃”指丢下不管，与街上偶然碰到你的情景完全不同。"}, "sentence_index": 6, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们走了三小时，遇见了山顶。", "explanation": "这里应该用〈到达〉。遇见是偶然碰到人或物，爬到山顶这样的地点要用到达。"}, {"text": "周末我专门去王老师家遇见他。", "explanation": "这里应该用〈请教〉。“专门去”说明是有目的的求教，遇见是偶然碰到，要用请教。"}, {"text": "总统明天遇见代表团，日程已经排好了。", "explanation": "这里应该用〈会见〉。遇见是偶然碰到，日程已排好的正式会面要用会见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我走出小区时，正在遇见了一位老同学。", "corrected_sentence": "我走出小区时，遇见了一位老同学。", "error_description": "错误：“正在”表示动作进行中，与瞬间完成的“遇见”加完成态“了”相矛盾。应删去“正在”，说“我走出小区时，遇见了一位老同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候走这条路，遇见着一位老邻居。", "corrected_sentence": "我小时候走这条路，遇见过一位老邻居。", "error_description": "错误：“遇见”是瞬间动作，不能带持续态“着”。表示曾经有过的经历应用“过”，应改为“遇见过一位老邻居”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
