INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有事先约定而碰到、见到某人或某物。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天在超市遇见了老同学。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在路上，他遇见一位老朋友。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在国外遇见过中国人吗？", "target_word": "遇见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会在这儿遇见你。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在大学里遇见了她的丈夫。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我们遇见了一只小狗。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上班路上遇见了王老师，就打了招呼。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在机场遇见了一个很有名的歌手。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末去公园，我遇见了好多邻居。", "target_word": "遇见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在火车上遇见了一位老医生。", "target_word": "遇见", "complexity_tier": "T3", "furigana": "wǒ zài huǒchē shàng yùjiàn le yí wèi lǎo yīshēng", "sentence_source": "generated"}], "morphological_forms": [{"form": "遇见了", "label": "体标"}, {"form": "遇见过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事先没有约定而碰到、见到某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7eda32-eefc-46de-9706-5443cde9dd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遇见", "is_correct": true, "explanation": "遇见：没有事先约定而碰到某人或某物。"}, {"text": "愚见", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。"}, {"text": "预交", "is_correct": false, "explanation": "yù jiāo 与 yù jiàn 第二音节的韵母和声调不同，意思是事先交付（费用）。"}, {"text": "预检", "is_correct": false, "explanation": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}], "explanations": {"遇见": "遇见：没有事先约定而碰到某人或某物。", "愚见": "yú（第二声）与 yù（第四声）声调不同，意思是谦称自己的见解，与“遇见”不同。", "预交": "yù jiāo 与 yù jiàn 第二音节的韵母和声调不同，意思是事先交付（费用）。", "预检": "yù jiǎn 与 yù jiàn 第二音节声调不同（第三声），意思是事先检查。"}, "sentence_index": null, "correct_answer": "遇见"}, "level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示偶然碰到，与在超市里偶然碰到老同学相符。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：“摆放”的对象是物品，不能用于人，与“老同学”不合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于展馆、场所，不能带“老同学”这样的人作宾语。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能说“买老同学”。"}], "explanations": {"遇见": "正确：“遇见”表示偶然碰到，与在超市里偶然碰到老同学相符。", "摆放": "搭配：“摆放”的对象是物品，不能用于人，与“老同学”不合。", "参观": "搭配：“参观”用于展馆、场所，不能带“老同学”这样的人作宾语。", "买": "搭配：“买”的宾语是商品，不能说“买老同学”。"}, "sentence_index": 0, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前三天和他约好，要在火车站遇见他。", "explanation": "这里应该用〈约见〉。遇见指没有事先约定而碰到，已经约好时间的见面要用约见。"}, {"text": "我特意去医院遇见奶奶。", "explanation": "这里应该用〈看望〉。遇见是偶然碰到，“特意去”说明是有目的的探访，要用看望。"}, {"text": "我们早就约好在车站遇见远方的朋友。", "explanation": "这里应该用〈迎接〉。遇见不能用于有计划地去接人，约好的接站要用迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遇见", "is_correct": true, "explanation": "正确：“遇见”表示偶然碰到，与路上碰到王老师并打招呼相符。"}, {"text": "请教", "is_correct": false, "explanation": "语义：“请教”指有目的地向人求教，与路上偶然碰到的情景不符。"}, {"text": "想起", "is_correct": false, "explanation": "语义：“想起”是心里想到，不是当面见到，与后面“就打了招呼”矛盾。"}, {"text": "报告", "is_correct": false, "explanation": "配价：“报告”的宾语是情况或信息，不能直接带“王老师”这样的人作宾语。"}], "explanations": {"遇见": "正确：“遇见”表示偶然碰到，与路上碰到王老师并打招呼相符。", "请教": "语义：“请教”指有目的地向人求教，与路上偶然碰到的情景不符。", "想起": "语义：“想起”是心里想到，不是当面见到，与后面“就打了招呼”矛盾。", "报告": "配价：“报告”的宾语是情况或信息，不能直接带“王老师”这样的人作宾语。"}, "sentence_index": 6, "correct_answer": "遇见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外长按日程安排，将在大使馆遇见外国代表。", "explanation": "这里应该用〈会见〉。遇见是偶然碰到，按日程安排的正式见面要用会见。"}, {"text": "他按约定遇见了王教授。", "explanation": "这里应该用〈拜访〉。遇见不能用于按约定进行的造访，约好登门见面要用拜访。"}, {"text": "学生下课后专门去办公室遇见老师。", "explanation": "这里应该用〈请教〉。“专门去办公室”说明是有目的的求教，遇见是偶然碰到，要用请教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天会在路上遇见了老师。", "corrected_sentence": "我明天会在路上遇见老师。", "error_description": "错误：“遇见”后面多了“了”。“会”表示将来，将来的动作不能加“了”，应改为“会在路上遇见老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在路上遇见到了王老师。", "corrected_sentence": "我在路上遇见了王老师。", "error_description": "错误：“遇见”后面多了补语“到”。“遇见”本身已表示碰到，不能再加“到”组成“遇见到”，应改为“遇见了王老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f87650-6ffb-429e-b0d8-cdb0c3b1b179') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
