INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来不愿说或没说出的话说出来。", "primary_collocate": null, "pronunciation": "dào chū", "ipa": "tɑʊ̯⁵¹ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他终于道出了心里的秘密。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哭着道出了这些年的辛苦。", "target_word": "道出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问了很久，他才道出真相。", "target_word": "道出", "complexity_tier": "T3", "furigana": "jǐng chá wèn le hěn jiǔ, tā cái dào chū zhēn xiàng", "sentence_source": "generated"}, {"text": "他沉默了许久，终于道出了当年隐瞒的那件事。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友一直没说，今天才道出原因。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人慢慢道出了多年前的往事。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不敢道出自己真正的想法。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在大家的鼓励下，她道出了真相。", "target_word": "道出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子低着头，道出了自己的错误。", "target_word": "道出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把藏了很久的心里话全部道出。", "target_word": "道出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道出了", "label": "体标"}, {"form": "道出过", "label": "体标"}], "register": "书面", "sense_fingerprint": "终于说出原来不愿说或没说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：道出，意思是把原来不愿说的话说出来。"}, {"text": "导出", "is_correct": false, "explanation": "导出的第一个音节为第三声，与道出的第四声不同，意思是把数据或文件输出。"}, {"text": "到处", "is_correct": false, "explanation": "到处的第二个音节为第四声，与道出的第一声不同，意思是各个地方。"}, {"text": "套出", "is_correct": false, "explanation": "套出的声母是 t，与道出的 d 不同，意思是用计谋让人说出实情。"}], "explanations": {"道出": "正确：道出，意思是把原来不愿说的话说出来。", "导出": "导出的第一个音节为第三声，与道出的第四声不同，意思是把数据或文件输出。", "到处": "到处的第二个音节为第四声，与道出的第一声不同，意思是各个地方。", "套出": "套出的声母是 t，与道出的 d 不同，意思是用计谋让人说出实情。"}, "sentence_index": null, "correct_answer": "道出"}, "level_3": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：“道出”表示把原来不愿说的心里秘密说出来，与“终于”的语境相合。"}, {"text": "掏出", "is_correct": false, "explanation": "搭配：“掏出”指从口袋或容器里拿出实物，秘密不能被掏出。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指正式公开言论或作品，与秘密不愿说的语境相反。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：“讲解”是解释说明知识或道理，不能用于心里的秘密。"}], "explanations": {"道出": "正确：“道出”表示把原来不愿说的心里秘密说出来，与“终于”的语境相合。", "掏出": "搭配：“掏出”指从口袋或容器里拿出实物，秘密不能被掏出。", "发表": "语义：“发表”指正式公开言论或作品，与秘密不愿说的语境相反。", "讲解": "语义：“讲解”是解释说明知识或道理，不能用于心里的秘密。"}, "sentence_index": 0, "correct_answer": "道出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府昨天道出了新的规定。", "explanation": "这里应该用〈宣布〉。道出指把原来不愿说或难以启齿的话说出来，正式发布规定应用宣布。"}, {"text": "他每天早上都道出一句“早安”。", "explanation": "这里应该用〈说〉。道出表示吐露原来不愿说的心里话，早上的问候只是随口说，不用道出。"}, {"text": "他从口袋里道出了一颗糖。", "explanation": "这里应该用〈掏出〉。道出只用于把话语或想法说出来，从口袋里拿出实物要用掏出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道出", "is_correct": true, "explanation": "正确：“道出”表示把不敢说的想法说出口，与“不敢”的语境相合。"}, {"text": "摔碎", "is_correct": false, "explanation": "搭配：“摔碎”指把物体摔成碎片，想法不能被摔碎。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物体的外表，与表达想法无关。"}, {"text": "叠起", "is_correct": false, "explanation": "搭配：“叠起”指把纸张或衣物折叠，不能用于想法。"}], "explanations": {"道出": "正确：“道出”表示把不敢说的想法说出口，与“不敢”的语境相合。", "摔碎": "搭配：“摔碎”指把物体摔成碎片，想法不能被摔碎。", "装饰": "语义：“装饰”指美化物体的外表，与表达想法无关。", "叠起": "搭配：“叠起”指把纸张或衣物折叠，不能用于想法。"}, "sentence_index": 6, "correct_answer": "道出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里道出了一锅汤。", "explanation": "这里应该用〈端〉。道出只用于说出话语或想法，端一锅汤这类实物要用端。"}, {"text": "他一进门就道出了一阵大笑。", "explanation": "这里应该用〈发出〉。道出只用于说出话语或想法，笑声这类非语言的声音要用发出。"}, {"text": "妈妈每次出门前都道出一句“再见”。", "explanation": "这里应该用〈说〉。道出表示吐露原来不愿说或没说的话，出门时的例行道别只是随口说，不用道出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于道出着压在心里很久的话。", "corrected_sentence": "他终于道出了压在心里很久的话。", "error_description": "错误：“道出着”。正确：“道出了”。“道出”表示把话说出口这一完成的动作，要用“了”；“着”表示持续状态，与“终于”的完成语境不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于道出着压抑多年的委屈。", "corrected_sentence": "她终于道出了压抑多年的委屈。", "error_description": "错误：“道出着”。正确：“道出了”。“道出”表示把话说出口这一完成的动作，要用“了”；“着”表示持续状态，与“终于”的完成语境不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
