INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供应酒类饮料，供人饮酒、休闲的场所。", "primary_collocate": null, "pronunciation": "jiǔ bā", "ipa": "tɕi̯ou̯˨˩ pa˥", "syllable_count": 2, "sentences": [{"text": "这家酒吧卖各种啤酒和红酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约在街角的酒吧见面。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧晚上营业到凌晨两点。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一家酒吧里当服务员。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里灯光很暗，大家边喝酒边聊天。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喝酒，所以很少去酒吧。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个酒吧有现场音乐，客人很多。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们走进旁边的酒吧躲雨。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那间酒吧装修得很有特色。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧老板正在给客人倒酒。", "target_word": "酒吧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "间", "label": "量词"}], "register": "中性", "sense_fingerprint": "酒吧|名词|供应酒类饮料供人休闲的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」供应酒类饮料，符合「卖各种啤酒和红酒」的说法。"}, {"text": "书店", "is_correct": false, "explanation": "语义：「书店」卖的是书，不卖啤酒和红酒。"}, {"text": "花店", "is_correct": false, "explanation": "搭配：「花店」卖的是花，与「卖啤酒和红酒」不搭配。"}, {"text": "药店", "is_correct": false, "explanation": "语义：「药店」卖的是药品，不卖啤酒和红酒。"}], "explanations": {"酒吧": "正确：「酒吧」供应酒类饮料，符合「卖各种啤酒和红酒」的说法。", "书店": "语义：「书店」卖的是书，不卖啤酒和红酒。", "花店": "搭配：「花店」卖的是花，与「卖啤酒和红酒」不搭配。", "药店": "语义：「药店」卖的是药品，不卖啤酒和红酒。"}, "sentence_index": 0, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家酒吧每天生产一万瓶白酒。", "explanation": "这里应该用〈酒厂〉。「酒吧」是供应酒类饮料、供人饮酒休闲的场所，不生产酒。"}, {"text": "这家酒吧有一百间客房，每天都住满人。", "explanation": "这里应该用〈酒店〉。「酒吧」供应饮料、供人饮酒休闲，不提供客房住宿，这里误用了它。"}, {"text": "这家酒吧的电脑很多，学生们都来这里上网。", "explanation": "这里应该用〈网吧〉。「酒吧」是供人饮酒休闲的场所，不是上网的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酒吧", "is_correct": true, "explanation": "正确：「酒吧」供人饮酒休闲，符合「有现场音乐，客人很多」的描述。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：「工厂」是生产产品的地方，不以现场音乐和接待客人为特点。"}, {"text": "医院", "is_correct": false, "explanation": "语义：「医院」是看病治病的地方，不适合有现场音乐和很多客人。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：「仓库」是存放货物的地方，与「有现场音乐，客人很多」不搭配。"}], "explanations": {"酒吧": "正确：「酒吧」供人饮酒休闲，符合「有现场音乐，客人很多」的描述。", "工厂": "语义：「工厂」是生产产品的地方，不以现场音乐和接待客人为特点。", "医院": "语义：「医院」是看病治病的地方，不适合有现场音乐和很多客人。", "仓库": "搭配：「仓库」是存放货物的地方，与「有现场音乐，客人很多」不搭配。"}, "sentence_index": 6, "correct_answer": "酒吧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天去了一本酒吧，里面很热闹。", "explanation": "量词错误。「本」用于书籍，「酒吧」应该用量词「家」。"}, {"text": "我们昨晚在一张酒吧里聚会，很开心。", "explanation": "量词错误。「张」用于平面的东西，「酒吧」应该用量词「家」。"}, {"text": "那支酒吧的装修很有特色。", "explanation": "量词错误。「支」用于笔、队伍等，「酒吧」应该用量词「家」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们常去一只安静的酒吧聊天。", "corrected_sentence": "周末我们常去一家安静的酒吧聊天。", "error_description": "错误：「酒吧」前应用量词「家」，这里误用了「只」。「只」用于动物或某些小物件，正确的是「一家安静的酒吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家酒吧地装修很有特色。", "corrected_sentence": "那家酒吧的装修很有特色。", "error_description": "错误：名词「装修」前的修饰语「酒吧」应用「的」连接，这里误用了「地」。「地」用于修饰动词或形容词，正确的是「酒吧的装修」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
