INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "震惊是遇到没想到的事，吓了一大跳。", "primary_collocate": null, "pronunciation": "zhèn jīng", "ipa": "ʈʂən˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "听到这个消息，我非常震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然出现在门口，大家都很震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到成绩单，她震惊得说不出话。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没想到他会哭，心里很震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开门，看见满屋子的水，一下子震惊了。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的变化，让朋友们十分震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他要辞职，同事们都感到震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜里一声巨响，邻居们都震惊了。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着空空的房间，震惊地站在那里。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己不是中国人，我们都很震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "遇到完全没想到的事，吓了一大跳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：震惊，指遇到没想到的事而吓了一大跳。"}, {"text": "镇静", "is_correct": false, "explanation": "zhèn jìng（第四声）与 zhèn jīng（第一声）只有第二音节声调不同，意思是冷静、不慌乱。"}, {"text": "正经", "is_correct": false, "explanation": "zhèng jīng 与 zhèn jīng 第一音节韵母不同（-ng 与 -n），意思是端正、严肃。"}, {"text": "振兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是使事业重新兴旺起来。"}], "explanations": {"震惊": "正确：震惊，指遇到没想到的事而吓了一大跳。", "镇静": "zhèn jìng（第四声）与 zhèn jīng（第一声）只有第二音节声调不同，意思是冷静、不慌乱。", "正经": "zhèng jīng 与 zhèn jīng 第一音节韵母不同（-ng 与 -n），意思是端正、严肃。", "振兴": "xīng 与 jīng 声母不同（x 与 j），意思是使事业重新兴旺起来。"}, "sentence_index": null, "correct_answer": "震惊"}, "level_3": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：“非常震惊”表示听到消息后非常吃惊，与句中的“听到这个消息”相符。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”形容外表好看，不能用来表示对消息的反应。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格或东西，不能用来形容人的心情。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说人的才智，与听到消息后的反应对不上。"}], "explanations": {"震惊": "正确：“非常震惊”表示听到消息后非常吃惊，与句中的“听到这个消息”相符。", "美丽": "体貌：“美丽”形容外表好看，不能用来表示对消息的反应。", "便宜": "搭配：“便宜”说价格或东西，不能用来形容人的心情。", "聪明": "语义：“聪明”说人的才智，与听到消息后的反应对不上。"}, "sentence_index": 0, "correct_answer": "震惊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震的时候，整栋楼都在剧烈震惊。", "explanation": "这里应该用〈震动〉。震动指物体因外力而摇晃，震惊只表示人心里吃惊，不能用来形容房子晃动。"}, {"text": "我今天早上吃了一碗面，觉得非常震惊。", "explanation": "这里应该用〈惊讶〉。惊讶只表示一般的意外，吃早饭这样平常的事最多只能说惊讶，“震惊”表示大吃一惊，程度太重。"}, {"text": "我早就知道这个结果，看到成绩单时却震惊了。", "explanation": "这里应该用〈平静〉。“震惊”表示没想到而大吃一惊；早就知道的结果不会让人吃惊，“却震惊了”自相矛盾，应说“平静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：“感到震惊”表示听说同事要辞职后非常吃惊，与句中的情境相符。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要吃东西，与听说同事辞职的消息无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能用来形容心理感受。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用在“感到”后面表示心理反应。"}], "explanations": {"震惊": "正确：“感到震惊”表示听说同事要辞职后非常吃惊，与句中的情境相符。", "饿": "语义：“饿”指身体需要吃东西，与听说同事辞职的消息无关。", "高大": "体貌：“高大”形容身材或外形，不能用来形容心理感受。", "明亮": "搭配：“明亮”形容光线或颜色，不能用在“感到”后面表示心理反应。"}, "sentence_index": 6, "correct_answer": "震惊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个温暖的故事让我很震惊，我哭了很久。", "explanation": "这里应该用〈感动〉。感动表示心里被打动；震惊表示吃惊，这个故事并不是出乎意料的事。"}, {"text": "他深夜独自走在路上，对黑暗感到震惊。", "explanation": "这里应该用〈恐惧〉。震惊指遇到意外的事而吃惊，不用于表示对黑暗的长期害怕，这里的意思应说“恐惧”。"}, {"text": "今天天气很好，我在公园里散步，心里很震惊。", "explanation": "这里应该用〈平静〉。震惊指遇到意外而大吃一惊，与散步时安闲的心情不符，这里应说“平静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个决定震惊了。", "corrected_sentence": "他被这个决定震惊了。", "error_description": "介词用错。“震惊”的感受者“他”要用“被”引出施事，应说“他被这个决定震惊了”，把“被”换成“把”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个决定被他震惊了。", "corrected_sentence": "这个决定让他震惊了。", "error_description": "“被”字句用错。“这个决定被他震惊了”把“这个决定”放在受事位置，让“他”成了施事，主客颠倒。应把“被”改为“让”，说“这个决定让他震惊了”，由“决定”引起“他”的震惊。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
