INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因意外的事情而感到非常吃惊。", "primary_collocate": null, "pronunciation": "zhèn jīng", "ipa": "ʈʂən˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "得知公司突然关门，员工们非常震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个意外的结果，让所有人都感到震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成功让家人又高兴又震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他竟然考了第一名，同学们都很震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到新闻里的事故，我心里十分震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她突然说要结婚，朋友们都震惊了。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到老人去世的消息，大家都很震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他震惊地问：“你说什么？”", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对意外的坏消息，他震惊得一句话也说不出。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多钱不见了，经理非常震惊。", "target_word": "震惊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因意外的事情而感到非常吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：震惊，指因意外的事情而感到非常吃惊。"}, {"text": "镇静", "is_correct": false, "explanation": "zhèn jìng（第四声）与 zhèn jīng（第一声）只有第二音节声调不同，意思是冷静、不慌乱。"}, {"text": "正经", "is_correct": false, "explanation": "zhèng jīng 与 zhèn jīng 第一音节韵母不同（-ng 与 -n），意思是端正、严肃。"}, {"text": "振兴", "is_correct": false, "explanation": "xīng 与 jīng 声母不同（x 与 j），意思是使事业重新兴旺起来。"}], "explanations": {"震惊": "正确：震惊，指因意外的事情而感到非常吃惊。", "镇静": "zhèn jìng（第四声）与 zhèn jīng（第一声）只有第二音节声调不同，意思是冷静、不慌乱。", "正经": "zhèng jīng 与 zhèn jīng 第一音节韵母不同（-ng 与 -n），意思是端正、严肃。", "振兴": "xīng 与 jīng 声母不同（x 与 j），意思是使事业重新兴旺起来。"}, "sentence_index": null, "correct_answer": "震惊"}, "level_3": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：“非常震惊”表示听到公司关门的消息后非常吃惊，与句中的情境相符。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”形容外表好看，不能用来表示对坏消息的反应。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格或东西，不能用来形容人的心情。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说人的才智，与公司突然关门的情境对不上。"}], "explanations": {"震惊": "正确：“非常震惊”表示听到公司关门的消息后非常吃惊，与句中的情境相符。", "美丽": "体貌：“美丽”形容外表好看，不能用来表示对坏消息的反应。", "便宜": "搭配：“便宜”说价格或东西，不能用来形容人的心情。", "聪明": "语义：“聪明”说人的才智，与公司突然关门的情境对不上。"}, "sentence_index": 0, "correct_answer": "震惊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们为他的平安到达感到非常震惊。", "explanation": "这里应该用〈欣慰〉。震惊指意外而吃惊，平安到达是预期中的好事，应表示欣慰，不能用“震惊”。"}, {"text": "我今天刷牙的时候，觉得很震惊。", "explanation": "这里应该用〈平静〉。刷牙是平常的事，心情应是平静的；震惊指遇到意外而大吃一惊，程度不符。"}, {"text": "一阵风吹过，门窗都震惊起来了。", "explanation": "这里应该用〈震动〉。震动指物体因外力而晃动，震惊只指心理上的吃惊，不能用来形容门窗晃动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "震惊", "is_correct": true, "explanation": "正确：“大家都很震惊”表示听到老人去世的消息后非常吃惊，与句中的情境相符。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要食物，与听到老人去世的消息没有关系。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能用来形容心理感受。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容大家的心理状态。"}], "explanations": {"震惊": "正确：“大家都很震惊”表示听到老人去世的消息后非常吃惊，与句中的情境相符。", "饿": "语义：“饿”指身体需要食物，与听到老人去世的消息没有关系。", "高大": "体貌：“高大”形容身材或外形，不能用来形容心理感受。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容大家的心理状态。"}, "sentence_index": 6, "correct_answer": "震惊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么多钱不见了，经理把它震惊了。", "explanation": "这里应该用〈心疼〉。震惊的承受者必须是有感受的人；“它”指钱，钱不能被震惊，这里应表达经理的心疼之类的感受。"}, {"text": "我今天只丢了一支笔，经理也非常震惊。", "explanation": "这里应该用〈惊讶〉。丢一支笔只需表示一般的意外，用“震惊”程度太重，“惊讶”才合适。"}, {"text": "经理为这笔钱震惊地笑了。", "explanation": "这里应该用〈惊喜〉。笑多表示高兴，要用“惊喜”；“震惊”是吃惊，搭配“笑”不协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她看了那张通知，震惊说不出话。", "corrected_sentence": "她看了那张通知，震惊得说不出话。", "error_description": "漏了“得”。“震惊”后面引出结果补语“说不出话”时要用“震惊得……”，漏掉“得”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把这个数字震惊了。", "corrected_sentence": "经理被这个数字震惊了。", "error_description": "介词用错。“震惊”的感受者“经理”要用“被”引出施事，应说“经理被这个数字震惊了”，把“被”换成“把”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
