INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "巩固是让东西变得更结实，不容易坏。", "primary_collocate": null, "pronunciation": "gǒng gù", "ipa": "kʊŋ˨˩˦ ku˥˩", "syllable_count": 2, "sentences": [{"text": "工人正在巩固这座桥。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们要巩固堤坝。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些石头能巩固房子的地基。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨以前，村民巩固了河边的土墙。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要巩固这道墙，得多加几根柱子。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用木板巩固了旧门。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让桥更结实，工人巩固了桥墩。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，政府巩固了很多旧房子。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把窗户用铁条巩固了一下。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用水泥巩固着塔的底部。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巩固了", "label": "体标"}, {"form": "巩固过", "label": "体标"}, {"form": "巩固着", "label": "体标"}, {"form": "巩固巩固", "label": "重叠"}], "register": "中性", "sense_fingerprint": "让东西更结实不易坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使桥更结实，“正在巩固这座桥”符合句意。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览指参观景点，工人在桥上工作不是去游览，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于桥。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于桥。"}], "explanations": {"巩固": "巩固：使桥更结实，“正在巩固这座桥”符合句意。", "游览": "语义：游览指参观景点，工人在桥上工作不是去游览，句子说不通。", "吃": "搭配：“吃”的对象是食物，不能用于桥。", "唱": "搭配：“唱”的对象是歌曲，不能用于桥。"}, "sentence_index": 0, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次施工巩固了大楼的高度。", "explanation": "这里应该用〈增加〉。巩固是使东西更结实，不表示高度增加，要用“增加”。"}, {"text": "我们用彩灯巩固了整个大厅。", "explanation": "这里应该用〈装饰〉。巩固是使东西更结实，用彩灯美化大厅要用“装饰”。"}, {"text": "地震巩固了几座旧房子。", "explanation": "这里应该用〈摧毁〉。巩固是使东西更结实，地震使房屋倒塌要用“摧毁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使桥墩更结实，“为了让桥更结实”表明目的，符合句意。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“为了让桥更结实”却“破坏”桥墩，前后矛盾，句子说不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰是美化，不能使桥墩更结实，与“为了让桥更结实”不符。"}, {"text": "锯", "is_correct": false, "explanation": "搭配：“锯”多用于木材等，不能用于桥墩。"}], "explanations": {"巩固": "巩固：使桥墩更结实，“为了让桥更结实”表明目的，符合句意。", "破坏": "语义：“为了让桥更结实”却“破坏”桥墩，前后矛盾，句子说不通。", "装饰": "语义：装饰是美化，不能使桥墩更结实，与“为了让桥更结实”不符。", "锯": "搭配：“锯”多用于木材等，不能用于桥墩。"}, "sentence_index": 6, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革让大楼的重量巩固了一半。", "explanation": "这里应该用〈减少〉。巩固表示使稳固，不表示重量减少一半，要用“减少”。"}, {"text": "台风巩固了村里的电线。", "explanation": "这里应该用〈破坏〉。巩固是使东西更结实，台风使电线受损要用“破坏”。"}, {"text": "这块膏药能巩固腰痛。", "explanation": "这里应该用〈减轻〉。巩固是使东西更结实，缓解腰痛要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把桥巩固很结实。", "corrected_sentence": "工人把桥巩固得很结实。", "error_description": "补语错误：“巩固”后接程度补语“很结实”时需要用“得”连接，应说“巩固得很结实”，不能直接说“巩固很结实”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天都巩固过堤坝。", "corrected_sentence": "我们每天都巩固堤坝。", "error_description": "时态助词错误：“过”表示曾经有过的经历，与“每天都”表示的习惯相矛盾，应说“我们每天都巩固堤坝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物、友谊或关系更加稳固、坚实；也指反复练习使学到的知识牢固。", "primary_collocate": null, "pronunciation": "gǒng gù", "ipa": "kʊŋ˨˩˦ ku˥˩", "syllable_count": 2, "sentences": [{"text": "我们要巩固新学的词。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每天复习可以巩固知识。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做能巩固友谊。", "target_word": "巩固", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天晚上都巩固当天学的内容。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国的合作巩固了双方的关系。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完练习以后，我想巩固一下语法。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了巩固成绩，她没有放松学习。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这堵墙需要巩固，不然会倒。", "target_word": "巩固", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把学过的汉字又巩固了一遍。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用钢筋巩固着河边的堤坝。", "target_word": "巩固", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巩固了", "label": "体标"}, {"form": "巩固过", "label": "体标"}, {"form": "巩固着", "label": "体标"}, {"form": "巩固巩固", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使事物、关系或所学知识更稳固", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使学到的知识更牢固，“巩固新学的词”即让新词记得更牢，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "语义：修建指建造房屋或设施，“词”不能被修建，句子说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”多用于房间、地面等场所，不能用于“词”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”的对象是植物或作物，“词”不能被种植，句子说不通。"}], "explanations": {"巩固": "巩固：使学到的知识更牢固，“巩固新学的词”即让新词记得更牢，符合句意。", "修建": "语义：修建指建造房屋或设施，“词”不能被修建，句子说不通。", "打扫": "搭配：“打扫”多用于房间、地面等场所，不能用于“词”。", "种植": "语义：“种植”的对象是植物或作物，“词”不能被种植，句子说不通。"}, "sentence_index": 0, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次跑步时，心跳巩固了很多。", "explanation": "这里应该用〈加快〉。巩固表示使稳固，不表示心跳加快，“心跳加快了很多”才符合句意。"}, {"text": "他每天晚上都巩固第二天要学的内容。", "explanation": "这里应该用〈预习〉。巩固是把学过的内容变牢固，第二天要学的内容还没学过，应该用“预习”。"}, {"text": "他的体重巩固了五公斤。", "explanation": "这里应该用〈增加〉。巩固不表示数量增加，体重增加了要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巩固", "is_correct": true, "explanation": "巩固：使成绩稳定、不下滑，“为了巩固成绩”表示目的，符合句意。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“为了破坏成绩”与后文“没有放松学习”的目的相矛盾，句子说不通。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多用于金钱、时间，不搭配“成绩”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“为了忘记成绩”与“没有放松学习”的目的相矛盾，句子说不通。"}], "explanations": {"巩固": "巩固：使成绩稳定、不下滑，“为了巩固成绩”表示目的，符合句意。", "破坏": "语义：“为了破坏成绩”与后文“没有放松学习”的目的相矛盾，句子说不通。", "挥霍": "搭配：“挥霍”多用于金钱、时间，不搭配“成绩”。", "忘记": "语义：“为了忘记成绩”与“没有放松学习”的目的相矛盾，句子说不通。"}, "sentence_index": 6, "correct_answer": "巩固"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种新方法让学生的运动量巩固了许多。", "explanation": "这里应该用〈增加〉。巩固表示使稳固，不表示数量增加，运动量增加要用“增加”。"}, {"text": "工人们正在巩固坏掉的电视机。", "explanation": "这里应该用〈修复〉。巩固是使东西更结实，把坏掉的东西修好要用“修复”。"}, {"text": "这种药能巩固头痛。", "explanation": "这里应该用〈减轻〉。巩固不表示减轻疼痛，缓解头痛要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "复习可以巩固了学到的语法。", "corrected_sentence": "复习可以巩固学到的语法。", "error_description": "时态助词错误：“可以”表示可能，后面不能加“了”，“巩固”后不用“了”，应说“复习可以巩固学到的语法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次施工把墙巩固很牢。", "corrected_sentence": "这次施工把墙巩固得很牢。", "error_description": "补语错误：“巩固”后接程度补语“很牢”时需要用“得”连接，应说“巩固得很牢”，不能直接说“巩固很牢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
