INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "颁发是把奖状或证书交给得到的人。", "primary_collocate": null, "pronunciation": "bān fā", "ipa": "pan˥ fa˥", "syllable_count": 2, "sentences": [{"text": "校长给获奖的同学颁发了奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天要颁发毕业证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在会上给他颁发荣誉证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家等着领导颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年六月给学生颁发毕业证。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理给优秀员工颁发了奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来给冠军颁发证书？", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，校长为三个同学颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向完成培训的人颁发证书。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午，学院给学生颁发奖状。", "target_word": "颁发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頒發", "label": "繁体"}, {"form": "颁发了", "label": "体标"}, {"form": "颁发过", "label": "体标"}], "register": "书面", "sense_fingerprint": "颁发：正式地把奖状、证书交给获得的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颁发", "is_correct": true, "explanation": "颁发：正式把奖状交给获奖的人，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物送进嘴里，不能用于奖状。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱奖状”。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”只带一个宾语（如仪式、会议），不能同时接“给同学”和“奖状”。"}], "explanations": {"颁发": "颁发：正式把奖状交给获奖的人，符合句意。", "吃": "语义：“吃”指把食物送进嘴里，不能用于奖状。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱奖状”。", "举行": "配价：“举行”只带一个宾语（如仪式、会议），不能同时接“给同学”和“奖状”。"}, "sentence_index": 0, "correct_answer": "颁发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每个月都给员工颁发工资。", "explanation": "这里应该用〈发放〉。颁发指正式授予奖状、证书等荣誉，发工资要用发放。"}, {"text": "他把自己的旧书颁发给了弟弟。", "explanation": "这里应该用〈赠送〉。颁发是由机关或组织正式授予，私人之间送书要用赠送。"}, {"text": "老师每天颁发作业给同学。", "explanation": "这里应该用〈发〉。颁发是正式授予，分发作业用发即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颁发", "is_correct": true, "explanation": "颁发：正式把证书交给获得者，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是用火毁坏东西，不能用来给冠军证书。"}, {"text": "配", "is_correct": false, "explanation": "搭配：“配”多用于钥匙、眼镜等，不说“配证书”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“给冠军”的赠予意思相反。"}], "explanations": {"颁发": "颁发：正式把证书交给获得者，符合句意。", "烧": "语义：“烧”是用火毁坏东西，不能用来给冠军证书。", "配": "搭配：“配”多用于钥匙、眼镜等，不说“配证书”。", "扔": "语义：“扔”表示丢弃，与“给冠军”的赠予意思相反。"}, "sentence_index": 6, "correct_answer": "颁发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙颁发给了我。", "explanation": "这里应该用〈交〉。颁发指正式授予荣誉、证书，把钥匙递给别人要用交。"}, {"text": "学院每年颁发一次运动会。", "explanation": "这里应该用〈举办〉。颁发指授予证书奖状，运动会要用举办。"}, {"text": "他颁发了一篇论文。", "explanation": "这里应该用〈发表〉。颁发指授予证书奖状，论文要用发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长在会上给他颁发过了奖状。", "corrected_sentence": "校长在会上给他颁发了奖状。", "error_description": "体标错误：“过”和“了”不能同时用在同一个动词后，应说“颁发了奖状”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把毕业证书颁发了给每位同学。", "corrected_sentence": "学校把毕业证书颁发给了每位同学。", "error_description": "“颁发给”之后的“了”应放在“给”后面，应说“颁发给了”，不能说“颁发了给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指图像不清晰、细节看不见。"}, {"text": "悠久", "is_correct": false, "explanation": "悠久形容历史长，与图像清晰程度没有反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容态度亲切，与高清没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦形容劳累，与高清没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指图像不清晰、细节看不见。", "悠久": "悠久形容历史长，与图像清晰程度没有反义关系。", "友好": "友好形容态度亲切，与高清没有反义关系。", "辛苦": "辛苦形容劳累，与高清没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指图像不清晰、细节看不见。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不平滑，与高清没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静形容没有声音，与图像清晰程度无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与高清没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指图像不清晰、细节看不见。", "粗糙": "粗糙形容表面不平滑，与高清没有反义关系。", "寂静": "寂静形容没有声音，与图像清晰程度无关。", "迟钝": "迟钝形容反应慢，与高清没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高清是图像特别清楚，看得很细。", "primary_collocate": null, "pronunciation": "gāo qīng", "ipa": "kɑʊ̯⁵⁵ tɕʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "高清照片可以看到每一根头发。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图是高清的，连小字都看得见。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥买了一台高清相机。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的画面是高清的，特别细。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在网上看了高清的月亮照片。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高清图片放大以后，还是很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用高清图像检查他的眼睛。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的高清画面看得很细。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我发一张高清的地图。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑的屏幕是高清的，字很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高清图片", "label": "复合"}, {"form": "高清画面", "label": "复合"}], "register": "中性", "sense_fingerprint": "图像特别清楚，细节看得见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容图像清晰、细节可见，与“看到每一根头发”相合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，照片不能用来形容。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，与照片的清晰程度无关。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，照片不能是寒冷的。"}], "explanations": {"高清": "正确：“高清”形容图像清晰、细节可见，与“看到每一根头发”相合。", "柔软": "搭配：“柔软”形容物体的质地，照片不能用来形容。", "甜": "语义：“甜”形容味道，与照片的清晰程度无关。", "寒冷": "语义：“寒冷”形容温度，照片不能是寒冷的。"}, "sentence_index": 0, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位厨师的刀工很高清。", "explanation": "这里应该用〈精细〉。高清只用于图像或屏幕的分辨率，不用于形容刀工。"}, {"text": "这家店的服务很高清。", "explanation": "这里应该用〈周到〉。高清只描述影像或屏幕的清晰度，不用于形容服务。"}, {"text": "他的思路很高清。", "explanation": "这里应该用〈清晰〉。高清只描述影像或屏幕的清晰度，不用于形容思路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容图像分辨率高，与“检查眼睛”的语境相合。"}, {"text": "高尚", "is_correct": false, "explanation": "语义：“高尚”形容品德，不能用来形容检查用的图像。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容人的体形，与图像无关。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容态度，不能用来形容图像。"}], "explanations": {"高清": "正确：“高清”形容图像分辨率高，与“检查眼睛”的语境相合。", "高尚": "语义：“高尚”形容品德，不能用来形容检查用的图像。", "肥胖": "体貌：“肥胖”形容人的体形，与图像无关。", "冷淡": "语义：“冷淡”形容态度，不能用来形容图像。"}, "sentence_index": 6, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道理讲得很高清。", "explanation": "这里应该用〈清楚〉。高清只描述画面的分辨率，不用于讲解道理。"}, {"text": "这件衣服的颜色很高清。", "explanation": "这里应该用〈鲜艳〉。高清只用于影像的清晰度，不能用来形容颜色。"}, {"text": "他的性格很高清，大家都喜欢他。", "explanation": "这里应该用〈开朗〉。高清只描述影像或屏幕的清晰度，不用于形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台相机拍出的照片得高清。", "corrected_sentence": "这台相机拍出的照片很高清。", "error_description": "错误：“照片得高清”。正确：“照片很高清”。“得”是补语标记，不能用来修饰形容词“高清”，程度副词应用“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台显微镜把细胞图片拍很得高清。", "corrected_sentence": "这台显微镜把细胞图片拍得很高清。", "error_description": "错误：“拍很得高清”。正确：“拍得很高清”。“得”后面接补语，“很”要放在补语的形容词前，不能放在“得”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：模糊与高清相反，指画面不清楚、细节看不清。"}, {"text": "悠久", "is_correct": false, "explanation": "悠久形容历史长，与画面清晰程度没有反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "友好形容态度亲切，与高清没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容不费力，与画面分辨率没有关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：模糊与高清相反，指画面不清楚、细节看不清。", "悠久": "悠久形容历史长，与画面清晰程度没有反义关系。", "友好": "友好形容态度亲切，与高清没有反义关系。", "轻松": "轻松形容不费力，与画面分辨率没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
