INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "分辨率很高、画面非常清晰的。", "primary_collocate": null, "pronunciation": "gāo qīng", "ipa": "kɑʊ̯⁵⁵ tɕʰiŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这台电视是高清的，画面很清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一台高清电视。", "target_word": "高清", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影有高清版本，可以在网上看。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的新手机能拍高清视频。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个高清屏幕看起来特别漂亮。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的电视不是高清的，画面不太清楚。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个视频太模糊了，有高清的吗？", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用高清摄像机拍出来的照片很好看。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家电影院的屏幕是高清的，很大。", "target_word": "高清", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把旧电视换成了高清的。", "target_word": "高清", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高清电视", "label": "复合"}, {"form": "高清视频", "label": "复合"}], "register": "中性", "sense_fingerprint": "分辨率高、画面清晰的影像或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”形容画面分辨率高，与“画面很清楚”相合。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，不能用来形容电视。"}, {"text": "老实", "is_correct": false, "explanation": "语义：“老实”形容人的品性，不能用来形容电视。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，与画面清楚的语境无关。"}], "explanations": {"高清": "正确：“高清”形容画面分辨率高，与“画面很清楚”相合。", "柔软": "搭配：“柔软”形容物体的质地，不能用来形容电视。", "老实": "语义：“老实”形容人的品性，不能用来形容电视。", "寒冷": "语义：“寒冷”形容温度，与画面清楚的语境无关。"}, "sentence_index": 0, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个答案很高清，大家都听懂了。", "explanation": "这里应该用〈清楚〉。高清只用于图像或屏幕的分辨率，不用于说明或道理。"}, {"text": "他的心地很高清，大家都喜欢他。", "explanation": "这里应该用〈善良〉。高清只描述影像或屏幕的清晰度，不用于形容人的心地。"}, {"text": "这杯茶的味道很高清。", "explanation": "这里应该用〈醇厚〉。高清只描述影像或屏幕的清晰度，不用于形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高清", "is_correct": true, "explanation": "正确：“高清”与“模糊”相对，询问是否有画面更清晰的版本。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容食物的味道，不能用来形容视频。"}, {"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人的性格，与视频无关。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”形容分量或心情，不能说视频沉重。"}], "explanations": {"高清": "正确：“高清”与“模糊”相对，询问是否有画面更清晰的版本。", "辛辣": "语义：“辛辣”形容食物的味道，不能用来形容视频。", "腼腆": "语义：“腼腆”形容人的性格，与视频无关。", "沉重": "搭配：“沉重”形容分量或心情，不能说视频沉重。"}, "sentence_index": 6, "correct_answer": "高清"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套家具的做工很高清。", "explanation": "这里应该用〈精致〉。高清只描述画面或屏幕的分辨率，不用于形容做工。"}, {"text": "他听到消息后，心里很高清。", "explanation": "这里应该用〈激动〉。高清只描述影像或屏幕的清晰度，不用于形容人的心情。"}, {"text": "他这次数学考试的成绩很高清。", "explanation": "这里应该用〈好〉。高清只描述影像的清晰程度，不用于形容成绩，成绩好要说“好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台投影仪让画面高清了。", "corrected_sentence": "这台投影仪让画面变高清了。", "error_description": "错误：“让画面高清了”漏了“变”。正确：“让画面变高清了”。“让……变”结构表示变成某种状态，“高清”作结果时要加“变”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一台高清地电视。", "corrected_sentence": "我买了一台高清的电视。", "error_description": "错误：“高清地电视”。正确：“高清的电视”。“地”用于修饰动词，修饰名词的定语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
