INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "紧挨着这一次之前的那一次。", "primary_collocate": null, "pronunciation": "shàng cì", "ipa": "ʂɑŋ˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "上次见面，你还是短头发。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次你说的那本书，我买到了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次来这儿，还是去年冬天。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上次来的时候，这里没有地铁。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次的会议在三楼开的。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上次给我打电话，是上周五。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次你生病，现在好了吗？", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次我忘了带伞，这次带了。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师上次说过，明天要考试。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上次吃火锅，我们一起去了那家店。", "target_word": "上次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "上次：紧靠现在之前的那一次，用来回忆过去的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1d2176-a13c-4769-a424-d290b8720390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。上次指紧挨着这一次之前的那一次。"}, {"text": "上菜", "is_correct": false, "explanation": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一次。"}, {"text": "上市", "is_correct": false, "explanation": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一次。"}, {"text": "上策", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一次。"}, {"text": "上册", "is_correct": false, "explanation": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一次。"}], "explanations": {"上次": "正确答案。上次指紧挨着这一次之前的那一次。", "上菜": "shàng cài 与 shàng cì 只有韵母不同（ai 与 i），意思是端上菜，不是前一次。", "上市": "shì 与 cì 声母不同（sh 与 c），意思是产品投放市场，不是前一次。", "上策": "cè 与 cì 韵母不同（e 与 i），意思是高明的办法，不是前一次。", "上册": "cè 与 cì 韵母不同（e 与 i），意思是书的上一册，不是前一次。"}, "sentence_index": null, "correct_answer": "上次"}, "level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。“上次见面”指前一次见面，与“还是短头发”的过去到现在对比相合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物”不是时间词，不能作“见面”的时间状语，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不是时间词，不能作“见面”的时间状语，句子不通。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：电影不能作为见面的时间状语，“电影见面”句子不通。"}], "explanations": {"上次": "正确答案。“上次见面”指前一次见面，与“还是短头发”的过去到现在对比相合。", "礼物": "搭配：“礼物”不是时间词，不能作“见面”的时间状语，句子不通。", "书包": "搭配：“书包”不是时间词，不能作“见面”的时间状语，句子不通。", "电影": "搭配：电影不能作为见面的时间状语，“电影见面”句子不通。"}, "sentence_index": 0, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们上次经常来这里吃饭。", "explanation": "这里应该用〈以前〉。上次只指一次，不能表示经常性的过去。"}, {"text": "你上次想来就来吧。", "explanation": "这里应该用〈随时〉。上次指紧挨着这一次之前的那一次，不能表示任何一次都可以；表示随便哪次都行要用〈随时〉。"}, {"text": "上次再来这里的时候，要记得带伞。", "explanation": "这里应该用〈以后〉。上次指过去，提醒将来要做的事应该用〈以后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上次", "is_correct": true, "explanation": "正确答案。“上次你生病，现在好了吗”指过去的一次生病，与“现在好了吗”相合。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指将来，与“现在好了吗”的现在时矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指未来，与“现在好了”的现在状态矛盾。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭你生病”不成立，餐时不能作为生病的时间状语。"}], "explanations": {"上次": "正确答案。“上次你生病，现在好了吗”指过去的一次生病，与“现在好了吗”相合。", "下次": "语义：“下次”指将来，与“现在好了吗”的现在时矛盾。", "将来": "语义：“将来”指未来，与“现在好了”的现在状态矛盾。", "午饭": "搭配：“午饭你生病”不成立，餐时不能作为生病的时间状语。"}, "sentence_index": 6, "correct_answer": "上次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上次吃火锅，我们每次都去那家店。", "explanation": "这里应该用〈以前〉。上次只指一次，不能用于表示多次的情况；表示多次要用〈以前〉。"}, {"text": "上次吃火锅，我们一起去那家店吧。", "explanation": "这里应该用〈明天〉。上次指过去，提议要去做的事应该用〈明天〉。"}, {"text": "上次吃火锅，我们下个月去那家店。", "explanation": "这里应该用〈下次〉。上次指已经过去的那一次，不能与“下个月”这样的将来时间连用；将来的时间要用〈下次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上次给你发着消息。", "corrected_sentence": "我上次给你发了消息。", "error_description": "错误：“发消息”是一次完成的动作，应用“了”表示完成；用“着”表示持续，与“上次”指过去的一次不合。正确形式是“我上次给你发了消息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上次的一起吃了饭。", "corrected_sentence": "我们上次一起吃了饭。", "error_description": "错误：在时间词“上次”后加“的”，使它变成定语修饰后面的“一起”，句子结构不通。正确形式是“我们上次一起吃了饭”，“上次”直接作状语，不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
