INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "来路是人或东西从哪里来的路。", "primary_collocate": null, "pronunciation": "lái lù", "ipa": "lai̯˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "来路上有一棵很大的树。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们顺着来路慢慢走回村子。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜雨，来路变得很难走。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路口，望着来路等朋友。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来路和去路都是这条河边的小路。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得来路，不会迷路的。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了很远，他又回头看来路。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑，我们找不到来路了。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥正好在我们的来路上。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪把来路盖住了，他们只好等天亮。", "target_word": "来路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "來路", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或东西来时走的那条路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来路", "is_correct": true, "explanation": "正确：“来路上”指来时的那条路上，有一棵树是合理的。"}, {"text": "信心", "is_correct": false, "explanation": "搭配：“上”前面要接具体的位置，“信心”是抽象概念，不能说“信心上”。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不是位置，“笑声上有一棵树”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是位置，“心情上有一棵树”没有意义。"}], "explanations": {"来路": "正确：“来路上”指来时的那条路上，有一棵树是合理的。", "信心": "搭配：“上”前面要接具体的位置，“信心”是抽象概念，不能说“信心上”。", "笑声": "语义：笑声不是位置，“笑声上有一棵树”说不通。", "心情": "语义：心情不是位置，“心情上有一棵树”没有意义。"}, "sentence_index": 0, "correct_answer": "来路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经规划好了去山顶的来路。", "explanation": "这里应该用〈路线〉。“来路”指已经走过的路，不能用来规划将要走的路线。"}, {"text": "一只狗突然跳出来，咬伤了他的来路。", "explanation": "这里应该用〈腿〉。“来路”指道路，不是身体部位，不能被咬伤。"}, {"text": "他把来路摆在了客厅里。", "explanation": "这里应该用〈物品〉。“来路”指道路，不是物品，不能摆在客厅里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来路", "is_correct": true, "explanation": "正确：“回头看”的对象是他走过的路，来路正合适。"}, {"text": "味道", "is_correct": false, "explanation": "语义：走了很远，“回头看味道”说不通。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿是感觉，不是可以回头去看的东西。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“看”后接可见的事物，“年龄”是抽象概念，不能说“看年龄”。"}], "explanations": {"来路": "正确：“回头看”的对象是他走过的路，来路正合适。", "味道": "语义：走了很远，“回头看味道”说不通。", "饥饿": "语义：饥饿是感觉，不是可以回头去看的东西。", "年龄": "搭配：“看”后接可见的事物，“年龄”是抽象概念，不能说“看年龄”。"}, "sentence_index": 6, "correct_answer": "来路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个来路在前面等着他。", "explanation": "这里应该用〈来人〉。“来路”指道路或来源，不指人，不能用来指站在前面等他的人。"}, {"text": "他推开来路，走进了房间。", "explanation": "这里应该用〈门〉。“来路”指道路，不能被推开，推开的应是门。"}, {"text": "他把来路装进了行李箱。", "explanation": "这里应该用〈东西〉。“来路”是道路，不是可以装进行李箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他顺着那位来路找到了那只狗。", "corrected_sentence": "他顺着那条来路找到了那只狗。", "error_description": "量词错误：“来路”指道路，应该用“条”计量；“位”用于人，这里用“位”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨冲坏了我们来路。", "corrected_sentence": "大雨冲坏了我们的来路。", "error_description": "漏用“的”：“我们”修饰“来路”时要用“的”，应说“我们的来路”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
