INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用符号表示的、反映各个量之间关系的式子。", "primary_collocate": null, "pronunciation": "gōng shì", "ipa": "kʊŋ˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "欧姆定律可以用一个简单的公式来表示。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理书里有很多公式，我看不懂。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式表示速度、时间和路程的关系。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用公式说明力和质量的关系。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在黑板上写了一个长长的公式。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式里有三个量，你先找出来。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要把数字放进公式，就能得到结果。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师每天都用公式计算桥的重量。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书把常用的物理公式都列出来了。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说这个公式里每个符号的意思。", "target_word": "公式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "物理公式", "label": "复合"}], "register": "书面", "sense_fingerprint": "用符号表示各量关系的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公式", "is_correct": true, "explanation": "公式：用符号表示、反映量之间关系的式子，即听到的目标词。"}, {"text": "共事", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是一起做事。"}, {"text": "公使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是外交使节。"}, {"text": "工时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是工作时间。"}, {"text": "公制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh／sh），意思是公制计量制度。"}], "explanations": {"公式": "公式：用符号表示、反映量之间关系的式子，即听到的目标词。", "共事": "gòng（第四声）与 gōng（第一声）声调不同，意思是一起做事。", "公使": "shǐ（第三声）与 shì（第四声）声调不同，意思是外交使节。", "工时": "shí（第二声）与 shì（第四声）声调不同，意思是工作时间。", "公制": "zhì 与 shì 声母不同（zh／sh），意思是公制计量制度。"}, "sentence_index": null, "correct_answer": "公式"}, "level_3": {"options": [{"text": "公式", "is_correct": true, "explanation": "公式：表示量之间关系的式子，这里指欧姆定律的表达式。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是机构，不能用来表示定律。"}, {"text": "桥梁", "is_correct": false, "explanation": "语义：桥梁是建筑物，表示定律的应是抽象的式子。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“表示”要求抽象的内容作宾语，“窗户”是具体的物件，不能用来表示定律。"}], "explanations": {"公式": "公式：表示量之间关系的式子，这里指欧姆定律的表达式。", "公司": "语义：公司是机构，不能用来表示定律。", "桥梁": "语义：桥梁是建筑物，表示定律的应是抽象的式子。", "窗户": "配价：“表示”要求抽象的内容作宾语，“窗户”是具体的物件，不能用来表示定律。"}, "sentence_index": 0, "correct_answer": "公式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的公式很严格。", "explanation": "这里应该用〈规定〉。公式指数学、物理中表示数量关系的式子，会议的要求要说“规定”。"}, {"text": "他在黑板上画了一幅公式。", "explanation": "这里应该用〈个〉。“幅”用于字画、图画，公式不用“幅”来数。"}, {"text": "这支曲子的公式写得很工整。", "explanation": "这里应该用〈乐谱〉。公式指数学、物理中表示数量关系的式子，曲子的记谱要说“乐谱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94764, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公式", "is_correct": true, "explanation": "公式：用符号表示、反映量之间关系的式子，即听到的目标词。"}, {"text": "公制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh／sh），意思是公制，即公制计量制度。"}, {"text": "公汽", "is_correct": false, "explanation": "qì 与 shì 声母不同（q／sh），意思是公共汽车（口语）。"}, {"text": "公立", "is_correct": false, "explanation": "lì 与 shì 声母不同（l／sh），意思是公办的，如公立学校。"}, {"text": "公地", "is_correct": false, "explanation": "dì 与 shì 声母不同（d／sh），意思是公有的土地。"}], "explanations": {"公式": "公式：用符号表示、反映量之间关系的式子，即听到的目标词。", "公制": "zhì 与 shì 声母不同（zh／sh），意思是公制，即公制计量制度。", "公汽": "qì 与 shì 声母不同（q／sh），意思是公共汽车（口语）。", "公立": "lì 与 shì 声母不同（l／sh），意思是公办的，如公立学校。", "公地": "dì 与 shì 声母不同（d／sh），意思是公有的土地。"}, "sentence_index": null, "correct_answer": "公式"}, "level_3": {"options": [{"text": "公式", "is_correct": true, "explanation": "公式：这里指可以代入数值计算的式子，把数字代入即可得到结果。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是地方，不能把数字放进去。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，数字不能放进花园得出结果。"}, {"text": "生日", "is_correct": false, "explanation": "配价：“放进”要求容器或位置作宾语，“生日”是时间，不能作为放入的地方。"}], "explanations": {"公式": "公式：这里指可以代入数值计算的式子，把数字代入即可得到结果。", "城市": "语义：城市是地方，不能把数字放进去。", "花园": "语义：花园是场所，数字不能放进花园得出结果。", "生日": "配价：“放进”要求容器或位置作宾语，“生日”是时间，不能作为放入的地方。"}, "sentence_index": 6, "correct_answer": "公式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的公式是人民路十号。", "explanation": "这里应该用〈地址〉。公式指数学、物理中表示数量关系的式子，住址要说“地址”。"}, {"text": "他在作业本上写了一首公式。", "explanation": "这里应该用〈个〉。“首”用于诗词、歌曲，公式不用“首”来数。"}, {"text": "桌上放着一把公式。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，公式不用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很有用公式。", "corrected_sentence": "这是一个很有用的公式。", "error_description": "漏“的”：“很有用”作定语修饰名词，中间要加“的”，应说“很有用的公式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看懂了这把公式。", "corrected_sentence": "我看懂了这个公式。", "error_description": "量词错误：“公式”的量词是“个”，“把”用于有柄的器具，应说“这个公式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
