INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冒是从里面往外跑出来。", "primary_collocate": null, "pronunciation": "mào", "ipa": "maʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "春天到了，小草从地里冒出来了。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里冒出了很多小泡泡。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脑子里突然冒出一个新想法。", "target_word": "冒", "complexity_tier": "T3", "furigana": "mào", "sentence_source": "generated"}, {"text": "雨后，山上冒出了许多蘑菇。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小鱼从水里冒出头来。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅盖一开，白气就冒出来了。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下冒出一股清水。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外突然冒出一个人影。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树从石头缝里冒了出来。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近冒出了一家新书店。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒出", "label": "复合"}, {"form": "冒了", "label": "体标"}, {"form": "冒出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "冒：从里面往外出现、长出来（冒出）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1d2176-a13c-4769-a424-d290b8720390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒读 mào，意思是从里面往外出现或升起。"}, {"text": "猫", "is_correct": false, "explanation": "māo（第一声）与 mào（第四声）声调不同，意思是猫。"}, {"text": "毛", "is_correct": false, "explanation": "máo（第二声）与 mào（第四声）声调不同，意思是毛。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是报纸或报告。"}], "explanations": {"冒": "正确：冒读 mào，意思是从里面往外出现或升起。", "猫": "māo（第一声）与 mào（第四声）声调不同，意思是猫。", "毛": "máo（第二声）与 mào（第四声）声调不同，意思是毛。", "报": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是报纸或报告。"}, "sentence_index": null, "correct_answer": "冒"}, "level_3": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒出来表示小草从地里长出、露出，与句意相符。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”多用于液体或颗粒，不能用于小草从地里出来。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，小草不会飞出来。"}, {"text": "浮", "is_correct": false, "explanation": "语义：“浮”指漂在水面上，小草从地里出来不能说浮。"}], "explanations": {"冒": "正确：冒出来表示小草从地里长出、露出，与句意相符。", "倒": "搭配：“倒”多用于液体或颗粒，不能用于小草从地里出来。", "飞": "语义：“飞”指在空中移动，小草不会飞出来。", "浮": "语义：“浮”指漂在水面上，小草从地里出来不能说浮。"}, "sentence_index": 0, "correct_answer": "冒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨水从屋顶冒下来了。", "explanation": "这里应该用〈流下来〉。冒指从里面向上或向外冒出，不能用于向下流动。"}, {"text": "蜗牛冒上了墙。", "explanation": "这里应该用〈爬上〉。冒指从里面向外透出或冒出，不能用于动物自己向上移动；蜗牛向上爬要说爬上。"}, {"text": "小鱼从网里冒到了水底下。", "explanation": "这里应该用〈沉〉。冒表示向外或向上出现，不能表示向水底移动；要说沉到水底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94765, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒读 mào，意思是从里面往外出现或升起。"}, {"text": "闹", "is_correct": false, "explanation": "nào（第四声）与 mào（第四声）声母不同（n 与 m），意思是吵闹。"}, {"text": "抱", "is_correct": false, "explanation": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是抱。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 mào（第四声）韵母不同（ai 与 ao），意思是卖。"}], "explanations": {"冒": "正确：冒读 mào，意思是从里面往外出现或升起。", "闹": "nào（第四声）与 mào（第四声）声母不同（n 与 m），意思是吵闹。", "抱": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是抱。", "卖": "mài（第四声）与 mào（第四声）韵母不同（ai 与 ao），意思是卖。"}, "sentence_index": null, "correct_answer": "冒"}, "level_3": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒出一股清水，表示水从地下涌出，与句意相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动物体，“地下搬出一股清水”不通。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指气流带动物体，清水不会被吹出，句意不通。"}, {"text": "长", "is_correct": false, "explanation": "搭配：“长”用于生物生长，水不能长出来。"}], "explanations": {"冒": "正确：冒出一股清水，表示水从地下涌出，与句意相符。", "搬": "语义：“搬”指移动物体，“地下搬出一股清水”不通。", "吹": "语义：“吹”指气流带动物体，清水不会被吹出，句意不通。", "长": "搭配：“长”用于生物生长，水不能长出来。"}, "sentence_index": 6, "correct_answer": "冒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在地下冒出了一件文物。", "explanation": "这里应该用〈挖出〉。冒出是东西自己出现，不能说有人有意把东西弄出来。"}, {"text": "我家附近冒下了一家新书店。", "explanation": "这里应该用〈开〉。冒表示从里往外出现，不能用于向下的方向。"}, {"text": "他从箱子里冒出一张照片。", "explanation": "这里应该用〈翻出〉。冒出是东西自己出现，不能说有人主动把东西从箱子里取出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里冒下了一朵小花。", "corrected_sentence": "院子里冒出了一朵小花。", "error_description": "错误：“冒”表示向上或向外出现，不能接“下”，应说“冒出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落冒下来一条小蛇。", "corrected_sentence": "院子角落冒出来一条小蛇。", "error_description": "错误：“冒”表示向上或向外出现，不能接“下来”，应说“冒出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
