INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向外透出或升起；也指不顾危险。", "primary_collocate": null, "pronunciation": "mào", "ipa": "maʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "锅里冒着热气。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟囱在冒黑烟。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得直冒汗。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨，他冒着雨回家了。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冒着大火冲进房子。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她冒着危险救了小孩。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们冒雨走了很远。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冒着大雪去上班。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水刚烧开，杯子里还在冒热气。", "target_word": "冒", "complexity_tier": "T3", "furigana": "mào", "sentence_source": "generated"}, {"text": "车坏了，发动机冒烟了。", "target_word": "冒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒着", "label": "体标"}, {"form": "冒了", "label": "体标"}, {"form": "冒过", "label": "体标"}, {"form": "冒烟", "label": "复合"}], "register": "中性", "sense_fingerprint": "冒：烟、汗、气等向外透出升起；不顾（雨、危险）而行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe1d2176-a13c-4769-a424-d290b8720390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94766, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒读 mào，意思是向外透出或升起，也指不顾危险。"}, {"text": "猫", "is_correct": false, "explanation": "māo（第一声）与 mào（第四声）声调不同，意思是猫。"}, {"text": "毛", "is_correct": false, "explanation": "máo（第二声）与 mào（第四声）声调不同，意思是毛。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是报纸或报告。"}], "explanations": {"冒": "正确：冒读 mào，意思是向外透出或升起，也指不顾危险。", "猫": "māo（第一声）与 mào（第四声）声调不同，意思是猫。", "毛": "máo（第二声）与 mào（第四声）声调不同，意思是毛。", "报": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是报纸或报告。"}, "sentence_index": null, "correct_answer": "冒"}, "level_3": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒着热气表示热气向上升起，与句意相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掉的意思，“扔着热气”说不通，热气不能被扔。"}, {"text": "端", "is_correct": false, "explanation": "搭配：“端”的对象是可以托起的器物，不能端热气。"}, {"text": "切", "is_correct": false, "explanation": "配价：“切”需要有被切的对象，“锅里切着热气”没有合理的宾语。"}], "explanations": {"冒": "正确：冒着热气表示热气向上升起，与句意相符。", "扔": "语义：扔是抛掉的意思，“扔着热气”说不通，热气不能被扔。", "端": "搭配：“端”的对象是可以托起的器物，不能端热气。", "切": "配价：“切”需要有被切的对象，“锅里切着热气”没有合理的宾语。"}, "sentence_index": 0, "correct_answer": "冒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停以后，他冒着雨回家了。", "explanation": "这里应该用〈趁着〉。冒着表示不顾雨等情况而行，雨已经停了就不能再说冒着雨。"}, {"text": "他冒着妈妈去上班。", "explanation": "这里应该用〈陪着〉。冒着只用于危险、雨、火等情况，不能接“妈妈”这样的人。"}, {"text": "他冒着清晨出门。", "explanation": "这里应该用〈趁着〉。冒着后面接的是危险、恶劣天气等，不能接表示时间的“清晨”；要说趁清晨出门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94766, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒读 mào，意思是向外透出或升起，也指不顾危险。"}, {"text": "闹", "is_correct": false, "explanation": "nào（第四声）与 mào（第四声）声母不同（n 与 m），意思是吵闹。"}, {"text": "抱", "is_correct": false, "explanation": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是抱。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 mào（第四声）韵母不同（ai 与 ao），意思是卖。"}], "explanations": {"冒": "正确：冒读 mào，意思是向外透出或升起，也指不顾危险。", "闹": "nào（第四声）与 mào（第四声）声母不同（n 与 m），意思是吵闹。", "抱": "bào（第四声）与 mào（第四声）声母不同（b 与 m），意思是抱。", "卖": "mài（第四声）与 mào（第四声）韵母不同（ai 与 ao），意思是卖。"}, "sentence_index": null, "correct_answer": "冒"}, "level_3": {"options": [{"text": "冒", "is_correct": true, "explanation": "正确：冒雨表示不顾雨走路，与句意相符。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示畏惧，“怕雨走了很远”与句意不符。"}, {"text": "等", "is_correct": false, "explanation": "搭配：“等”后要接等待的对象或时间，不能接雨来修饰走路。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”需要可抱的对象，“抱雨走了很远”不通。"}], "explanations": {"冒": "正确：冒雨表示不顾雨走路，与句意相符。", "怕": "语义：“怕”表示畏惧，“怕雨走了很远”与句意不符。", "等": "搭配：“等”后要接等待的对象或时间，不能接雨来修饰走路。", "抱": "搭配：“抱”需要可抱的对象，“抱雨走了很远”不通。"}, "sentence_index": 6, "correct_answer": "冒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他冒着车去上班。", "explanation": "这里应该用〈开着〉。冒着只表示不顾危险或困难，不能接“车”这样的交通工具；要说开车去上班。"}, {"text": "他冒着笑走了。", "explanation": "这里应该用〈带着〉。冒着只表示不顾危险或困难，不能接表情。"}, {"text": "他冒着大衣出门了。", "explanation": "这里应该用〈穿着〉。冒着只表示不顾危险或困难，不能接“大衣”这样的衣物；要说穿着大衣出门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她急得冒直汗。", "corrected_sentence": "她急得直冒汗。", "error_description": "错误：“直”是副词，应放在动词“冒”之前，写成“直冒汗”；“冒直汗”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冒了着雪去接孩子。", "corrected_sentence": "他冒着雪去接孩子。", "error_description": "错误：“冒”后不能同时带“了”和“着”；表示不顾风雪的状态只用“冒着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64422c5c-c98b-451d-a4c7-0d54eb55faf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
