INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反击是别人打你，你也打回去。", "primary_collocate": null, "pronunciation": "fǎn jī", "ipa": "fan˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他打我一下，我也反击了。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗被踢了一脚，开始反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人先动手，我只好反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人打你的时候，你可以反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打了我，我马上反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被推倒了，站起来就反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学打了她一下，她不想反击。", "target_word": "反击", "complexity_tier": "T3", "furigana": "tóng xué dǎ le tā yí xià, tā bù xiǎng fǎn jī.", "sentence_source": "generated"}, {"text": "他们先打过我们，所以我们反击了。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被打了，为什么不反击？", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫被狗抓了一下，突然转身反击。", "target_word": "反击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反击了", "label": "体标"}, {"form": "反击过", "label": "体标"}, {"form": "反击战", "label": "复合"}], "register": "中性", "sense_fingerprint": "反击|动词|别人打你你也打回去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反击", "is_correct": true, "explanation": "正确。“反击”指受到攻击后进行回击，与“他打我一下”的语境相符。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：对方先打了我，我却“道歉”，与“他打我一下”的语境相悖。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带宾语（感谢谁或什么），此处没有宾语，句子不完整。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：被打之后“庆祝”，与句中受攻击的语境冲突，句意不通。"}], "explanations": {"反击": "正确。“反击”指受到攻击后进行回击，与“他打我一下”的语境相符。", "道歉": "语义：对方先打了我，我却“道歉”，与“他打我一下”的语境相悖。", "感谢": "配价：“感谢”需要带宾语（感谢谁或什么），此处没有宾语，句子不完整。", "庆祝": "语义：被打之后“庆祝”，与句中受攻击的语境冲突，句意不通。"}, "sentence_index": 0, "correct_answer": "反击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常反击自己的错误。", "explanation": "这里应该用〈反省〉。反击是受攻击后的回击，检讨自己的错误要用“反省”。"}, {"text": "他先反击我，我没有生气。", "explanation": "这里应该用〈挑衅〉。反击要在对方先动手之后才能用，先挑衅的人不能说反击。"}, {"text": "大家正在反击这个问题，气氛很热烈。", "explanation": "这里应该用〈讨论〉。反击指受攻击后的回击，对问题进行商议要用“讨论”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反击", "is_correct": true, "explanation": "正确。“反击”与“同学打了她一下”的语境相符，表示受攻击后的还手。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”需要带宾语（祝贺谁或什么），此处没有宾语，句子不完整。"}, {"text": "请客", "is_correct": false, "explanation": "语义：同学刚打了她，她却“请客”，与句意冲突，不合情理。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”需要带宾语（欢迎谁），单独作谓语时句子不完整。"}], "explanations": {"反击": "正确。“反击”与“同学打了她一下”的语境相符，表示受攻击后的还手。", "祝贺": "配价：“祝贺”需要带宾语（祝贺谁或什么），此处没有宾语，句子不完整。", "请客": "语义：同学刚打了她，她却“请客”，与句意冲突，不合情理。", "欢迎": "配价：“欢迎”需要带宾语（欢迎谁），单独作谓语时句子不完整。"}, "sentence_index": 6, "correct_answer": "反击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察反击了那起案件。", "explanation": "这里应该用〈调查〉。反击是回击已经发生的攻击，对案件进行查问要用“调查”。"}, {"text": "强盗反击了老人的钱包。", "explanation": "这里应该用〈抢夺〉。反击是回击已经发生的攻击，抢走别人财物要用“抢夺”。"}, {"text": "同学们反击他的好成绩。", "explanation": "这里应该用〈称赞〉。反击只指受攻击后的还手，对他人的成绩表示肯定要用“称赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打我一下，我把反击了他。", "corrected_sentence": "他打我一下，我反击了他。", "error_description": "错误：“我把反击了他”。正确：“我反击了他”。“把”字句需要“把＋宾语＋动词”的结构，这里“把”后直接是动词，应删去“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只兔子被狗追着，还没反击了。", "corrected_sentence": "这只兔子被狗追着，还没反击。", "error_description": "错误：“还没反击了”。正确：“还没反击”。“没”表示否定，否定句中动词后不能再带动态助词“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
