INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "合约是两边人说好后写下的纸，要照着做。", "primary_collocate": null, "pronunciation": "hé yuē", "ipa": "xɤ˧˥ ɥœ˥", "syllable_count": 2, "sentences": [{"text": "我们和房东签了一份合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合约写得很清楚，你可以放心。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约上说，每月五号要交房租。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把合约放在桌子上，没有看完。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要照着合约做，不能乱改。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签合约以前，请先读一读每一句话。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张合约我已经给老板看过了。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机公司给我寄来了新合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约丢了，我得再要一份。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王对合约上的字不太明白。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "双方说好后写下、要照做的纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：双方签下的书面协议，这里指与房东签的纸质合约。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“签”多用于合约、文件，“报纸”通常说“订”，“签了一份报纸”不说。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是纸质文件，无法签订。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是可以签的文件。"}], "explanations": {"合约": "合约：双方签下的书面协议，这里指与房东签的纸质合约。", "报纸": "搭配：“签”多用于合约、文件，“报纸”通常说“订”，“签了一份报纸”不说。", "蛋糕": "语义：蛋糕不是纸质文件，无法签订。", "饭菜": "语义：饭菜是食物，不是可以签的文件。"}, "sentence_index": 0, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一只合约，没有看完。", "explanation": "这里应该用〈份〉。“只”多用于动物或成对物品中的一个，不用来数合约。"}, {"text": "妈妈留给我一份合约，上面写着她的心愿。", "explanation": "这里应该用〈遗嘱〉。合约是双方订立的书面协议，单方面留下的心愿要说“遗嘱”。"}, {"text": "他买了一把合约。", "explanation": "这里应该用〈份〉。“把”用于有柄的器具，合约不用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：这里指已经给老板看过的那份纸质合约。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是要给老板看的文件。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是家具，不是要给老板看的纸质文件。"}, {"text": "饼", "is_correct": false, "explanation": "语义：饼是食物，不是可以给老板看的纸质文件，句意不通。"}], "explanations": {"合约": "合约：这里指已经给老板看过的那份纸质合约。", "桌子": "语义：桌子是家具，不是要给老板看的文件。", "床": "语义：床是家具，不是要给老板看的纸质文件。", "饼": "语义：饼是食物，不是可以给老板看的纸质文件，句意不通。"}, "sentence_index": 6, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天忘带合约，刷不开宿舍的门。", "explanation": "这里应该用〈门卡〉。合约是双方订立的书面协议，开门用的卡要说“门卡”。"}, {"text": "小王手里拿着一条合约。", "explanation": "这里应该用〈份〉。“条”用于细长的东西，合约不用“条”来数。"}, {"text": "小王念了一首合约。", "explanation": "这里应该用〈份〉。“首”用于诗词、歌曲，合约不用“首”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们签了三条合约。", "corrected_sentence": "我们签了三份合约。", "error_description": "量词错误：“合约”的量词是“份”，“条”用于细长的东西，应说“三份合约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找到了那旧份合约。", "corrected_sentence": "我找到了那份旧合约。", "error_description": "修饰语位置错误：“旧”作定语应放在量词“份”前，应说“那份旧合约”，不能说“那旧份合约”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
