INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94776, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "双方或多方经协商订立的、具有约束力的书面协议。", "primary_collocate": null, "pronunciation": "hé yuē", "ipa": "xɤ˧˥ ɥœ˥", "syllable_count": 2, "sentences": [{"text": "两家公司经过谈判，订立了合作合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约一旦签字，双方就必须遵守。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他违反了合约，要赔偿对方的损失。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合约的有效期是三年。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约规定，货物必须在月底前送到。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师仔细检查了合约里的每一条。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方同意延长合约，继续合作。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合约到期后，公司没有再续签。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不履行合约，就要负法律责任。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队和这位球员签了五年的合约。", "target_word": "合约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "书面", "sense_fingerprint": "协商订立、有约束力的书面协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：双方经协商订立的书面协议，这里指合作合约。"}, {"text": "方式", "is_correct": false, "explanation": "搭配：“订立”后接的是协议、合同一类，不能接“方式”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是协议，不能订立。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送人的东西，不能订立。"}], "explanations": {"合约": "合约：双方经协商订立的书面协议，这里指合作合约。", "方式": "搭配：“订立”后接的是协议、合同一类，不能接“方式”。", "食物": "语义：食物不是协议，不能订立。", "礼物": "语义：礼物是送人的东西，不能订立。"}, "sentence_index": 0, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把今天的心情写成了一份合约。", "explanation": "这里应该用〈日记〉。合约必须是双方订立的协议，个人的心情记录要说“日记”。"}, {"text": "老师发给他一份合约，表扬他的努力。", "explanation": "这里应该用〈奖状〉。合约是双方协商订立的协议，表扬用的证书要说“奖状”。"}, {"text": "这把合约的有效期是三年。", "explanation": "这里应该用〈份〉。“把”用于有柄的器具，合约不用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合约", "is_correct": true, "explanation": "合约：双方的书面协议，这里指要延长的那份协议。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不是协议，不能延长它的期限，句意不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "配价：“延长”要接时间、期限或长度，“饭菜”不能作为延长的对象。"}, {"text": "大衣", "is_correct": false, "explanation": "语义：大衣是衣服，不是可以延长的协议或期限。"}], "explanations": {"合约": "合约：双方的书面协议，这里指要延长的那份协议。", "房间": "语义：房间是空间，不是协议，不能延长它的期限，句意不通。", "饭菜": "配价：“延长”要接时间、期限或长度，“饭菜”不能作为延长的对象。", "大衣": "语义：大衣是衣服，不是可以延长的协议或期限。"}, "sentence_index": 6, "correct_answer": "合约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师今天布置的合约明天要交。", "explanation": "这里应该用〈作业〉。合约是双方协商订立的协议，老师布置的学习任务要说“作业”。"}, {"text": "球队和这位球员签了一只合约，期限五年。", "explanation": "这里应该用〈份〉。“只”多用于动物或成对物品中的一个，不用来数合约。"}, {"text": "他向母亲作出了合约。", "explanation": "这里应该用〈承诺〉。合约是双方签订的书面协议，对家人的承诺不用“合约”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国政府签订了一条重要合约。", "corrected_sentence": "两国政府签订了一份重要合约。", "error_description": "量词错误：“合约”的量词是“份”，“条”不用于合约，应说“一份重要合约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们签了一份新地合约。", "corrected_sentence": "我们签了一份新的合约。", "error_description": "结构助词错误：修饰名词“合约”的“新”后要用“的”，不用“地”，应说“一份新的合约”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
