INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同人是一起做同一件事的人。", "primary_collocate": null, "pronunciation": "tóng rén", "ipa": "tʰʊŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们是一起做公益的同人。", "target_word": "同人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这几位同人每周聚一次，交流研究进展。", "target_word": "同人", "complexity_tier": "T3", "furigana": "wǒ men zhè jǐ wèi tóng rén měi zhōu jù yí cì, jiāo liú yán jiū jìn zhǎn", "sentence_source": "generated"}, {"text": "他总是主动帮助身边的同人。", "target_word": "同人", "complexity_tier": "T3", "furigana": "tā zǒng shì zhǔ dòng bāng zhù shēn biān de tóng rén", "sentence_source": "generated"}, {"text": "同人之间要互相帮助。", "target_word": "同人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和几位同人一起发起了这个读书会。", "target_word": "同人", "complexity_tier": "T3", "furigana": "tā hé jǐ wèi tóng rén yì qǐ fā qǐ le zhè ge dú shū huì", "sentence_source": "generated"}, {"text": "他和几位同人经常在周末一起爬山。", "target_word": "同人", "complexity_tier": "T3", "furigana": "tā hé jǐ wèi tóng rén jīng cháng zài zhōu mò yì qǐ pá shān", "sentence_source": "generated"}, {"text": "他请几位同人来家里做客，一起讨论问题。", "target_word": "同人", "complexity_tier": "T3", "furigana": "tā qǐng jǐ wèi tóng rén lái jiā lǐ zuò kè, yì qǐ tǎo lùn wèn tí", "sentence_source": "generated"}, {"text": "几位同人在一起切磋棋艺，都很开心。", "target_word": "同人", "complexity_tier": "T3", "furigana": "jǐ wèi tóng rén zài yì qǐ qiē cuō qí yì, dōu hěn kāi xīn", "sentence_source": "generated"}, {"text": "她很关心每一位同人的成长。", "target_word": "同人", "complexity_tier": "T3", "furigana": "tā hěn guān xīn měi yí wèi tóng rén de chéng zhǎng", "sentence_source": "generated"}, {"text": "我们这些同人一起走过很多路。", "target_word": "同人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一起做同一件事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同人", "is_correct": true, "explanation": "正确：同人指一起做同一件事的人，与“一起做公益”相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手是相互竞争的人，与“一起做公益”的合作关系矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人与“一起做公益”的合作关系完全相反，句意不通。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人与事情无关，不会一起做公益，与句意矛盾。"}], "explanations": {"同人": "正确：同人指一起做同一件事的人，与“一起做公益”相符。", "对手": "语义：对手是相互竞争的人，与“一起做公益”的合作关系矛盾。", "敌人": "语义：敌人与“一起做公益”的合作关系完全相反，句意不通。", "路人": "语义：路人与事情无关，不会一起做公益，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "同人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同人是一台电脑。", "explanation": "这里应该用〈伙伴〉。同人指人，不能指电脑这样的物品。"}, {"text": "那只同人很热心。", "explanation": "这里应该用〈位〉。同人指人，量词用“位”，“只”多用于动物或物品。"}, {"text": "两国结成了同人。", "explanation": "这里应该用〈同盟〉。同人指人，不能指国家之间的组织关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同人", "is_correct": true, "explanation": "正确：同人指志趣相同或一起做事的人，可以被邀请来做客、讨论问题。"}, {"text": "尸体", "is_correct": false, "explanation": "语义：尸体不能来家里做客，也不能参与讨论，与句意矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“几位”只修饰人，不能与“石头”搭配。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被邀请做客，与“请……来做客”矛盾。"}], "explanations": {"同人": "正确：同人指志趣相同或一起做事的人，可以被邀请来做客、讨论问题。", "尸体": "语义：尸体不能来家里做客，也不能参与讨论，与句意矛盾。", "石头": "搭配：“几位”只修饰人，不能与“石头”搭配。", "影子": "语义：影子不能被邀请做客，与“请……来做客”矛盾。"}, "sentence_index": 6, "correct_answer": "同人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的同人很强，我们很难赢。", "explanation": "这里应该用〈对手〉。同人指志趣相同、一起做事的人，比赛中的对方不属于此类。"}, {"text": "这个同人很好吃。", "explanation": "这里应该用〈食物〉。同人指人，不能用来形容食物。"}, {"text": "我的同人很好用。", "explanation": "这里应该用〈手机〉。同人指人，不能用来形容物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几只同人一起去山里植树。", "corrected_sentence": "我们几位同人一起去山里植树。", "error_description": "量词错误：指人的“同人”应用“位”，不能用“只”。正确说法是“我们几位同人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位同人的一起走过很长的路。", "corrected_sentence": "几位同人一起走过很长的路。", "error_description": "多用了“的”：“一起”是状语，“同人”后不能接“的”，应删去“的”，说“几位同人一起走过很长的路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼", "is_correct": true, "explanation": "正确。“吸”与“呼”是一对反义词，分别指吸气与呼气。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“吸”不构成反义关系，与吸气这一义项无关。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“吸”不构成反义关系，二者不表示相对的动作。"}, {"text": "看", "is_correct": false, "explanation": "“看”与“吸”不构成反义关系，与吸入空气这一义项无关。"}], "correct_answer": "呼", "explanations": {"呼": "正确。“吸”与“呼”是一对反义词，分别指吸气与呼气。", "跑": "“跑”与“吸”不构成反义关系，与吸气这一义项无关。", "写": "“写”与“吸”不构成反义关系，二者不表示相对的动作。", "看": "“看”与“吸”不构成反义关系，与吸入空气这一义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
