INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把气体或液体经口鼻引入体内；也指物体把别的东西引过来。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "这块磁铁能把铁钉吸起来。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海绵吸水很快。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毛巾吸了很多水。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，吸了一口新鲜空气。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光把很多小虫吸过来了。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的衣服吸热，夏天穿着很热。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘吸了烟味，很难洗干净。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器可以把地上的灰吸走。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在河边，用管子吸水。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干土吸雨水，很快就不湿了。", "target_word": "吸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸了", "label": "体标"}, {"form": "吸过", "label": "体标"}, {"form": "吸吸", "label": "重叠"}], "register": "中性", "sense_fingerprint": "吸|动词|吸入体内或把别的东西引过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88937676-1732-4c8a-9ac7-4b6520113a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”（第一声）指把气体或液体引入体内，或把别的东西引过来。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是洗。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是练习、学习。"}, {"text": "星", "is_correct": false, "explanation": "xīng 比 xī 多一个鼻音韵尾 -ng，意思是星星。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是系统、联系。"}], "explanations": {"吸": "正确。“吸”（第一声）指把气体或液体引入体内，或把别的东西引过来。", "洗": "xǐ（第三声）与 xī（第一声）声调不同，意思是洗。", "习": "xí（第二声）与 xī（第一声）声调不同，意思是练习、学习。", "星": "xīng 比 xī 多一个鼻音韵尾 -ng，意思是星星。", "系": "xì（第四声）与 xī（第一声）声调不同，意思是系统、联系。"}, "sentence_index": null, "correct_answer": "吸"}, "level_3": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”与“把铁钉……起来”相符，指磁铁把铁钉引过来。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”是用鼻子辨别气味，不能使铁钉被引过来，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，铁钉不能作“吃”的对象。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”的对象是食物或液体，不能说“把铁钉尝起来”。"}], "explanations": {"吸": "正确。“吸”与“把铁钉……起来”相符，指磁铁把铁钉引过来。", "闻": "语义：“闻”是用鼻子辨别气味，不能使铁钉被引过来，句意不通。", "吃": "搭配：“吃”的对象是食物，铁钉不能作“吃”的对象。", "尝": "搭配：“尝”的对象是食物或液体，不能说“把铁钉尝起来”。"}, "sentence_index": 0, "correct_answer": "吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她闭上眼睛，慢慢吸出一口新鲜空气。", "explanation": "这里应该用〈呼〉。吸是把空气吸进体内，把空气送出体外要用“呼”，“吸出”与呼气方向相反。"}, {"text": "消防员用水枪把水吸向火场。", "explanation": "这里应该用〈喷〉。水枪是向外射水，要用“喷”；“吸”表示把东西拉进来，方向相反。"}, {"text": "他一口把药吸了下去。", "explanation": "这里应该用〈吞〉。吸是把气体或液体吸入，吞下药片要用“吞”，不能用“吸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”（第一声）指把气体或液体引入体内，或把别的东西引过来。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，意思是喜欢。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xī（第一声）声调不同，意思是席位、席子。"}, {"text": "细", "is_correct": false, "explanation": "xì（第四声）与 xī（第一声）声调不同，意思是细小。"}, {"text": "心", "is_correct": false, "explanation": "xīn 比 xī 多一个韵尾 -n，意思是心脏、心思。"}], "explanations": {"吸": "正确。“吸”（第一声）指把气体或液体引入体内，或把别的东西引过来。", "喜": "xǐ（第三声）与 xī（第一声）声调不同，意思是喜欢。", "席": "xí（第二声）与 xī（第一声）声调不同，意思是席位、席子。", "细": "xì（第四声）与 xī（第一声）声调不同，意思是细小。", "心": "xīn 比 xī 多一个韵尾 -n，意思是心脏、心思。"}, "sentence_index": null, "correct_answer": "吸"}, "level_3": {"options": [{"text": "吸", "is_correct": true, "explanation": "正确。“吸”与“窗帘……了烟味”相符，指窗帘把烟味吸收进去。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂具体的物体，不能说“挂了烟味”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指把衣物套在身上，窗帘不能“穿”烟味，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体的物件，烟味不能被“扔”，搭配不当。"}], "explanations": {"吸": "正确。“吸”与“窗帘……了烟味”相符，指窗帘把烟味吸收进去。", "挂": "搭配：“挂”指悬挂具体的物体，不能说“挂了烟味”。", "穿": "语义：“穿”指把衣物套在身上，窗帘不能“穿”烟味，句意不通。", "扔": "搭配：“扔”的对象是具体的物件，烟味不能被“扔”，搭配不当。"}, "sentence_index": 6, "correct_answer": "吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力吸住了缰绳。", "explanation": "这里应该用〈拉〉。吸是把东西引入体内或引过来，抓住缰绳要用“拉”，不能用“吸”。"}, {"text": "他一脚吸飞了足球。", "explanation": "这里应该用〈踢〉。吸表示把东西拉进来或吸收，踢飞足球要用“踢”。"}, {"text": "他一口吸住了苹果。", "explanation": "这里应该用〈咬〉。吸指把东西拉进来或吸入，用牙齿夹住东西要用“咬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在山顶，吸了一个清新的空气。", "corrected_sentence": "他站在山顶，吸了一口清新的空气。", "error_description": "错误：“吸了一个清新的空气”。正确：“吸了一口清新的空气”。吸气的量词应用“口”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙子吸得大量雨水，地面很快就干了。", "corrected_sentence": "沙子吸了大量雨水，地面很快就干了。", "error_description": "错误：“吸得大量雨水”。正确：“吸了大量雨水”。“得”后应接补语，不能直接带宾语；表示已经发生的吸收动作应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38a86f10-2060-4178-bcae-2573dbafb9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
