INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国际上统一规定、通用的计量单位。", "primary_collocate": null, "pronunciation": "guó jì dān wèi", "ipa": "kwo˧˥ tɕi˥˩ tan˥ wei˥˩", "syllable_count": 4, "sentences": [{"text": "米是长度的国际单位。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "质量的国际单位是千克。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在论文里都用国际单位。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间的国际单位是秒。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用国际单位，各国的数据才好比较。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上说，温度的国际单位是开尔文。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些数字都改成国际单位。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力的国际单位叫牛顿。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际单位让全世界的科学家能互相看懂数据。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试要求大家用国际单位来表示答案。", "target_word": "国际单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "国际单位制", "label": "复合"}, {"form": "國際單位", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国际统一规定的计量单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际单位", "is_correct": true, "explanation": "正确：国际单位是国际上统一规定的计量单位，米正是长度的国际单位。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“长度”是可以度量的属性，“颜色”不是计量单位，“长度的颜色”说不通。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是计量单位，“长度的语言”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“长度”与“重量”是并列的两类量，不能说“长度的重量”。"}], "explanations": {"国际单位": "正确：国际单位是国际上统一规定的计量单位，米正是长度的国际单位。", "颜色": "语义：“长度”是可以度量的属性，“颜色”不是计量单位，“长度的颜色”说不通。", "语言": "语义：“语言”不是计量单位，“长度的语言”不成立。", "重量": "搭配：“长度”与“重量”是并列的两类量，不能说“长度的重量”。"}, "sentence_index": 0, "correct_answer": "国际单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项新技术已经成为国际单位。", "explanation": "这里应该用〈国际标准〉。“成为”后接的是被认可的标准或规范，国际单位是计量体系，不能说技术成为了它。"}, {"text": "我在一家大公司工作，那是一个很大的国际单位。", "explanation": "这里应该用〈单位〉（工作的机构）。“国际单位”只指计量单位，不指工作的机构。"}, {"text": "两国的国际单位一直很好。", "explanation": "这里应该用〈国际关系〉。“国际单位”指计量单位，不能用来描述两国之间的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际单位", "is_correct": true, "explanation": "正确：这里要求把数字换成国际统一的计量单位，“改成”后接的正是计量单位。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：数字可以改写成计量单位，不能改成歌曲。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：数字不能改成朋友，与“把数字改成”的意思不符。"}, {"text": "星星", "is_correct": false, "explanation": "搭配：“改成”需要表示形式或单位的词，“星星”不能作为数字的改写结果。"}], "explanations": {"国际单位": "正确：这里要求把数字换成国际统一的计量单位，“改成”后接的正是计量单位。", "歌曲": "语义：数字可以改写成计量单位，不能改成歌曲。", "朋友": "语义：数字不能改成朋友，与“把数字改成”的意思不符。", "星星": "搭配：“改成”需要表示形式或单位的词，“星星”不能作为数字的改写结果。"}, "sentence_index": 6, "correct_answer": "国际单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "联合国是世界上最重要的国际单位。", "explanation": "这里应该用〈国际组织〉。联合国是组织，“国际单位”只指计量单位。"}, {"text": "两国的国际单位每年都在增长。", "explanation": "这里应该用〈国际贸易〉。“增长”说的是贸易额，“国际单位”不能作为增长的主体。"}, {"text": "他是我最好的国际单位。", "explanation": "这里应该用〈朋友〉。“国际单位”是计量单位，不指人，不能用来指好朋友这样的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学会了一座国际单位的用法。", "corrected_sentence": "他学会了一个国际单位的用法。", "error_description": "量词错误：“国际单位”作为计量单位应用“个”计数；“座”用于山、楼等大型物体，这里用“座”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各种国际单位们都很有用。", "corrected_sentence": "各种国际单位都很有用。", "error_description": "“们”用错了：“们”只加在指人的名词后面，“国际单位”是事物，不能加“们”，应说“各种国际单位都很有用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94783, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
