INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学历是一个人在学校读书读到了哪一年级。", "primary_collocate": null, "pronunciation": "xué lì", "ipa": "ɕɥɛ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他只读到小学三年级，学历就停在这里。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "你的学历是初中还是高中？", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷没上过学，学历很低。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她高中只读到二年级，学历就到这里。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "表格上要写你的学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你的学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只读到初中，学历不高。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人小时候只上过一年级，学历停在那里。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "这个孩子读到小学四年级，学历还不够高。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "填表时，学历那一栏写“初中”。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高学历", "label": "复合"}, {"form": "低学历", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人读书读到哪一年级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学历", "is_correct": true, "explanation": "正确答案：学历（xué lì），指一个人在学校读书读到的阶段。"}, {"text": "学弟", "is_correct": false, "explanation": "学弟（xué dì）与 xué lì 声母不同（d 与 l），意思是比自己低一届的男同学。"}, {"text": "学系", "is_correct": false, "explanation": "学系（xué xì）与 xué lì 声母不同（x 与 l），意思是大学里的院系。"}, {"text": "雪梨", "is_correct": false, "explanation": "雪梨（xuě lí）与 xué lì 第一音节声调不同（第三声与第二声），意思是一种水果。"}, {"text": "学理", "is_correct": false, "explanation": "学理（xué lǐ）与 xué lì 第二音节声调不同（第三声与第四声），意思是理论上的道理。"}], "explanations": {"学历": "正确答案：学历（xué lì），指一个人在学校读书读到的阶段。", "学弟": "学弟（xué dì）与 xué lì 声母不同（d 与 l），意思是比自己低一届的男同学。", "学系": "学系（xué xì）与 xué lì 声母不同（x 与 l），意思是大学里的院系。", "雪梨": "雪梨（xuě lí）与 xué lì 第一音节声调不同（第三声与第二声），意思是一种水果。", "学理": "学理（xué lǐ）与 xué lì 第二音节声调不同（第三声与第四声），意思是理论上的道理。"}, "sentence_index": null, "correct_answer": "学历"}, "level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：指读书读到的阶段，与“只读到小学三年级”相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”指交的钱，不能说“学费就停在这里”，句子说的是读到哪个阶段。"}, {"text": "学位", "is_correct": false, "explanation": "语义：“学位”是大学授予的学术称号，小学三年级不能对应学位。"}, {"text": "学籍", "is_correct": false, "explanation": "搭配：“学籍”说注册、转入、保留，不说“停在这里”。"}], "explanations": {"学历": "学历：指读书读到的阶段，与“只读到小学三年级”相合。", "学费": "语义：“学费”指交的钱，不能说“学费就停在这里”，句子说的是读到哪个阶段。", "学位": "语义：“学位”是大学授予的学术称号，小学三年级不能对应学位。", "学籍": "搭配：“学籍”说注册、转入、保留，不说“停在这里”。"}, "sentence_index": 0, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国外工作过，有很多工作学历。", "explanation": "这里应该用〈经历〉。学历指受教育的阶段，工作的经历不能说成学历。"}, {"text": "他读书多，学历很丰富。", "explanation": "这里应该用〈学识〉。学历指受教育的阶段，说知识丰富要用学识。"}, {"text": "他的学历写了三页纸，把以前做过的工作都列了上去。", "explanation": "这里应该用〈履历〉。履历指个人的工作经过和简历，列出以前的工作要用履历；学历只指受教育的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：读到的最高阶段，与“只读到初中”相合，说“学历不高”。"}, {"text": "学籍", "is_correct": false, "explanation": "语义：“学籍”是学生在学校的注册身份，不能说“学籍不高”。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，和读到初中的学习经历无关，不能说“长相不高”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用高低来评价，“颜色不高”不成立。"}], "explanations": {"学历": "学历：读到的最高阶段，与“只读到初中”相合，说“学历不高”。", "学籍": "语义：“学籍”是学生在学校的注册身份，不能说“学籍不高”。", "长相": "体貌：“长相”指外貌，和读到初中的学习经历无关，不能说“长相不高”。", "颜色": "搭配：“颜色”不用高低来评价，“颜色不高”不成立。"}, "sentence_index": 6, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的学历很老，做了十年了。", "explanation": "这里应该用〈资历〉。学历指受教育的阶段，说工作年限和地位要用资历。"}, {"text": "他学历很广，去过很多国家。", "explanation": "这里应该用〈见识〉。学历指受教育的阶段，说见闻广要用见识。"}, {"text": "这座老房子的学历很长，有一百多年了。", "explanation": "这里应该用〈历史〉。学历指受教育的阶段，说建筑的年代要用历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他读到初中，一位学历就停在这里。", "corrected_sentence": "他读到初中，学历就停在这里。", "error_description": "错误：「学历」是抽象名词，不能用量词「位」计量（「位」用于人）。正确形式：他读到初中，学历就停在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的一位学历低得很，只读到初中。", "corrected_sentence": "她的学历低得很，只读到初中。", "error_description": "“位”用于指人，学历是抽象名词，不能用“位”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
