INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人在学校接受教育的经历，通常指最高的学习阶段。", "primary_collocate": null, "pronunciation": "xué lì", "ipa": "ɕɥɛ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "他的学历是大学本科。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作要求硕士学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有博士学历，工作很好。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司看重学历，也看重经验。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的最高学历是什么？", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学历越高，工资不一定越高。", "target_word": "学历", "complexity_tier": "T3", "furigana": "xué lì", "sentence_source": "generated"}, {"text": "他想提高学历，所以回学校读书。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，老板先问我的学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学历不高，但是很努力。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简历上要写清楚学历。", "target_word": "学历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高学历", "label": "复合"}, {"form": "低学历", "label": "复合"}], "register": "中性", "sense_fingerprint": "接受教育的最高阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学历", "is_correct": true, "explanation": "正确答案：学历（xué lì），指一个人接受教育的最高阶段。"}, {"text": "学弟", "is_correct": false, "explanation": "学弟（xué dì）与 xué lì 声母不同（d 与 l），意思是比自己低一届的男同学。"}, {"text": "学系", "is_correct": false, "explanation": "学系（xué xì）与 xué lì 声母不同（x 与 l），意思是大学里的院系。"}, {"text": "雪梨", "is_correct": false, "explanation": "雪梨（xuě lí）与 xué lì 第一音节声调不同（第三声与第二声），意思是一种水果。"}, {"text": "学理", "is_correct": false, "explanation": "学理（xué lǐ）与 xué lì 第二音节声调不同（第三声与第四声），意思是理论上的道理。"}], "explanations": {"学历": "正确答案：学历（xué lì），指一个人接受教育的最高阶段。", "学弟": "学弟（xué dì）与 xué lì 声母不同（d 与 l），意思是比自己低一届的男同学。", "学系": "学系（xué xì）与 xué lì 声母不同（x 与 l），意思是大学里的院系。", "雪梨": "雪梨（xuě lí）与 xué lì 第一音节声调不同（第三声与第二声），意思是一种水果。", "学理": "学理（xué lǐ）与 xué lì 第二音节声调不同（第三声与第四声），意思是理论上的道理。"}, "sentence_index": null, "correct_answer": "学历"}, "level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：受教育的最高阶段，与“大学本科”相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是交的钱，不能说“学费是大学本科”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用数字表示，不能说“年龄是大学本科”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，和“大学本科”毫不相关。"}], "explanations": {"学历": "学历：受教育的最高阶段，与“大学本科”相合。", "学费": "语义：“学费”是交的钱，不能说“学费是大学本科”。", "年龄": "搭配：“年龄”用数字表示，不能说“年龄是大学本科”。", "体重": "语义：“体重”指身体的重量，和“大学本科”毫不相关。"}, "sentence_index": 0, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的学历很快，一个上午就做完了。", "explanation": "这里应该用〈效率〉。学历指受教育的阶段，说做事快慢要用效率。"}, {"text": "他学历很广，去过很多国家。", "explanation": "这里应该用〈见识〉。学历指受教育的阶段，说见闻广要用见识。"}, {"text": "他的学历足足有三页纸，每份工作都写在上面。", "explanation": "这里应该用〈履历〉。履历指个人的工作经过，写下做过的工作要用履历；学历只指受教育的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学历", "is_correct": true, "explanation": "学历：可以提高的受教育水平，与“回学校读书”相合。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指外形，与“回学校读书”无关，不能为提高外貌而读书。"}, {"text": "脸色", "is_correct": false, "explanation": "配价：“提高”要求可以提升的水平或能力，“脸色”不能说提高。"}, {"text": "嗓子", "is_correct": false, "explanation": "配价：“嗓子”不是可以提高的对象，“提高嗓子”不成立。"}], "explanations": {"学历": "学历：可以提高的受教育水平，与“回学校读书”相合。", "外貌": "体貌：“外貌”指外形，与“回学校读书”无关，不能为提高外貌而读书。", "脸色": "配价：“提高”要求可以提升的水平或能力，“脸色”不能说提高。", "嗓子": "配价：“嗓子”不是可以提高的对象，“提高嗓子”不成立。"}, "sentence_index": 6, "correct_answer": "学历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的学历很老，在公司干了十年。", "explanation": "这里应该用〈资历〉。学历指受教育的阶段，说工作年限和地位要用资历。"}, {"text": "他学历很深，什么都懂。", "explanation": "这里应该用〈学问〉。学历指受教育的阶段，说知识深要用学问。"}, {"text": "这座老桥的学历很长，有几百年了。", "explanation": "这里应该用〈历史〉。学历指受教育的阶段，说桥梁的年代要用历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拿到了一颗硕士学历。", "corrected_sentence": "他拿到了硕士学历。", "error_description": "“颗”用于粒状的小东西，学历不能用“颗”计量，去掉量词即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的一位学历高得很，同事都很佩服。", "corrected_sentence": "她的学历高得很，同事都很佩服。", "error_description": "“位”用于指人，学历是抽象名词，不能用“位”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大生产", "is_correct": true, "explanation": "反义：小生产规模小，大生产规模大，两者在此义上相对。"}, {"text": "农业", "is_correct": false, "explanation": "无关：农业是行业名称，与小生产不构成反义。"}, {"text": "商品", "is_correct": false, "explanation": "无关：商品是产品，不是生产方式，没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "无关：学校是机构，与小生产的生产方式没有反义关系。"}], "correct_answer": "大生产", "explanations": {"大生产": "反义：小生产规模小，大生产规模大，两者在此义上相对。", "农业": "无关：农业是行业名称，与小生产不构成反义。", "商品": "无关：商品是产品，不是生产方式，没有反义关系。", "学校": "无关：学校是机构，与小生产的生产方式没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大生产", "is_correct": true, "explanation": "反义：小生产规模小，大生产规模大，两者在此义上相对。"}, {"text": "银行", "is_correct": false, "explanation": "无关：银行是金融机构，不是生产方式，不构成反义。"}, {"text": "教育", "is_correct": false, "explanation": "无关：教育是活动或领域，与小生产的生产规模没有反义关系。"}, {"text": "农民", "is_correct": false, "explanation": "无关：农民是人，不是生产方式，与小生产没有反义关系。"}], "correct_answer": "大生产", "explanations": {"大生产": "反义：小生产规模小，大生产规模大，两者在此义上相对。", "银行": "无关：银行是金融机构，不是生产方式，不构成反义。", "教育": "无关：教育是活动或领域，与小生产的生产规模没有反义关系。", "农民": "无关：农民是人，不是生产方式，与小生产没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以个人或家庭为单位、规模较小的生产方式。", "primary_collocate": null, "pronunciation": "xiǎo shēng chǎn", "ipa": "ɕiɑʊ̯˨˩ ʂɤŋ˥ ʈʂʰan˨˩", "syllable_count": 3, "sentences": [{"text": "小生产以个人或家庭为单位。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去农村的主要方式是小生产。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产的规模小，很难赚大钱。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大工厂出现以后，小生产慢慢减少了。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产常常靠家里人一起干活。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，小生产是一种古老的生产方式。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在课上讲了小生产与大生产的区别。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与大生产相比，小生产的成本更高。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小生产的工具比较简单。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家早期都有过小生产的阶段。", "target_word": "小生产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小生產", "label": "繁体"}, {"form": "小生产者", "label": "复合"}], "register": "书面", "sense_fingerprint": "以个人或家庭为单位、规模小的生产方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565bf980-d2e2-4df5-b6b9-3a7ffc1dbc87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小生产", "is_correct": true, "explanation": "正确：小生产以个人或家庭为单位，与句中定义一致。"}, {"text": "大工业", "is_correct": false, "explanation": "语义：大工业以大规模生产为特点，与“以个人或家庭为单位”矛盾。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂通常以企业为单位，不以个人或家庭为单位，与句子矛盾。"}, {"text": "生产线", "is_correct": false, "explanation": "搭配：“以……为单位”指组织方式，“生产线”是设备，不能作为单位。"}], "explanations": {"小生产": "正确：小生产以个人或家庭为单位，与句中定义一致。", "大工业": "语义：大工业以大规模生产为特点，与“以个人或家庭为单位”矛盾。", "工厂": "语义：工厂通常以企业为单位，不以个人或家庭为单位，与句子矛盾。", "生产线": "搭配：“以……为单位”指组织方式，“生产线”是设备，不能作为单位。"}, "sentence_index": 0, "correct_answer": "小生产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小生产有很多员工，每天都很忙。", "explanation": "这里应该用〈小企业〉。小生产指生产方式，不指企业或公司，不能说“这家小生产”。"}, {"text": "农民是一个小生产，在家里做鞋。", "explanation": "这里应该用〈小生产者〉。小生产指生产方式，指人时要说“小生产者”。"}, {"text": "他在街上做小生产，每天卖水果。", "explanation": "这里应该用〈小生意〉。卖水果是买卖经营，小生产指生产制造，不能用来指做买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小生产", "is_correct": true, "explanation": "正确：小生产是一种生产方式，可以与大生产比较区别，句意通顺。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是生产方式，不能与“大生产”比较区别。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是生产方式，不能与“大生产”作区别对比。"}, {"text": "天地", "is_correct": false, "explanation": "语义：“天地”不是生产方式，不能与“大生产”作区别对比。"}], "explanations": {"小生产": "正确：小生产是一种生产方式，可以与大生产比较区别，句意通顺。", "饭": "语义：饭不是生产方式，不能与“大生产”比较区别。", "名字": "语义：“名字”不是生产方式，不能与“大生产”作区别对比。", "天地": "语义：“天地”不是生产方式，不能与“大生产”作区别对比。"}, "sentence_index": 6, "correct_answer": "小生产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里来了一只小生产，专门做豆腐。", "explanation": "这里应该用〈种〉。小生产是一种生产方式，量词要用“种”，“只”不用于生产方式。"}, {"text": "我们车间的小生产每天能做几千件衣服。", "explanation": "这里应该用〈大生产〉。小生产规模小，每天几千件的产量要用大生产。"}, {"text": "她的小生产很精致，绣的花很漂亮。", "explanation": "这里应该用〈手艺〉。小生产指生产方式，不指个人的绣花技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子以前主要小生产生活。", "corrected_sentence": "这个村子以前主要靠小生产生活。", "error_description": "漏用介词“靠”：“靠”引出生活所依赖的方式，应说“靠小生产生活”，不能省去“靠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一家人在院子里做着一个小生产。", "corrected_sentence": "他们一家人在院子里做着一种小生产。", "error_description": "量词错误：“小生产”是生产方式，应该用“种”计量，不能用“个”。正确说法是“做着一种小生产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '311212b8-243d-4bdb-869f-c8a6d227e1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
