INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成事是把一件事做好了。", "primary_collocate": null, "pronunciation": "chéng shì", "ipa": "ʈʂʰɤŋ³⁵ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "谋事在人，成事在天。", "target_word": "成事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只会说大话，成事不足，败事有余。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事认真的人，往往能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光有想法不行，行动起来才能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事太马虎，很难成事。", "target_word": "成事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想要成事，先要把准备做好。", "target_word": "成事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人别着急，慢慢来才能成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，细心的孩子长大后更容易成事。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成事靠的是坚持，不是运气。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公司里，他是个能成事的人。", "target_word": "成事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "把一件事做好、做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13c58d25-1eb8-4b9e-9181-3173d9fab08e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：与前句“谋事”相对，“成事在天”指事情能否办成由天决定。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：前句说谋划事情，后句应说事情的成败，“吃饭在天”与成败无关，句子不通。"}, {"text": "干活", "is_correct": false, "explanation": "语域：“干活”是口语，与这句谚语的书面语体不合。语义上也与前句的“谋事”不相称。"}, {"text": "管理", "is_correct": false, "explanation": "语义：“管理”指统筹安排，与“天”决定成败的意思不合，“管理在天”说不通。"}], "explanations": {"成事": "正确：与前句“谋事”相对，“成事在天”指事情能否办成由天决定。", "吃饭": "语义：前句说谋划事情，后句应说事情的成败，“吃饭在天”与成败无关，句子不通。", "干活": "语域：“干活”是口语，与这句谚语的书面语体不合。语义上也与前句的“谋事”不相称。", "管理": "语义：“管理”指统筹安排，与“天”决定成败的意思不合，“管理在天”说不通。"}, "sentence_index": 0, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他成事很稳，大家都信任他。", "explanation": "这里应该用〈办事〉。办事指处理事务的过程，“成事”强调事情办成的结果，不能用来形容做事的过程。"}, {"text": "这座桥三年内就能成事。", "explanation": "这里应该用〈建成〉。成事指人把事情办成，桥梁、建筑完工要说“建成”。"}, {"text": "这件衣服下周就能成事。", "explanation": "这里应该用〈做好〉。成事的对象是事务，衣服做好要说“做好”，“成事”不用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成事", "is_correct": true, "explanation": "正确：“才能”后接“成事”，表示办成事情这一正面结果。"}, {"text": "失败", "is_correct": false, "explanation": "语义：前句鼓励慢慢来，“慢慢来才能失败”与句意相反。"}, {"text": "着急", "is_correct": false, "explanation": "搭配：“才能”后接结果动词，“着急”是心理状态，且与前句“别着急”重复，不能作结果。"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：慢慢来不会导致吃亏，此处“才能”要接正面结果，“吃亏”与句意不合。"}], "explanations": {"成事": "正确：“才能”后接“成事”，表示办成事情这一正面结果。", "失败": "语义：前句鼓励慢慢来，“慢慢来才能失败”与句意相反。", "着急": "搭配：“才能”后接结果动词，“着急”是心理状态，且与前句“别着急”重复，不能作结果。", "吃亏": "语义：慢慢来不会导致吃亏，此处“才能”要接正面结果，“吃亏”与句意不合。"}, "sentence_index": 6, "correct_answer": "成事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的理想终于成事了。", "explanation": "这里应该用〈实现〉。成事指人把具体事情办成，理想要说“实现”，不说“成事”。"}, {"text": "这锅汤她一小时就成事了。", "explanation": "这里应该用〈煮好〉。成事用于办理事务，煮汤这类具体的家务要说“煮好”。"}, {"text": "这台电脑他下午就成事了。", "explanation": "这里应该用〈修好〉。成事指把事情办成，电器等具体物件修好要说“修好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于成事了了。", "corrected_sentence": "他终于成事了。", "error_description": "错误：句末多写了一个“了”，说成“成事了了”。“了”只用一次，应说“成事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没成事过。", "corrected_sentence": "他从来没成过事。", "error_description": "错误：“过”应放在离合词“成”和“事”之间，说“成过事”；“成事过”的位置不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
