INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数据库是电脑里放很多信息的大柜子。", "primary_collocate": null, "pronunciation": "shù jù kù", "ipa": "ʂu˥˩ tɕy˥˩ kʰu˥˩", "syllable_count": 3, "sentences": [{"text": "电脑里有一个数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的数据库里有学生的信息。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把名字放进了数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据库很大，放了很多信息。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据库里的信息很安全。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在数据库里找一个电话号码。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买了一个新数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的数据库里有病人的资料。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都往数据库里加新信息。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据库坏了，我们找不到资料。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "电脑里存放很多信息的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据库", "is_correct": true, "explanation": "数据库：电脑里存放信息的地方，与“电脑里”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是冷藏食物的家电，电脑里不会有一个冰箱。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：“鱼缸”是养鱼的容器，不能放在电脑里。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间”是实际的空间，电脑里存信息不说“有一个房间”，应说“文件夹”等。"}], "explanations": {"数据库": "数据库：电脑里存放信息的地方，与“电脑里”相合。", "冰箱": "语义：“冰箱”是冷藏食物的家电，电脑里不会有一个冰箱。", "鱼缸": "语义：“鱼缸”是养鱼的容器，不能放在电脑里。", "房间": "搭配：“房间”是实际的空间，电脑里存信息不说“有一个房间”，应说“文件夹”等。"}, "sentence_index": 0, "correct_answer": "数据库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把成品都放进了数据库里。", "explanation": "这里应该用〈仓库〉。数据库存的是信息，成品这类实物要放进仓库。"}, {"text": "这个新数据库很大，专门用来放衣服。", "explanation": "这里应该用〈衣柜〉。数据库存放的是信息，放衣服要用衣柜。"}, {"text": "我把袜子放在数据库里。", "explanation": "这里应该用〈抽屉〉。抽屉用来放衣物等实物，数据库只存放信息，不能放袜子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据库", "is_correct": true, "explanation": "数据库：可以买的存储系统，与“公司买了一个新”相合。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“天气”不是能买的东西，“买了一个新天气”不成立。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”是地方话，不是能买的东西，“买了一个新方言”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”不是能买的东西，“买了一个新脾气”不成立。"}], "explanations": {"数据库": "数据库：可以买的存储系统，与“公司买了一个新”相合。", "天气": "配价：“天气”不是能买的东西，“买了一个新天气”不成立。", "方言": "语义：“方言”是地方话，不是能买的东西，“买了一个新方言”不成立。", "脾气": "配价：“脾气”不是能买的东西，“买了一个新脾气”不成立。"}, "sentence_index": 6, "correct_answer": "数据库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数据库很快，能同时打开很多软件。", "explanation": "这里应该用〈电脑〉。数据库只存放和整理信息，不能打开软件。"}, {"text": "我们在客厅买了一个新数据库，专门用来摆书。", "explanation": "这里应该用〈书架〉。数据库是存储信息的系统，摆书要用书架。"}, {"text": "我每天都打开数据库看信。", "explanation": "这里应该用〈邮箱〉。邮箱用来收发信件，数据库不是收信的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司有一张数据库，存着客户的信息。", "corrected_sentence": "我们公司有一个数据库，存着客户的信息。", "error_description": "错误形式“一张数据库”，正确形式“一个数据库”。“张”用于纸张、桌子等平面或扁平的物体，数据库要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院新建了一本数据库，方便查资料。", "corrected_sentence": "医院新建了一个数据库，方便查资料。", "error_description": "错误形式“一本数据库”，正确形式“一个数据库”。“本”用于书、本子等，数据库要用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
