INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按一定方式组织并存储在计算机中的大量数据的集合。", "primary_collocate": null, "pronunciation": "shù jù kù", "ipa": "ʂu˥˩ tɕy˥˩ kʰu˥˩", "syllable_count": 3, "sentences": [{"text": "这家银行的数据库保存着客户的数据。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在设计新的数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据库需要密码才能打开。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用数据库来存放销售数据。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据库的查询速度很快。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据库有上亿条记录。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习编程时，也要学数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的数据库要定期备份。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧数据导入了新数据库。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据库里的表格按类别整理。", "target_word": "数据库", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "按方式组织存储的大量数据集合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a9e6c79-9a64-4e29-86b7-f0772555b1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据库", "is_correct": true, "explanation": "数据库：存放客户数据的系统，与“保存着客户的数据”相合。"}, {"text": "金库", "is_correct": false, "explanation": "语义：“金库”存放金银财宝，不是保存客户数据的地方。"}, {"text": "存折", "is_correct": false, "explanation": "搭配：“保存”的对象多是文件、数据，“存折”只记账户，不说保存客户的数据。"}, {"text": "营业厅", "is_correct": false, "explanation": "语义：“营业厅”是办理业务的场所，不能保存数据。"}], "explanations": {"数据库": "数据库：存放客户数据的系统，与“保存着客户的数据”相合。", "金库": "语义：“金库”存放金银财宝，不是保存客户数据的地方。", "存折": "搭配：“保存”的对象多是文件、数据，“存折”只记账户，不说保存客户的数据。", "营业厅": "语义：“营业厅”是办理业务的场所，不能保存数据。"}, "sentence_index": 0, "correct_answer": "数据库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数据库里放着牛奶和鸡蛋。", "explanation": "这里应该用〈冰箱〉。数据库存放的是信息，牛奶和鸡蛋要放在冰箱里。"}, {"text": "这家公司新买的数据库很高，专门用来摆放书。", "explanation": "这里应该用〈书架〉。数据库存放的是信息，摆放书要用书架。"}, {"text": "数据库里挂满了衣服。", "explanation": "这里应该用〈衣柜〉。数据库存放信息，衣服要挂在衣柜里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据库", "is_correct": true, "explanation": "数据库：需要学习的知识，与“学习编程”相合。"}, {"text": "嗓子", "is_correct": false, "explanation": "配价：“学”的对象须是知识或技能，“嗓子”不能学。"}, {"text": "外形", "is_correct": false, "explanation": "体貌：“外形”指外表，不是可以学习的内容。"}, {"text": "脸蛋", "is_correct": false, "explanation": "配价：“脸蛋”也不能学，“学脸蛋”不成立。"}], "explanations": {"数据库": "数据库：需要学习的知识，与“学习编程”相合。", "嗓子": "配价：“学”的对象须是知识或技能，“嗓子”不能学。", "外形": "体貌：“外形”指外表，不是可以学习的内容。", "脸蛋": "配价：“脸蛋”也不能学，“学脸蛋”不成立。"}, "sentence_index": 6, "correct_answer": "数据库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的数据库每天都要寄出很多包裹。", "explanation": "这里应该用〈邮局〉。数据库只存储信息，不寄包裹，寄包裹要用邮局。"}, {"text": "我们在门口建了一个数据库，专门用来停汽车。", "explanation": "这里应该用〈车库〉。数据库存放的是数据，停汽车要用车库。"}, {"text": "数据库里有很多新鲜的食材。", "explanation": "这里应该用〈冰箱〉。数据库存放信息，新鲜食材要放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家银行新建了一幅数据库，用来保存客户的资料。", "corrected_sentence": "这家银行新建了一个数据库，用来保存客户的资料。", "error_description": "错误形式“一幅数据库”，正确形式“一个数据库”。“幅”用于字画、照片，不能修饰数据库，数据库要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把一根数据库上传到了服务器。", "corrected_sentence": "学校把一个数据库上传到了服务器。", "error_description": "“根”用于长条形的东西，数据库要用“个”，“一根数据库”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'feec9883-baec-4df8-870d-1df28a28c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
