INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "格式是东西排好的样子和规矩。", "primary_collocate": null, "pronunciation": "gé shì", "ipa": "kɤ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这张表的格式很清楚，一看就懂。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按这个格式把名字写在上面。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书每一页的格式都一样。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单的格式太乱，客人找不到想吃的菜。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们改一下作业的格式。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信的格式有规矩，开头要写称呼。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页的格式设计得很整齐。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要改变原来的格式。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写请假条也有一定的格式。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几张海报格式不同，放在一起不好看。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物排列安排的样子和固定规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "格式", "is_correct": true, "explanation": "格式 gé shì：东西排好的样子和规矩，是正确答案。"}, {"text": "各式", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，意思是各种样式，不是格式。"}, {"text": "合适", "is_correct": false, "explanation": "hé（第二声）与 gé 声母不同（h 与 g），声调相同，意思是恰当，不是格式。"}, {"text": "德式", "is_correct": false, "explanation": "dé（第二声）与 gé 声母不同（d 与 g），声调相同，意思是德国式的，不是格式。"}], "explanations": {"格式": "格式 gé shì：东西排好的样子和规矩，是正确答案。", "各式": "gè（第四声）与 gé（第二声）声调不同，意思是各种样式，不是格式。", "合适": "hé（第二声）与 gé 声母不同（h 与 g），声调相同，意思是恰当，不是格式。", "德式": "dé（第二声）与 gé 声母不同（d 与 g），声调相同，意思是德国式的，不是格式。"}, "sentence_index": null, "correct_answer": "格式"}, "level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”靠嗅觉和味觉感知，不能说“清楚”，也不能“一看就懂”。"}, {"text": "格式", "is_correct": true, "explanation": "格式指表格排列的规矩和样子，“很清楚”“一看就懂”都说得通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：表格没有年龄，“年龄很清楚”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”要靠听，不能和“一看就懂”搭配。"}], "explanations": {"味道": "语义：“味道”靠嗅觉和味觉感知，不能说“清楚”，也不能“一看就懂”。", "格式": "格式指表格排列的规矩和样子，“很清楚”“一看就懂”都说得通。", "年龄": "语义：表格没有年龄，“年龄很清楚”说不通。", "声音": "语义：“声音”要靠听，不能和“一看就懂”搭配。"}, "sentence_index": 0, "correct_answer": "格式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情格式很好，大家都很高兴。", "explanation": "这里应该用〈心情〉。格式指东西排列的样子和规矩，人的情绪要说心情。"}, {"text": "这件衣服的格式很新颖，今年最流行。", "explanation": "这里应该用〈款式〉。格式指规定的排列样子，衣服的样式和花样要说款式。"}, {"text": "他说话的格式很幽默，大家都爱听。", "explanation": "这里应该用〈风格〉。格式是固定的排列规矩，说话的特点要说风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "格式", "is_correct": true, "explanation": "格式 gé shì：东西排好的样子和规矩，是正确答案。"}, {"text": "和式", "is_correct": false, "explanation": "h 与 g 声母不同，声调相同，意思是日本式的样子，不是格式。"}, {"text": "博士", "is_correct": false, "explanation": "bó（第二声）与 gé 声母不同（b 与 g），声调相同，意思是学位或其持有者，不是格式。"}, {"text": "得势", "is_correct": false, "explanation": "d 与 g 声母不同，声调相同，意思是取得权势或优势，不是格式。"}], "explanations": {"格式": "格式 gé shì：东西排好的样子和规矩，是正确答案。", "和式": "h 与 g 声母不同，声调相同，意思是日本式的样子，不是格式。", "博士": "bó（第二声）与 gé 声母不同（b 与 g），声调相同，意思是学位或其持有者，不是格式。", "得势": "d 与 g 声母不同，声调相同，意思是取得权势或优势，不是格式。"}, "sentence_index": null, "correct_answer": "格式"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：网页没有年龄，不能被“设计”得整齐。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，网页不能设计脾气。"}, {"text": "格式", "is_correct": true, "explanation": "格式指网页内容排列的样子，可以被“设计”得很整齐。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指人的容貌，不能用于网页。"}], "explanations": {"年龄": "语义：网页没有年龄，不能被“设计”得整齐。", "脾气": "语义：“脾气”是人的性情，网页不能设计脾气。", "格式": "格式指网页内容排列的样子，可以被“设计”得很整齐。", "相貌": "体貌：“相貌”指人的容貌，不能用于网页。"}, "sentence_index": 6, "correct_answer": "格式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的格式很快，听得人心跳加速。", "explanation": "这里应该用〈节奏〉。格式指规定的排列样子，歌曲快慢的变化要说节奏。"}, {"text": "他的格式很工整，每个字都写得清楚。", "explanation": "这里应该用〈笔迹〉。格式指规定的排列，一个人写字的特点要说笔迹。"}, {"text": "这封信的格式很温柔，读完让人想哭。", "explanation": "这里应该用〈语气〉。格式指文件的规定样式，信里的情感要说语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张表用了一只格式，一看就懂。", "corrected_sentence": "这张表用了一种格式，一看就懂。", "error_description": "“格式”前的量词应用“种”。“只”多用于动物或成对物件中的一件，不能用于“格式”。“一只格式”是错的，应改为“一种格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网页的格式制造得很整齐。", "corrected_sentence": "这个网页的格式设置得很整齐。", "error_description": "“格式”应与“设置、设计、制定”搭配，“制造”不能用于“格式”。应改为“设置”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
