INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文件、文章等按规定形成的样式和规格。", "primary_collocate": null, "pronunciation": "gé shì", "ipa": "kɤ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "论文的格式要按学校的规定来写。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文件的格式不支持，请换一个。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文章的格式改成了老师要的样子。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "简历的格式要简单，别太花。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司规定，所有报告都要用同一种格式。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提交申请前，请检查表格格式对不对。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章格式不对，要重新排版。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同的格式有固定要求，不能随便写。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份通知的格式很正式，标题和日期都不能少。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按规定的格式写报告，题目放在中间。", "target_word": "格式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "文件、文章等按规定形成的样式和规格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a252ca3-929a-4eff-b85c-7b311aaea147') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "格式", "is_correct": true, "explanation": "格式 gé shì：文件或文章按规定形成的样式，是正确答案。"}, {"text": "各式", "is_correct": false, "explanation": "gè（第四声）与 gé（第二声）声调不同，意思是各种样式，不是格式。"}, {"text": "博士", "is_correct": false, "explanation": "bó（第二声）与 gé 声母不同（b 与 g），声调相同，意思是学位或其持有者，不是格式。"}, {"text": "德式", "is_correct": false, "explanation": "dé 与 gé 声母不同（d 与 g），声调相同，意思是德国式的。"}], "explanations": {"格式": "格式 gé shì：文件或文章按规定形成的样式，是正确答案。", "各式": "gè（第四声）与 gé（第二声）声调不同，意思是各种样式，不是格式。", "博士": "bó（第二声）与 gé 声母不同（b 与 g），声调相同，意思是学位或其持有者，不是格式。", "德式": "dé 与 gé 声母不同（d 与 g），声调相同，意思是德国式的。"}, "sentence_index": null, "correct_answer": "格式"}, "level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，论文没有身材，不能这样说。"}, {"text": "格式", "is_correct": true, "explanation": "格式指文章的规定样式，论文“要按学校的规定来写”正好说得通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，论文没有脾气，不能按规定来写。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：论文没有年纪，不能“按学校的规定来写”。"}], "explanations": {"身材": "体貌：“身材”指人的体形，论文没有身材，不能这样说。", "格式": "格式指文章的规定样式，论文“要按学校的规定来写”正好说得通。", "脾气": "语义：“脾气”是人的性情，论文没有脾气，不能按规定来写。", "年纪": "语义：论文没有年纪，不能“按学校的规定来写”。"}, "sentence_index": 0, "correct_answer": "格式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的格式很高，比同学都高一截。", "explanation": "这里应该用〈个子〉。格式指文件或文章的规定样式，人的高矮要说个子。"}, {"text": "这双鞋的格式很新，颜色也好看。", "explanation": "这里应该用〈款式〉。格式指规定的样式，鞋子的样子要说款式。"}, {"text": "这份报告的格式很香，大家都想读。", "explanation": "这里应该用〈内容〉。格式指文件的规定样式，报告写得好不好要说内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "格式", "is_correct": true, "explanation": "格式 gé shì：文件或文章按规定形成的样式，是正确答案。"}, {"text": "和式", "is_correct": false, "explanation": "h 与 g 声母不同，声调相同，意思是日本式的样子，不是格式。"}, {"text": "得势", "is_correct": false, "explanation": "d 与 g 声母不同，声调相同，意思是取得权势或优势，不是格式。"}, {"text": "合适", "is_correct": false, "explanation": "hé（第二声）与 gé 声母不同（h 与 g），声调相同，意思是恰当，不是格式。"}], "explanations": {"格式": "格式 gé shì：文件或文章按规定形成的样式，是正确答案。", "和式": "h 与 g 声母不同，声调相同，意思是日本式的样子，不是格式。", "得势": "d 与 g 声母不同，声调相同，意思是取得权势或优势，不是格式。", "合适": "hé（第二声）与 gé 声母不同（h 与 g），声调相同，意思是恰当，不是格式。"}, "sentence_index": null, "correct_answer": "格式"}, "level_3": {"options": [{"text": "性别", "is_correct": false, "explanation": "语义：文章没有性别，不能说“性别不对”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：文章没有体重，“体重不对”说不通。"}, {"text": "格式", "is_correct": true, "explanation": "格式指文章的排列样子，不对就要重新排版，说得通。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指人的气色，不能用来说文章“脸色不对”。"}], "explanations": {"性别": "语义：文章没有性别，不能说“性别不对”。", "体重": "语义：文章没有体重，“体重不对”说不通。", "格式": "格式指文章的排列样子，不对就要重新排版，说得通。", "脸色": "体貌：“脸色”指人的气色，不能用来说文章“脸色不对”。"}, "sentence_index": 6, "correct_answer": "格式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的格式很感人，读完让人流泪。", "explanation": "这里应该用〈内容〉。格式指文章的规定样式，文章的感人之处要说内容。"}, {"text": "这首曲子的格式很稳，节奏听起来很舒服。", "explanation": "这里应该用〈节拍〉。格式指规定的样式，音乐的强弱快慢要说节拍。"}, {"text": "这家餐厅的格式很周到，服务员一直笑着。", "explanation": "这里应该用〈接待〉。格式指规定的样式，待客的态度和方式要说接待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份通知用了一只格式，很规范。", "corrected_sentence": "这份通知用了一种格式，很规范。", "error_description": "“格式”前的量词应用“种”。“只”多用于动物或成对物件中的一件，不能用于“格式”。“一只格式”是错的，应改为“一种格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇论文的格式制造得很规范。", "corrected_sentence": "这篇论文的格式制定得很规范。", "error_description": "“格式”应与“制定、设置”搭配，“制造”不能用于“格式”。应改为“制定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82d1cd87-ded3-40be-b7df-fd1562fb4219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
