INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94815, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "树立是把一个好的东西建起来，让大家看见。", "primary_collocate": null, "pronunciation": "shù lì", "ipa": "ʂu⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "广场中间树立着一座英雄纪念碑。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在班里树立了一个好榜样。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想给弟弟树立一个好榜样。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把这位老员工树立成大家学习的榜样。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口树立起一块新牌子，大家都看得见。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校树立了很多学习好的同学做榜样。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长要先做好，才能给孩子树立榜样。", "target_word": "树立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边树立着一块牌子，上面写着“慢行”。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里树立过一座老人的雕像。", "target_word": "树立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学校门口树立了一块石碑，上面刻着校训。", "target_word": "树立", "complexity_tier": "T3", "furigana": "shùlì", "sentence_source": "generated"}], "morphological_forms": [{"form": "树立了", "label": "体标"}, {"form": "树立过", "label": "体标"}, {"form": "樹立", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "把好的东西立起来，让大家看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13c58d25-1eb8-4b9e-9181-3173d9fab08e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94815, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指把好的东西立起来，让大家看见。"}, {"text": "数理", "is_correct": false, "explanation": "声调不同：lǐ 为第三声，lì 为第四声。数理意思是数学的道理。"}, {"text": "树篱", "is_correct": false, "explanation": "声调不同：lí 为第二声，lì 为第四声。树篱意思是密植成墙的树木。"}, {"text": "书吏", "is_correct": false, "explanation": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。"}], "explanations": {"树立": "正确：听到的是“树立”，指把好的东西立起来，让大家看见。", "数理": "声调不同：lǐ 为第三声，lì 为第四声。数理意思是数学的道理。", "树篱": "声调不同：lí 为第二声，lì 为第四声。树篱意思是密植成墙的树木。", "书吏": "声调不同：shū 为第一声，shù 为第四声。书吏意思是旧时官府中抄写文书的小吏。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立着”表示纪念碑竖立在广场上，供人观看。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：挖掘多用于地下的东西，与立在地面的纪念碑不符。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，纪念碑不能被烤，句子不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”多与食物、可分割的物体连用，与“纪念碑”不相配。"}], "explanations": {"树立": "正确：“树立着”表示纪念碑竖立在广场上，供人观看。", "挖掘": "语义：挖掘多用于地下的东西，与立在地面的纪念碑不符。", "烤": "语义：“烤”是加热食物，纪念碑不能被烤，句子不通。", "切": "搭配：“切”多与食物、可分割的物体连用，与“纪念碑”不相配。"}, "sentence_index": 0, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们去年在城里树立了一家公司。", "explanation": "这里应该用〈建立〉。树立用于形象、风气、榜样，公司、组织要说“建立”。"}, {"text": "客厅中间树立着一张大桌子。", "explanation": "这里应该用〈摆放〉。桌子是家具，要说“摆放”，“树立”只用于立起来供人看的标志或榜样，不能用于家具。"}, {"text": "这个社区去年树立了一项奖学金。", "explanation": "这里应该用〈设立〉。奖学金、机构要说“设立”，“树立”不用于这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94815, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：听到的是“树立”，指把好的东西立起来，让大家看见。"}, {"text": "熟栗", "is_correct": false, "explanation": "声调不同：shú 为第二声，shù 为第四声。熟栗意思是煮熟或炒熟的栗子。"}, {"text": "属吏", "is_correct": false, "explanation": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。"}, {"text": "书立", "is_correct": false, "explanation": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}], "explanations": {"树立": "正确：听到的是“树立”，指把好的东西立起来，让大家看见。", "熟栗": "声调不同：shú 为第二声，shù 为第四声。熟栗意思是煮熟或炒熟的栗子。", "属吏": "声调不同：shǔ 为第三声，shù 为第四声。属吏意思是隶属于官府的下级官吏。", "书立": "第一音节声调不同：shū 为第一声，shù 为第四声，意思是书挡。"}, "sentence_index": null, "correct_answer": "树立"}, "level_3": {"options": [{"text": "树立", "is_correct": true, "explanation": "正确：“树立榜样”指为孩子确立可以效仿的人。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“给孩子吃榜样”不合常理，与“做好”的语境不符。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”与前句“做好”的正面语境相反，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”与“榜样”不相配，二者语义无关。"}], "explanations": {"树立": "正确：“树立榜样”指为孩子确立可以效仿的人。", "吃": "语义：“给孩子吃榜样”不合常理，与“做好”的语境不符。", "抛弃": "语义：“抛弃”与前句“做好”的正面语境相反，句意不通。", "测量": "搭配：“测量”与“榜样”不相配，二者语义无关。"}, "sentence_index": 6, "correct_answer": "树立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在门口树立了一台新机器。", "explanation": "这里应该用〈安装〉。树立用于形象、榜样，机器要说“安装”。"}, {"text": "这位老师在城里树立了一门课程。", "explanation": "这里应该用〈开设〉。课程要说“开设”，“树立”不用于课程。"}, {"text": "展厅里树立了很多鲜花。", "explanation": "这里应该用〈摆放〉。鲜花要说“摆放”，“树立”只用于立起来供人看的标志或榜样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校园里树立了着一尊雕像。", "corrected_sentence": "校园里树立着一尊雕像。", "error_description": "错误：“了”和“着”不能同时用于“树立”，表示持续状态只用“着”，应说“树立着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf18d68-bcb4-4cb1-8f35-be66d6e32d63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
